export default "arch_client)\\n\\n        # Verify models are detected from the aggregations\\n        assert \\\"text-embedding-3-small\\\" in models\\n        assert \\\"text-embedding-3-large\\\" in models\\n        assert len(models) == 2\\n\\n    def test_authentication_basic(self, component_class):\\n        \\\"\\\"\\\"Test basic authentication configuration.\\\"\\\"\\\"\\n        component = component_class().set(\\n            opensearch_url=\\\"http://localhost:9200\\\",\\n            index_name=\\\"test_index\\\",\\n            embedding=MockEmbeddings(),\\n            auth_mode=\\\"basic\\\",\\n            username=\\\"test_user\\\",\\n            password=\\\"test_password\\\",  # pragma: allowlist secret  # noqa: S106\\n        )\\n\\n        assert component._build_auth_kwargs() == {\\\"http_auth\\\": (\\\"test_user\\\", \\\"test_password\\\")}\\n\\n    def test_authentication_jwt(self, component_class):\\n        \\\"\\\"\\\"Test JWT authentication without a Bearer prefix.\\\"\\\"\\\"\\n        component = component_class().set(\\n            opensearch_url=\\\"http://localhost:9200\\\",\\n            index_name=\\\"test_index\\\",\\n            embedding=MockEmbeddings(),\\n            auth_mode=\\\"jwt\\\",\\n            jwt_token=\\\"test_jwt_token\\\",  # pragma: allowlist secret  # noqa: S106\\n            jwt_header=\\\"Authorization\\\",\\n            bearer_prefix=False,\\n        )\\n\\n        assert component._build_auth_kwargs() == {\\\"headers\\\": {\\\"Authorization\\\": \\\"test_jwt_token\\\"}}\\n\\n    def test_authentication_jwt_with_bearer_prefix(self, component_class):\\n        \\\"\\\"\\\"Test JWT authentication with a Bearer prefix.\\\"\\\"\\\"\\n        component = component_class().set(\\n            opensearch_url=\\\"http://localhost:9200\\\",\\n            index_name=\\\"test_index\\\",\\n            embedding=MockEmbeddings(),\\n            auth_mode=\\\"jwt\\\",\\n            jwt_token=\\\"test_jwt_token\\\",  # pragma: allowlist secret  # noqa: S106\\n            jwt_header=\\\"Authorization\\\",\\n            bearer_prefix=True,\\n        )\\n\\n        assert component._build_auth_kwargs() == {\\\"headers\\\": {\\\"Authorization\\\": \\\"Bearer test_jwt_token\\\"}}\\n\\n    def test_default_auth_mode_and_bearer_prefix_inputs(self, component_class):\\n        \\\"\\\"\\\"Test default auth-mode related input values for new instances.\\\"\\\"\\\"\\n        component = component_class()\\n        auth_mode_input = next(field for field in component.inputs if field.name == \\\"auth_mode\\\")\\n        bearer_prefix_input = next(field for field in component.inputs if field.name == \\\"bearer_prefix\\\")\\n\\n        assert auth_mode_input.value == \\\"jwt\\\"\\n        assert bearer_prefix_input.value is False\\n\\n    def test_raw_search_applies_filter_expression(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test raw_search applies filter clauses, limit, and score threshold from filter_expression.\\\"\\\"\\\"\\n        client = MagicMock()\\n        client.search.return_value = {\\\"hits\\\": {\\\"hits\\\": []}}\\n        component = component_class().set(\\n            **default_kwargs,\\n            filter_expression='{\\\"filter\\\":[{\\\"term\\\":{\\\"owner\\\":\\\"user1\\\"}}],\\\"limit\\\":3,\\\"score_threshold\\\":1.2}',\\n        )\\n\\n        with patch.object(component, \\\"build_client\\\", return_value=client):\\n            component.raw_search({\\\"query\\\": {\\\"match\\\": {\\\"text\\\": \\\"python\\\"}}})\\n\\n        body = client.search.call_args.kwargs[\\\"body\\\"]\\n        assert body[\\\"query\\\"][\\\"bool\\\"][\\\"must\\\"] == [{\\\"match\\\": {\\\"text\\\": \\\"python\\\"}}]\\n        assert body[\\\"query\\\"][\\\"bool\\\"][\\\"filter\\\"] == [{\\\"term\\\": {\\\"owner\\\": \\\"user1\\\"}}]\\n        assert body[\\\"size\\\"] == 3\\n        assert body[\\\"min_score\\\"] == 1.2\\n\\n    def test_raw_search_invalid_filter_expression_json_raises(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test raw_search raises ValueError for invalid filter_expression JSON.\\\"\\\"\\\"\\n        component = component_class().set(**default_kwargs, filter_expression='{\\\"filter\\\": [}')\\n        with pytest.raises(ValueError, match=\\\"Invalid filter_expression JSON\\\"):\\n            component.raw_search({\\\"query\\\": {\\\"match_all\\\": {}}})\\n\\n    def test_raw_search_filter_expression_requires_json_object(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test raw_search rejects non-object JSON filter_expression values.\\\"\\\"\\\"\\n        component = component_class().set(**default_kwargs, filter_expression='[\\\"owner\\\"]')\\n        with pytest.raises(TypeError, match=\\\"expected a JSON object\\\"):\\n            component.raw_search({\\\"query\\\": {\\\"match_all\\\": {}}})\\n\\n    def test_raw_search_does_not_mutate_input_query_dict(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test raw_search does not mutate caller-provided query dicts.\\\"\\\"\\\"\\n        client = MagicMock()\\n        client.search.return_value = {\\\"hits\\\": {\\\"hits\\\": []}}\\n        component = component_class().set(\\n            **default_kwargs,\\n            filter_expression='{\\\"filter\\\":[{\\\"term\\\":{\\\"owner\\\":\\\"user1\\\"}}],\\\"limit\\\":2}',\\n        )\\n        raw_query = {\\\"query\\\": {\\\"match\\\": {\\\"text\\\": \\\"python\\\"}}}\\n        original_query = copy.deepcopy(raw_query)\\n\\n        with patch.object(component, \\\"build_client\\\", return_value=client):\\n            component.raw_search(raw_query)\\n\\n        assert raw_query == original_query\\n\\n    def test_raw_search_rejects_non_integer_limit(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test raw_search rejects invalid non-integer filter limit values.\\\"\\\"\\\"\\n        component = component_class().set(**default_kwargs, filter_expression='{\\\"limit\\\":\\\"abc\\\"}')\\n        with pytest.raises(ValueError, match=r\\\"filter_expression\\\\.limit\\\"):\\n            component.raw_search({\\\"query\\\": {\\\"match_all\\\": {}}})\\n\\n    async def test_update_build_config_auth_basic(self, component_class):\\n        \\\"\\\"\\\"Test update_build_config with basic authentication.\\\"\\\"\\\"\\n        component = component_class()\\n        build_config = {\\n            \\\"username\\\": {\\\"required\\\": False, \\\"show\\\": False},\\n            \\\"password\\\": {\\\"required\\\": False, \\\"show\\\": False},\\n            \\\"jwt_token\\\": {\\\"required\\\": False, \\\"show\\\": False},\\n            \\\"bearer_token\\\": {\\\"required\\\": False, \\\"show\\\": False},\\n            \\\"bearer_prefix\\\": {\\\"required\\\": False, \\\"show\\\": False},\\n            \\\"jwt_header\\\": {\\\"required\\\": False, \\\"show\\\": False},\\n        }\\n\\n        updated_config = await component.update_build_config(build_config, \\\"basic\\\", \\\"auth_mode\\\")\\n\\n        # Verify basic auth fields are visible and required\\n        assert updated_config[\\\"username\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"username\\\"][\\\"required\\\"] is True\\n        assert updated_config[\\\"password\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"password\\\"][\\\"required\\\"] is True\\n        # JWT fields should be hidden\\n        assert updated_config[\\\"jwt_token\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"jwt_header\\\"][\\\"show\\\"] is False\\n\\n    async def test_update_build_config_auth_jwt(self, component_class):\\n        \\\"\\\"\\\"Test update_build_config with JWT authentication.\\\"\\\"\\\"\\n        component = component_class()\\n        build_config = {\\n            \\\"username\\\": {\\\"required\\\": False, \\\"show\\\": False},\\n            \\\"password\\\": {\\\"required\\\": False, \\\"show\\\": False},\\n            \\\"jwt_token\\\": {\\\"required\\\": False, \\\"show\\\": False},\\n            \\\"bearer_token\\\": {\\\"required\\\": False, \\\"show\\\": False},\\n            \\\"bearer_prefix\\\": {\\\"required\\\": False, \\\"show\\\": False},\\n            \\\"jwt_header\\\": {\\\"required\\\": False, \\\"show\\\": False},\\n        }\\n\\n        updated_config = await component.update_build_config(build_config, \\\"jwt\\\", \\\"auth_mode\\\")\\n\\n        # Verify JWT fields are visible and required\\n        assert updated_config[\\\"jwt_token\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"jwt_token\\\"][\\\"required\\\"] is True\\n        assert updated_config[\\\"jwt_header\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"jwt_header\\\"][\\\"required\\\"] is True\\n        assert updated_config[\\\"bearer_prefix\\\"][\\\"show\\\"] is True\\n        assert updated_config[\\\"bearer_prefix\\\"][\\\"required\\\"] is False\\n        # Basic auth fields should be hidden\\n        assert updated_config[\\\"username\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"password\\\"][\\\"show\\\"] is False\\n\\n    async def test_update_build_config_auth_no_auth(self, component_class):\\n        \\\"\\\"\\\"Test update_build_config with no authentication (all fields hidden).\\\"\\\"\\\"\\n        component = component_class()\\n        build_config = {\\n            \\\"username\\\": {\\\"required\\\": True, \\\"show\\\": True},\\n            \\\"password\\\": {\\\"required\\\": True, \\\"show\\\": True},\\n            \\\"jwt_token\\\": {\\\"required\\\": True, \\\"show\\\": True},\\n            \\\"bearer_token\\\": {\\\"required\\\": False, \\\"show\\\": False},\\n            \\\"bearer_prefix\\\": {\\\"required\\\": False, \\\"show\\\": False},\\n            \\\"jwt_header\\\": {\\\"required\\\": True, \\\"show\\\": True},\\n        }\\n\\n        updated_config = await component.update_build_config(build_config, \\\"none\\\", \\\"auth_mode\\\")\\n\\n        # When mode is not \\\"basic\\\" or \\\"jwt\\\", all auth fields should be hidden\\n        assert updated_config[\\\"username\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"password\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"jwt_token\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"jwt_header\\\"][\\\"show\\\"] is False\\n        assert updated_config[\\\"bearer_prefix\\\"][\\\"show\\\"] is False\\n\\n\\nclass TestOpenSearchMultimodalIntegration:\\n    \\\"\\\"\\\"Integration tests for OpenSearch multimodal component.\\\"\\\"\\\"\\n\\n    def test_multi_embedding_configuration(self, embeddings_with_models_openai, embeddings_with_models_ollama):\\n        \\\"\\\"\\\"Test that multiple embeddings are properly configured.\\\"\\\"\\\"\\n        component = OpenSearchVectorStoreComponentMultimodalMultiEmbedding()\\n        component.set_attributes(\\n            {\\n                \\\"opensearch_url\\\": \\\"http://localhost:9200\\\",\\n                \\\"index_name\\\": \\\"test_index\\\",\\n                \\\"embedding\\\": [embeddings_with_models_openai, embeddings_with_models_ollama],\\n                \\\"auth_mode\\\": \\\"No Authentication\\\",\\n                \\\"number_of_results\\\": 5,\\n            }\\n        )\\n\\n        assert isinstance(component.embedding, list)\\n        assert len(component.embedding) == 2\\n\\n        # Verify all available models\\n        all_models = {}\\n        for emb_wrapper in component.embedding:\\n            if isinstance(emb_wrapper, EmbeddingsWithModels):\\n                all_models.update(emb_wrapper.available_models)\\n\\n        # Should have models from both OpenAI and Ollama\\n        assert len(all_models) >= 4  # 2 from OpenAI + 2 from Ollama\\n\\n    def test_field_mapping_generation(self):\\n        \\\"\\\"\\\"Test that field mappings are correctly generated for multiple models.\\\"\\\"\\\"\\n        # Verify that field names would be generated correctly\\n        expected_fields = [\\n            \\\"chunk_embedding_text_embedding_3_small\\\",\\n            \\\"chunk_embedding_text_embedding_3_large\\\",\\n            \\\"chunk_embedding_bge_large_latest\\\",\\n            \\\"chunk_embedding_qwen3_embedding_4b\\\",\\n        ]\\n\\n        for model_name in [\\n            \\\"text-embedding-3-small\\\",\\n            \\\"text-embedding-3-large\\\",\\n            \\\"bge-large:latest\\\",\\n            \\\"qwen3-embedding:4b\\\",\\n        ]:\\n            field_name = get_embedding_field_name(model_name)\\n            assert field_name in expected_fields\\n\\n    def test_embedding_dimension_consistency(self, embeddings_with_models_openai, embeddings_with_models_ollama):\\n        \\\"\\\"\\\"Test that each model maintains its own dimension.\\\"\\\"\\\"\\n        embeddings_list = [embeddings_with_models_openai, embeddings_with_models_ollama]\\n\\n        for emb_wrapper in embeddings_list:\\n            if isinstance(emb_wrapper, EmbeddingsWithModels):\\n                for model_instance in emb_wrapper.available_models.values():\\n                    # Each model should have consistent dimensions\\n                    vec1 = model_instance.embed_query(\\\"test1\\\")\\n                    vec2 = model_instance.embed_query(\\\"test2\\\")\\n                    assert len(vec1) == len(vec2)\\n\\n    async def test_async_embedding_generation(self, embeddings_with_models_openai, embeddings_with_models_ollama):\\n        \\\"\\\"\\\"Test async embedding generation for multiple models.\\\"\\\"\\\"\\n        embeddings_list = [embeddings_with_models_openai, embeddings_with_models_ollama]\\n\\n        for emb_wrapper in embeddings_list:\\n            if isinstance(emb_wrapper, EmbeddingsWithModels):\\n                for model_instance in emb_wrapper.available_models.values():\\n                    # Test async embedding\\n                    vec = await model_instance.aembed_query(\\\"test query\\\")\\n                    assert len(vec) > 0\\n                    assert all(isinstance(v, float) for v in vec)\\n\\n    def test_model_name_retrieval(self, embeddings_with_models_openai, embeddings_with_models_ollama):\\n        \\\"\\\"\\\"Test retrieving model names from embedding instances.\\\"\\\"\\\"\\n        component = OpenSearchVectorStoreComponentMultimodalMultiEmbedding()\\n        embeddings_list = [embeddings_with_models_openai, embeddings_with_models_ollama]\\n\\n        model_names = []\\n        for emb_wrapper in embeddings_list:\\n            if isinstance(emb_wrapper, EmbeddingsWithModels):\\n                # Get primary model name\\n                primary_name = component._get_embedding_model_name(emb_wrapper.embeddings)\\n                if primary_name:\\n                    model_names.append(primary_name)\\n\\n                # Get all available model names\\n                model_names.extend(emb_wrapper.available_models.keys())\\n\\n        # Should have multiple distinct model names\\n        assert len(set(model_names)) >= 4\\n\\n    def test_empty_available_models(self):\\n        \\\"\\\"\\\"Test component with EmbeddingsWithModels that has empty available_models.\\\"\\\"\\\"\\n        embedding = MockEmbeddings(model=\\\"test-model\\\", dimension=384)\\n        wrapper = EmbeddingsWithModels(embeddings=embedding, available_models={})\\n\\n        component = OpenSearchVectorStoreComponentMultimodalMultiEmbedding()\\n        component.set_attributes(\\n            {\\n                \\\"opensearch_url\\\": \\\"http://localhost:9200\\\",\\n                \\\"index_name\\\": \\\"test_index\\\",\\n                \\\"embedding\\\": wrapper,\\n                \\\"auth_mode\\\": \\\"No Authentication\\\",\\n            }\\n        )\\n\\n        # Should still work with empty available_models\\n        assert isinstance(component.embedding, EmbeddingsWithModels)\\n        assert len(component.embedding.available_models) == 0\\n\\n    def test_mixed_embedding_types(self):\\n        \\\"\\\"\\\"Test component with both EmbeddingsWithModels and regular Embeddings.\\\"\\\"\\\"\\n        regular_embedding = MockEmbeddings(model=\\\"regular-model\\\", dimension=384)\\n        wrapped_embedding = EmbeddingsWithModels(\\n            embeddings=MockEmbeddings(model=\\\"wrapped-model\\\", dimension=512),\\n            available_models={\\\"model-a\\\": MockEmbeddings(model=\\\"model-a\\\", dimension=768)},\\n        )\\n\\n        component = OpenSearchVectorStoreComponentMultimodalMultiEmbedding()\\n        component.set_attributes(\\n            {\\n                \\\"opensearch_url\\\": \\\"http://localhost:9200\\\",\\n                \\\"index_name\\\": \\\"test_index\\\",\\n                \\\"embedding\\\": [regular_embedding, wrapped_embedding],\\n                \\\"auth_mode\\\": \\\"No Authentication\\\",\\n            }\\n        )\\n\\n        # Should handle mixed types\\n        assert isinstance(component.embedding, list)\\n        assert len(component.embedding) == 2\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/bundles/faiss/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c0602bfafb94600376f0b174cc899182e5dfb9d34df592211ecd64fb5df12192\",\"content\":\"\\\"\\\"\\\"FAISS components test package.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/bundles/google/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"38658069c224d73dbfa5b13d89007f576c11f4ef215ad0b137e3c295c9b49efc\",\"content\":\"\\\"\\\"\\\"Google components test package.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/bundles/google/test_google_bq_sql_executor_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"dc9c51c1346b3314fceb02750ed236f4e5418b4f19fcd929f9190eca8c11b741\",\"content\":\"\\\"\\\"\\\"Tests for BigQueryExecutorComponent.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nimport re\\nfrom unittest.mock import MagicMock, mock_open, patch\\n\\nimport pytest\\n\\npytest.importorskip(\\\"lfx_google\\\")\\n\\nfrom google.auth.exceptions import RefreshError\\nfrom google.oauth2.service_account import Credentials\\nfrom lfx_google.components.google.google_bq_sql_executor import BigQueryExecutorComponent\\nfrom pandas import DataFrame\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestBigQueryExecutorComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return BigQueryExecutorComponent\\n\\n    @pytest.fixture\\n    def mock_credentials_json(self):\\n        \\\"\\\"\\\"Return a valid service account JSON string.\\\"\\\"\\\"\\n        return json.dumps(\\n            {\\n                \\\"type\\\": \\\"service_account\\\",\\n                \\\"project_id\\\": \\\"test-project\\\",\\n                \\\"private_key_id\\\": \\\"fake-key-id\\\",\\n                \\\"private_key\\\": \\\"-----BEGIN PRIVATE KEY-----\\\\nfake-key\\\\n-----END PRIVATE KEY-----\\\\n\\\",\\n                \\\"client_email\\\": \\\"test@project.iam.gserviceaccount.com\\\",\\n                \\\"client_id\\\": \\\"123456789\\\",\\n                \\\"auth_uri\\\": \\\"https://accounts.google.com/o/oauth2/auth\\\",\\n                \\\"token_uri\\\": \\\"https://oauth2.googleapis.com/token\\\",\\n                \\\"auth_provider_x509_cert_url\\\": \\\"https://www.googleapis.com/oauth2/v1/certs\\\",\\n                \\\"client_x509_cert_url\\\": (\\n                    \\\"https://www.googleapis.com/robot/v1/metadata/x509/test@project.iam.gserviceaccount.com\\\"\\n                ),\\n            }\\n        )\\n\\n    @pytest.fixture\\n    def service_account_file(self, tmp_path, mock_credentials_json):\\n        \\\"\\\"\\\"Write service account JSON to a temp file and return its path.\\\"\\\"\\\"\\n        f = tmp_path / \\\"sa.json\\\"\\n        f.write_text(mock_credentials_json)\\n        return str(f)\\n\\n    @pytest.fixture\\n    def default_kwargs(self, service_account_file):\\n        \\\"\\\"\\\"Return default kwargs for component instantiation.\\\"\\\"\\\"\\n        return {\\n            \\\"service_account_json_file\\\": service_account_file,\\n            \\\"query\\\": \\\"SELECT 1\\\",\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"No version-specific files for this component.\\\"\\\"\\\"\\n        return []\\n\\n    @patch.object(Credentials, \\\"from_service_account_file\\\")\\n    @patch(\\\"lfx_google.components.google.google_bq_sql_executor.bigquery.Client\\\")\\n    def test_execute_sql_success(self, mock_client_cls, mock_from_file, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test successful SQL execution and component side-effects.\\\"\\\"\\\"\\n        # Arrange mocks\\n        mock_creds = MagicMock(spec=Credentials)\\n        mock_from_file.return_value = mock_creds\\n\\n        # Create a mock row that can be converted to a dict\\n        mock_row = MagicMock()\\n        mock_row.items.return_value = [(\\\"column1\\\", \\\"value1\\\")]\\n        mock_row.__iter__.return_value = iter([(\\\"column1\\\", \\\"value1\\\")])\\n        mock_row.keys.return_value = [\\\"column1\\\"]\\n        mock_row.to_numpy.return_value = [\\\"value1\\\"]  # Changed from values to to_numpy\\n        mock_row.__getitem__.return_value = \\\"value1\\\"\\n\\n        # Create mock result with the mock row\\n        mock_result = MagicMock()\\n        mock_result.__iter__.return_value = iter([mock_row])\\n\\n        # Create mock job with the mock result\\n        mock_job = MagicMock()\\n        mock_job.result.return_value = mock_result\\n\\n        # Create mock client with the mock job\\n        mock_client = MagicMock()\\n        mock_client.query.return_value = mock_job\\n        mock_client_cls.return_value = mock_client\\n\\n        # Instantiate component with defaults\\n        component = component_class(**default_kwargs)\\n\\n        # Execute\\n        result = component.execute_sql()\\n\\n        # Verify the result\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 1  # Check number of rows\\n        assert \\\"column1\\\" in result.columns  # Check column exists\\n        assert result.iloc[0][\\\"column1\\\"] == \\\"value1\\\"  # Check value\\n\\n        # Verify the mocks were called correctly\\n        mock_from_file.assert_called_once_with(default_kwargs[\\\"service_account_json_file\\\"])\\n        mock_client_cls.assert_called_once_with(credentials=mock_creds, project=\\\"test-project\\\")\\n        mock_client.query.assert_called_once_with(default_kwargs[\\\"query\\\"])\\n\\n    @pytest.mark.parametrize(\\\"q\\\", [\\\"\\\", \\\"   \\\\n\\\\t  \\\"])\\n    @patch.object(Credentials, \\\"from_service_account_file\\\")\\n    @patch(\\\"lfx_google.components.google.google_bq_sql_executor.bigquery.Client\\\")\\n    def test_empty_query_raises(self, mock_client_cls, mock_from_file, component_class, service_account_file, q):\\n        \\\"\\\"\\\"Empty or whitespace-only queries should raise a ValueError.\\\"\\\"\\\"\\n        # Create a proper mock credentials object\\n        mock_creds = MagicMock(spec=Credentials)\\n        mock_from_file.return_value = mock_creds\\n\\n        # Mock the BigQuery client\\n        mock_client = MagicMock()\\n        mock_client_cls.return_value = mock_client\\n\\n        # Create component with empty/whitespace query\\n        component = component_class(\\n            service_account_json_file=service_account_file,\\n            query=q,\\n        )\\n\\n        # Verify that execute_sql raises ValueError for empty/whitespace queries\\n        expected_error = \\\"No valid SQL query found in input text.\\\"\\n        with pytest.raises(ValueError, match=expected_error):\\n            component.execute_sql()\\n\\n        # Verify that the BigQuery client was not called\\n        mock_client.query.assert_not_called()\\n\\n    def test_missing_service_account_file(self, component_class):\\n        \\\"\\\"\\\"Non-existent service account file should raise a ValueError.\\\"\\\"\\\"\\n        component = component_class(\\n            service_account_json_file=\\\"/no/such/file.json\\\",\\n            query=\\\"SELECT 1\\\",\\n        )\\n        expected_error = \\\"Service account file not found\\\"\\n        with pytest.raises(ValueError, match=expected_error):\\n            component.execute_sql()\\n\\n    def test_invalid_service_account_json(self, component_class):\\n        \\\"\\\"\\\"Invalid JSON in service account file should raise a ValueError.\\\"\\\"\\\"\\n        with patch(\\\"pathlib.Path.open\\\", mock_open(read_data=\\\"invalid json\\\")):\\n            component = component_class(\\n                service_account_json_file=\\\"ignored.json\\\",\\n                query=\\\"SELECT 1\\\",\\n            )\\n            expected_error = \\\"Invalid JSON string for service account credentials\\\"\\n            with pytest.raises(ValueError, match=expected_error):\\n                component.execute_sql()\\n\\n    @patch.object(Credentials, \\\"from_service_account_file\\\")\\n    @patch(\\\"lfx_google.components.google.google_bq_sql_executor.bigquery.Client\\\")\\n    def test_execute_sql_invalid_query(self, mock_client_cls, mock_from_file, component_class, default_kwargs):\\n        \\\"\\\"\\\"SQL execution errors should be wrapped in ValueError.\\\"\\\"\\\"\\n        mock_from_file.return_value = MagicMock()\\n        fake_client = MagicMock()\\n        mock_client_cls.return_value = fake_client\\n        fake_client.query.side_effect = Exception(\\\"Invalid query syntax\\\")\\n\\n        component = component_class(**default_kwargs)\\n        with pytest.raises(ValueError, match=\\\"Error executing BigQuery SQL query: Invalid query syntax\\\"):\\n            component.execute_sql()\\n\\n    @patch.object(Credentials, \\\"from_service_account_file\\\")\\n    @patch(\\\"lfx_google.components.google.google_bq_sql_executor.bigquery.Client\\\")\\n    def test_refresh_error_handling(self, mock_client_cls, mock_from_file, component_class, default_kwargs):\\n        \\\"\\\"\\\"RefreshError should produce an authentication ValueError.\\\"\\\"\\\"\\n        mock_from_file.return_value = MagicMock()\\n        fake_client = MagicMock()\\n        mock_client_cls.return_value = fake_client\\n        fake_client.query.side_effect = RefreshError(\\\"Token expired\\\")\\n\\n        component = component_class(**default_kwargs)\\n        with pytest.raises(\\n            ValueError, match=re.escape(\\\"Authentication error: Unable to refresh authentication token.\\\")\\n        ):\\n            component.execute_sql()\\n\\n    @patch.object(Credentials, \\\"from_service_account_file\\\")\\n    @patch(\\\"lfx_google.components.google.google_bq_sql_executor.bigquery.Client\\\")\\n    def test_complex_query_result(self, mock_client_cls, mock_from_file, component_class, default_kwargs):\\n        \\\"\\\"\\\"Complex row structures should be correctly serialized to DataFrame.\\\"\\\"\\\"\\n        # Arrange mocks\\n        mock_creds = MagicMock(spec=Credentials)\\n        mock_from_file.return_value = mock_creds\\n\\n        # Create mock rows with complex data\\n        mock_row1 = MagicMock()\\n        mock_row1.items.return_value = [(\\\"id\\\", 1), (\\\"name\\\", \\\"Test 1\\\"), (\\\"value\\\", 10.5), (\\\"active\\\", True)]\\n        mock_row1.__iter__.return_value = iter([(\\\"id\\\", 1), (\\\"name\\\", \\\"Test 1\\\"), (\\\"value\\\", 10.5), (\\\"active\\\", True)])\\n        mock_row1.keys.return_value = [\\\"id\\\", \\\"name\\\", \\\"value\\\", \\\"active\\\"]\\n        mock_row1.to_numpy.return_value = [1, \\\"Test 1\\\", 10.5, True]  # Changed from values to to_numpy\\n        mock_row1.__getitem__.side_effect = lambda key: {\\\"id\\\": 1, \\\"name\\\": \\\"Test 1\\\", \\\"value\\\": 10.5, \\\"active\\\": True}[key]\\n\\n        mock_row2 = MagicMock()\\n        mock_row2.items.return_value = [(\\\"id\\\", 2), (\\\"name\\\", \\\"Test 2\\\"), (\\\"value\\\", 20.75), (\\\"active\\\", False)]\\n        mock_row2.__iter__.return_value = iter([(\\\"id\\\", 2), (\\\"name\\\", \\\"Test 2\\\"), (\\\"value\\\", 20.75), (\\\"active\\\", False)])\\n        mock_row2.keys.return_value = [\\\"id\\\", \\\"name\\\", \\\"value\\\", \\\"active\\\"]\\n        mock_row2.to_numpy.return_value = [2, \\\"Test 2\\\", 20.75, False]  # Changed from values to to_numpy\\n        mock_row2.__getitem__.side_effect = lambda key: {\\\"id\\\": 2, \\\"name\\\": \\\"Test 2\\\", \\\"value\\\": 20.75, \\\"active\\\": False}[\\n            key\\n        ]\\n\\n        # Create mock result with the mock rows\\n        mock_result = MagicMock()\\n        mock_result.__iter__.return_value = iter([mock_row1, mock_row2])\\n\\n        # Create mock job with the mock result\\n        mock_job = MagicMock()\\n        mock_job.result.return_value = mock_result\\n\\n        # Create mock client with the mock job\\n        mock_client = MagicMock()\\n        mock_client.query.return_value = mock_job\\n        mock_client_cls.return_value = mock_client\\n\\n        # Instantiate component with defaults\\n        component = component_class(**default_kwargs)\\n\\n        # Execute\\n        result = component.execute_sql()\\n\\n        # Verify the result\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 2  # Check number of rows\\n        assert list(result.columns) == [\\\"id\\\", \\\"name\\\", \\\"value\\\", \\\"active\\\"]  # Check columns\\n\\n        # Convert DataFrame to dictionary for easier comparison\\n        result_dict = result.to_dict(orient=\\\"records\\\")\\n\\n        # Verify first row\\n        assert result_dict[0][\\\"id\\\"] == 1\\n        assert result_dict[0][\\\"name\\\"] == \\\"Test 1\\\"\\n        assert result_dict[0][\\\"value\\\"] == 10.5\\n        assert result_dict[0][\\\"active\\\"] is True\\n\\n        # Verify second row\\n        assert result_dict[1][\\\"id\\\"] == 2\\n        assert result_dict[1][\\\"name\\\"] == \\\"Test 2\\\"\\n        assert result_dict[1][\\\"value\\\"] == 20.75\\n        assert result_dict[1][\\\"active\\\"] is False\\n\\n        # Verify the mocks were called correctly\\n        mock_from_file.assert_called_once_with(default_kwargs[\\\"service_account_json_file\\\"])\\n        mock_client_cls.assert_called_once_with(credentials=mock_creds, project=\\\"test-project\\\")\\n        mock_client.query.assert_called_once_with(default_kwargs[\\\"query\\\"])\\n\\n    @patch.object(Credentials, \\\"from_service_account_file\\\")\\n    @patch(\\\"lfx_google.components.google.google_bq_sql_executor.bigquery.Client\\\")\\n    def test_query_with_sql_code_block(self, mock_client_cls, mock_from_file, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that queries with SQL code blocks are properly handled.\\\"\\\"\\\"\\n        mock_from_file.return_value = MagicMock()\\n        fake_client = MagicMock()\\n        mock_client_cls.return_value = fake_client\\n\\n        query_with_code_block = \\\"```sql\\\\nSELECT * FROM table\\\\n```\\\"\\n        component = component_class(**{**default_kwargs, \\\"query\\\": query_with_code_block, \\\"clean_query\\\": True})\\n\\n        result = component.execute_sql()\\n\\n        # Verify the query was properly cleaned (code block markers removed)\\n        fake_client.query.assert_called_once_with(\\\"SELECT * FROM table\\\")\\n        assert isinstance(result, DataFrame)\\n\\n    @patch.object(Credentials, \\\"from_service_account_file\\\")\\n    @patch(\\\"lfx_google.components.google.google_bq_sql_executor.bigquery.Client\\\")\\n    def test_query_with_whitespace(self, mock_client_cls, mock_from_file, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that queries with extra whitespace are properly handled.\\\"\\\"\\\"\\n        # Arrange mocks\\n        mock_creds = MagicMock(spec=Credentials)\\n        mock_from_file.return_value = mock_creds\\n\\n        # Create a mock row that can be converted to a dict\\n        mock_row = MagicMock()\\n        mock_row.items.return_value = [(\\\"column1\\\", \\\"value1\\\")]\\n        mock_row.__iter__.return_value = iter([(\\\"column1\\\", \\\"value1\\\")])\\n        mock_row.keys.return_value = [\\\"column1\\\"]\\n        mock_row.to_numpy.return_value = [\\\"value1\\\"]  # Changed from values to to_numpy\\n        mock_row.__getitem__.return_value = \\\"value1\\\"\\n\\n        # Create mock result with the mock row\\n        mock_result = MagicMock()\\n        mock_result.__iter__.return_value = iter([mock_row])\\n\\n        # Create mock job with the mock result\\n        mock_job = MagicMock()\\n        mock_job.result.return_value = mock_result\\n\\n        # Create mock client with the mock job\\n        mock_client = MagicMock()\\n        mock_client.query.return_value = mock_job\\n        mock_client_cls.return_value = mock_client\\n\\n        query_with_whitespace = \\\"  SELECT * FROM table  \\\"\\n        component = component_class(**{**default_kwargs, \\\"query\\\": query_with_whitespace, \\\"clean_query\\\": True})\\n\\n        result = component.execute_sql()\\n\\n        # Verify the query was properly stripped\\n        mock_client.query.assert_called_once_with(\\\"SELECT * FROM table\\\")\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 1  # Check number of rows\\n        assert \\\"column1\\\" in result.columns  # Check column exists\\n        assert result.iloc[0][\\\"column1\\\"] == \\\"value1\\\"  # Check value\\n\\n    @patch.object(Credentials, \\\"from_service_account_file\\\")\\n    @patch(\\\"lfx_google.components.google.google_bq_sql_executor.bigquery.Client\\\")\\n    def test_query_with_special_characters(self, mock_client_cls, mock_from_file, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that queries with special characters are properly handled.\\\"\\\"\\\"\\n        # Arrange mocks\\n        mock_creds = MagicMock(spec=Credentials)\\n        mock_from_file.return_value = mock_creds\\n\\n        # Create a mock row that can be converted to a dict\\n        mock_row = MagicMock()\\n        mock_row.items.return_value = [(\\\"name\\\", \\\"test_value\\\")]\\n        mock_row.__iter__.return_value = iter([(\\\"name\\\", \\\"test_value\\\")])\\n        mock_row.keys.return_value = [\\\"name\\\"]\\n        mock_row.to_numpy.return_value = [\\\"test_value\\\"]  # Changed from values to to_numpy\\n        mock_row.__getitem__.return_value = \\\"test_value\\\"\\n\\n        # Create mock result with the mock row\\n        mock_result = MagicMock()\\n        mock_result.__iter__.return_value = iter([mock_row])\\n\\n        # Create mock job with the mock result\\n        mock_job = MagicMock()\\n        mock_job.result.return_value = mock_result\\n\\n        # Create mock client with the mock job\\n        mock_client = MagicMock()\\n        mock_client.query.return_value = mock_job\\n        mock_client_cls.return_value = mock_client\\n\\n        query_with_special_chars = \\\"SELECT * FROM project.dataset.table WHERE name LIKE '%test%'\\\"\\n        component = component_class(**{**default_kwargs, \\\"query\\\": query_with_special_chars})\\n\\n        result = component.execute_sql()\\n\\n        # Verify the query with special characters was passed correctly\\n        mock_client.query.assert_called_once_with(query_with_special_chars)\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 1  # Check number of rows\\n        assert \\\"name\\\" in result.columns  # Check column exists\\n        assert result.iloc[0][\\\"name\\\"] == \\\"test_value\\\"  # Check value\\n\\n    @patch.object(Credentials, \\\"from_service_account_file\\\")\\n    @patch(\\\"lfx_google.components.google.google_bq_sql_executor.bigquery.Client\\\")\\n    def test_query_with_multiple_statements(self, mock_client_cls, mock_from_file, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that queries with multiple statements are properly handled.\\\"\\\"\\\"\\n        # Arrange mocks\\n        mock_creds = MagicMock(spec=Credentials)\\n        mock_from_file.return_value = mock_creds\\n\\n        # Create a mock row that can be converted to a dict\\n        mock_row = MagicMock()\\n        mock_row.items.return_value = [(\\\"id\\\", 1)]\\n        mock_row.__iter__.return_value = iter([(\\\"id\\\", 1)])\\n        mock_row.keys.return_value = [\\\"id\\\"]\\n        mock_row.to_numpy.return_value = [1]  # Changed from values to to_numpy\\n        mock_row.__getitem__.return_value = 1\\n\\n        # Create mock result with the mock row\\n        mock_result = MagicMock()\\n        mock_result.__iter__.return_value = iter([mock_row])\\n\\n        # Create mock job with the mock result\\n        mock_job = MagicMock()\\n        mock_job.result.return_value = mock_result\\n\\n        # Create mock client with the mock job\\n        mock_client = MagicMock()\\n        mock_client.query.return_value = mock_job\\n        mock_client_cls.return_value = mock_client\\n\\n        multi_statement_query = (\\n            \\\"CREATE TABLE IF NOT EXISTS test_table (id INT64);\\\\n\\\"\\n            \\\"INSERT INTO test_table VALUES (1);\\\\n\\\"\\n            \\\"SELECT * FROM test_table;\\\"\\n        )\\n        component = component_class(**{**default_kwargs, \\\"query\\\": multi_statement_query})\\n\\n        result = component.execute_sql()\\n\\n        # Verify the multi-statement query was passed correctly\\n        mock_client.query.assert_called_once_with(multi_statement_query)\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 1  # Check number of rows\\n        assert \\\"id\\\" in result.columns  # Check column exists\\n        assert result.iloc[0][\\\"id\\\"] == 1  # Check value\\n\\n    @patch.object(Credentials, \\\"from_service_account_file\\\")\\n    @patch(\\\"lfx_google.components.google.google_bq_sql_executor.bigquery.Client\\\")\\n    def test_query_with_parameters(self, mock_client_cls, mock_from_file, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that queries with parameters are properly handled.\\\"\\\"\\\"\\n        # Arrange mocks\\n        mock_creds = MagicMock(spec=Credentials)\\n        mock_from_file.return_value = mock_creds\\n\\n        # Create a mock row that can be converted to a dict\\n        mock_row = MagicMock()\\n        mock_row.items.return_value = [(\\\"id\\\", 1), (\\\"name\\\", \\\"test_name\\\")]\\n        mock_row.__iter__.return_value = iter([(\\\"id\\\", 1), (\\\"name\\\", \\\"test_name\\\")])\\n        mock_row.keys.return_value = [\\\"id\\\", \\\"name\\\"]\\n        mock_row.to_numpy.return_value = [1, \\\"test_name\\\"]  # Changed from values to to_numpy\\n        mock_row.__getitem__.side_effect = lambda key: {\\\"id\\\": 1, \\\"name\\\": \\\"test_name\\\"}[key]\\n\\n        # Create mock result with the mock row\\n        mock_result = MagicMock()\\n        mock_result.__iter__.return_value = iter([mock_row])\\n\\n        # Create mock job with the mock result\\n        mock_job = MagicMock()\\n        mock_job.result.return_value = mock_result\\n\\n        # Create mock client with the mock job\\n        mock_client = MagicMock()\\n        mock_client.query.return_value = mock_job\\n        mock_client_cls.return_value = mock_client\\n\\n        query_with_params = \\\"SELECT * FROM table WHERE id = @id AND name = @name\\\"\\n        component = component_class(**{**default_kwargs, \\\"query\\\": query_with_params})\\n\\n        result = component.execute_sql()\\n\\n        # Verify the parameterized query was passed correctly\\n        mock_client.query.assert_called_once_with(query_with_params)\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 1  # Check number of rows\\n        assert list(result.columns) == [\\\"id\\\", \\\"name\\\"]  # Check columns\\n        assert result.iloc[0][\\\"id\\\"] == 1  # Check id value\\n        assert result.iloc[0][\\\"name\\\"] == \\\"test_name\\\"  # Check name value\\n\\n    def test_missing_project_id_in_credentials(self, component_class, tmp_path):\\n        \\\"\\\"\\\"Test that missing project_id in credentials raises an error.\\\"\\\"\\\"\\n        # Create a service account JSON without project_id\\n        invalid_credentials = {\\n            \\\"type\\\": \\\"service_account\\\",\\n            \\\"private_key_id\\\": \\\"fake-key-id\\\",\\n            \\\"private_key\\\": \\\"-----BEGIN PRIVATE KEY-----\\\\nfake-key\\\\n-----END PRIVATE KEY-----\\\\n\\\",\\n            \\\"client_email\\\": \\\"test@project.iam.gserviceaccount.com\\\",\\n            \\\"client_id\\\": \\\"123456789\\\",\\n            \\\"auth_uri\\\": \\\"https://accounts.google.com/o/oauth2/auth\\\",\\n            \\\"token_uri\\\": \\\"https://oauth2.googleapis.com/token\\\",\\n            \\\"auth_provider_x509_cert_url\\\": \\\"https://www.googleapis.com/oauth2/v1/certs\\\",\\n            \\\"client_x509_cert_url\\\": \\\"https://www.googleapis.com/robot/v1/metadata/x509/test@project.iam.gserviceaccount.com\\\",\\n        }\\n\\n        # Write invalid credentials to a temp file\\n        f = tmp_path / \\\"invalid_sa.json\\\"\\n        f.write_text(json.dumps(invalid_credentials))\\n\\n        component = component_class(\\n            service_account_json_file=str(f),\\n            query=\\\"SELECT 1\\\",\\n        )\\n\\n        with pytest.raises(ValueError, match=\\\"No project_id found in service account credentials file\\\"):\\n            component.execute_sql()\\n\\n    @patch.object(Credentials, \\\"from_service_account_file\\\")\\n    @patch(\\\"lfx_google.components.google.google_bq_sql_executor.bigquery.Client\\\")\\n    def test_query_with_quotes(self, mock_client_cls, mock_from_file, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that queries wrapped in quotes are properly handled.\\\"\\\"\\\"\\n        # Arrange mocks\\n        mock_creds = MagicMock(spec=Credentials)\\n        mock_from_file.return_value = mock_creds\\n\\n        # Create a mock row that can be converted to a dict\\n        mock_row = MagicMock()\\n        mock_row.items.return_value = [(\\\"column1\\\", \\\"value1\\\")]\\n        mock_row.__iter__.return_value = iter([(\\\"column1\\\", \\\"value1\\\")])\\n        mock_row.keys.return_value = [\\\"column1\\\"]\\n        mock_row.to_numpy.return_value = [\\\"value1\\\"]  # Changed from values to to_numpy\\n        mock_row.__getitem__.return_value = \\\"value1\\\"\\n\\n        # Create mock result with the mock row\\n        mock_result = MagicMock()\\n        mock_result.__iter__.return_value = iter([mock_row])\\n\\n        # Create mock job with the mock result\\n        mock_job = MagicMock()\\n        mock_job.result.return_value = mock_result\\n\\n        # Create mock client with the mock job\\n        mock_client = MagicMock()\\n        mock_client.query.return_value = mock_job\\n        mock_client_cls.return_value = mock_client\\n\\n        # Test with double quotes\\n        query_with_double_quotes = '\\\"SELECT * FROM table\\\"'\\n        component = component_class(**{**default_kwargs, \\\"query\\\": query_with_double_quotes, \\\"clean_query\\\": True})\\n        result = component.execute_sql()\\n        mock_client.query.assert_called_once_with(\\\"SELECT * FROM table\\\")\\n        assert isinstance(result, DataFrame)\\n\\n        # Reset mocks for next test\\n        mock_client.reset_mock()\\n\\n        # Test with single quotes\\n        query_with_single_quotes = \\\"'SELECT * FROM table'\\\"\\n        component = component_class(**{**default_kwargs, \\\"query\\\": query_with_single_quotes, \\\"clean_query\\\": True})\\n        result = component.execute_sql()\\n        mock_client.query.assert_called_once_with(\\\"SELECT * FROM table\\\")\\n        assert isinstance(result, DataFrame)\\n\\n        # Reset mocks for next test\\n        mock_client.reset_mock()\\n\\n        # Test with SQL code block\\n        query_with_code_block = \\\"```sql\\\\nSELECT * FROM table\\\\n```\\\"\\n        component = component_class(**{**default_kwargs, \\\"query\\\": query_with_code_block, \\\"clean_query\\\": True})\\n        result = component.execute_sql()\\n        mock_client.query.assert_called_once_with(\\\"SELECT * FROM table\\\")\\n        assert isinstance(result, DataFrame)\\n\\n        # Reset mocks for next test\\n        mock_client.reset_mock()\\n\\n        # Test with SQL code block and quotes\\n        query_with_code_block_and_quotes = '```sql\\\\n\\\"SELECT * FROM table\\\"\\\\n```'\\n        component = component_class(\\n            **{**default_kwargs, \\\"query\\\": query_with_code_block_and_quotes, \\\"clean_query\\\": True}\\n        )\\n        result = component.execute_sql()\\n        mock_client.query.assert_called_once_with(\\\"SELECT * FROM table\\\")\\n        assert isinstance(result, DataFrame)\\n\\n        # Reset mocks for next test\\n        mock_client.reset_mock()\\n\\n        # Test with just backticks\\n        query_with_backticks = \\\"`SELECT * FROM table`\\\"\\n        component = component_class(**{**default_kwargs, \\\"query\\\": query_with_backticks, \\\"clean_query\\\": True})\\n        result = component.execute_sql()\\n        mock_client.query.assert_called_once_with(\\\"SELECT * FROM table\\\")\\n        assert isinstance(result, DataFrame)\\n\\n        # Reset mocks for next test\\n        mock_client.reset_mock()\\n\\n        # Test with mixed markers\\n        query_with_mixed = '```sql\\\\n`\\\"SELECT * FROM table\\\"`\\\\n```'\\n        component = component_class(**{**default_kwargs, \\\"query\\\": query_with_mixed, \\\"clean_query\\\": True})\\n        result = component.execute_sql()\\n        mock_client.query.assert_called_once_with(\\\"SELECT * FROM table\\\")\\n        assert isinstance(result, DataFrame)\\n\\n        # Reset mocks for next test\\n        mock_client.reset_mock()\\n\\n        # Test with backticks in the middle of the query\\n        query_with_middle_backticks = \\\"SELECT * FROM project.dataset.table\\\"\\n        component = component_class(**{**default_kwargs, \\\"query\\\": query_with_middle_backticks, \\\"clean_query\\\": True})\\n        result = component.execute_sql()\\n        mock_client.query.assert_called_once_with(\\\"SELECT * FROM project.dataset.table\\\")\\n        assert isinstance(result, DataFrame)\\n\\n        # Reset mocks for next test\\n        mock_client.reset_mock()\\n\\n        # Test with multiple backticks in the query\\n        query_with_multiple_backticks = \\\"SELECT * FROM project.dataset.table WHERE column = 'value'\\\"\\n        component = component_class(**{**default_kwargs, \\\"query\\\": query_with_multiple_backticks, \\\"clean_query\\\": True})\\n        result = component.execute_sql()\\n        mock_client.query.assert_called_once_with(\\\"SELECT * FROM project.dataset.table WHERE column = 'value'\\\")\\n        assert isinstance(result, DataFrame)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/bundles/google/test_google_search_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b10246ebaf31b3b90bbe89fd478309dcc8715fcd893bedda4892600889a65484\",\"content\":\"from unittest.mock import patch\\n\\nimport pandas as pd\\nimport pytest\\n\\npytest.importorskip(\\\"lfx_google\\\")\\n\\nfrom lfx.schema import DataFrame\\nfrom lfx_google.components.google.google_search_api_core import GoogleSearchAPICore\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestGoogleSearchAPICore(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        return GoogleSearchAPICore\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\n            \\\"google_api_key\\\": \\\"test_api_key\\\",\\n            \\\"google_cse_id\\\": \\\"test_cse_id\\\",\\n            \\\"input_value\\\": \\\"test query\\\",\\n            \\\"k\\\": 2,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        # New component, no previous versions\\n        return []\\n\\n    @pytest.fixture\\n    def mock_search_results(self):\\n        return pd.DataFrame(\\n            [\\n                {\\n                    \\\"title\\\": \\\"Test Title 1\\\",\\n                    \\\"link\\\": \\\"https://test1.com\\\",\\n                    \\\"snippet\\\": \\\"Test snippet 1\\\",\\n                },\\n                {\\n                    \\\"title\\\": \\\"Test Title 2\\\",\\n                    \\\"link\\\": \\\"https://test2.com\\\",\\n                    \\\"snippet\\\": \\\"Test snippet 2\\\",\\n                },\\n            ]\\n        )\\n\\n    def test_component_initialization(self, component_class):\\n        component = component_class()\\n\\n        frontend_node = component.to_frontend_node()\\n        node_data = frontend_node[\\\"data\\\"][\\\"node\\\"]\\n\\n        # Test basic component attributes\\n        assert node_data[\\\"display_name\\\"] == \\\"Google Search API\\\"\\n        assert node_data[\\\"icon\\\"] == \\\"Google\\\"\\n\\n        # Test inputs configuration\\n        template = node_data[\\\"template\\\"]\\n        assert \\\"google_api_key\\\" in template\\n        assert \\\"google_cse_id\\\" in template\\n        assert \\\"input_value\\\" in template\\n        assert \\\"k\\\" in template\\n\\n    @patch(\\\"langchain_google_community.GoogleSearchAPIWrapper.results\\\")\\n    def test_search_google_success(self, mock_results, component_class, default_kwargs, mock_search_results):\\n        component = component_class(**default_kwargs)\\n        mock_results.return_value = mock_search_results.to_dict(\\\"records\\\")\\n\\n        result = component.search_google()\\n\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 2\\n        assert result.iloc[0][\\\"title\\\"] == \\\"Test Title 1\\\"\\n        assert result.iloc[1][\\\"link\\\"] == \\\"https://test2.com\\\"\\n        mock_results.assert_called_once_with(query=\\\"test query\\\", num_results=2)\\n\\n    def test_search_google_invalid_api_key(self, component_class):\\n        component = component_class(google_api_key=None)\\n        result = component.search_google()\\n\\n        assert isinstance(result, DataFrame)\\n        assert \\\"error\\\" in result.columns\\n        assert \\\"Invalid Google API Key\\\" in result.iloc[0][\\\"error\\\"]\\n\\n    def test_search_google_invalid_cse_id(self, component_class):\\n        component = component_class(google_api_key=\\\"valid_key\\\", google_cse_id=None)\\n        result = component.search_google()\\n\\n        assert isinstance(result, DataFrame)\\n        assert \\\"error\\\" in result.columns\\n        assert \\\"Invalid Google CSE ID\\\" in result.iloc[0][\\\"error\\\"]\\n\\n    @patch(\\\"langchain_google_community.GoogleSearchAPIWrapper.results\\\")\\n    def test_search_google_error_handling(self, mock_results, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        mock_results.side_effect = ConnectionError(\\\"API connection failed\\\")\\n\\n        result = component.search_google()\\n\\n        assert isinstance(result, DataFrame)\\n        assert \\\"error\\\" in result.columns\\n        assert \\\"Connection error: API connection failed\\\" in result.iloc[0][\\\"error\\\"]\\n\\n    def test_build_method(self, component_class, default_kwargs):\\n        component = component_class(**default_kwargs)\\n        build_result = component.build()\\n        assert build_result == component.search_google\\n\\n    @pytest.mark.asyncio\\n    async def test_latest_version(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Override test_latest_version to skip API call.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        assert component is not None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/bundles/google/test_google_serper_api_core.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b5ce7662141a412b48562d3754219294f5b90438f901e5cea3118c1a91e29a57\",\"content\":\"from unittest.mock import MagicMock, patch\\n\\nimport pytest\\n\\npytest.importorskip(\\\"lfx_google\\\")\\n\\nfrom lfx.schema import DataFrame\\nfrom lfx_google.components.google.google_serper_api_core import GoogleSerperAPICore\\n\\n\\n@pytest.fixture\\ndef google_serper_component():\\n    return GoogleSerperAPICore()\\n\\n\\n@pytest.fixture\\ndef mock_search_results():\\n    return {\\n        \\\"organic\\\": [\\n            {\\n                \\\"title\\\": \\\"Test Title 1\\\",\\n                \\\"link\\\": \\\"https://test1.com\\\",\\n                \\\"snippet\\\": \\\"Test snippet 1\\\",\\n            },\\n            {\\n                \\\"title\\\": \\\"Test Title 2\\\",\\n                \\\"link\\\": \\\"https://test2.com\\\",\\n                \\\"snippet\\\": \\\"Test snippet 2\\\",\\n            },\\n        ]\\n    }\\n\\n\\ndef test_component_initialization(google_serper_component):\\n    assert google_serper_component.display_name == \\\"Google Serper API\\\"\\n    assert google_serper_component.icon == \\\"Serper\\\"\\n\\n    input_names = [input_.name for input_ in google_serper_component.inputs]\\n    assert \\\"serper_api_key\\\" in input_names\\n    assert \\\"input_value\\\" in input_names\\n    assert \\\"k\\\" in input_names\\n\\n\\n@patch(\\\"langchain_community.utilities.google_serper.requests.get\\\")\\n@patch(\\\"langchain_community.utilities.google_serper.requests.post\\\")\\ndef test_search_serper_success(mock_post, mock_get, google_serper_component, mock_search_results):\\n    # Configure mocks\\n    mock_response = MagicMock()\\n    mock_response.status_code = 200\\n    mock_response.json.return_value = mock_search_results\\n    mock_post.return_value = mock_response\\n    mock_get.return_value = mock_response\\n\\n    # Configure component\\n    google_serper_component.serper_api_key = \\\"test_api_key\\\"\\n    google_serper_component.input_value = \\\"test query\\\"\\n    google_serper_component.k = 2\\n\\n    # Execute search\\n    result = google_serper_component.search_serper()\\n\\n    # Verify results\\n    assert isinstance(result, DataFrame)\\n    assert len(result) == 2\\n    assert list(result.columns) == [\\\"title\\\", \\\"link\\\", \\\"snippet\\\"]\\n    assert result.iloc[0][\\\"title\\\"] == \\\"Test Title 1\\\"\\n    assert result.iloc[1][\\\"link\\\"] == \\\"https://test2.com\\\"\\n\\n\\n@patch(\\\"langchain_community.utilities.google_serper.requests.get\\\")\\n@patch(\\\"langchain_community.utilities.google_serper.requests.post\\\")\\ndef test_search_serper_error_handling(mock_post, mock_get, google_serper_component):\\n    # Configure mocks to simulate error\\n    mock_response = MagicMock()\\n    mock_response.status_code = 403\\n    mock_response.raise_for_status.side_effect = ConnectionError(\\\"API connection failed\\\")\\n    mock_post.return_value = mock_response\\n    mock_get.return_value = mock_response\\n\\n    # Configure component\\n    google_serper_component.serper_api_key = \\\"test_api_key\\\"\\n    google_serper_component.input_value = \\\"test query\\\"\\n    google_serper_component.k = 2\\n\\n    # Execute search\\n    result = google_serper_component.search_serper()\\n\\n    # Verify error handling\\n    assert isinstance(result, DataFrame)\\n    assert \\\"error\\\" in result.columns\\n    assert \\\"API connection failed\\\" in result.iloc[0][\\\"error\\\"]\\n\\n\\ndef test_text_search_serper(google_serper_component):\\n    with patch.object(google_serper_component, \\\"search_serper\\\") as mock_search:\\n        mock_search.return_value = DataFrame(\\n            [{\\\"title\\\": \\\"Test Title\\\", \\\"link\\\": \\\"https://test.com\\\", \\\"snippet\\\": \\\"Test snippet\\\"}]\\n        )\\n\\n        result = google_serper_component.text_search_serper()\\n        assert result.text is not None\\n        assert \\\"Test Title\\\" in result.text\\n        assert \\\"https://test.com\\\" in result.text\\n\\n\\ndef test_build_wrapper(google_serper_component):\\n    google_serper_component.serper_api_key = \\\"test_api_key\\\"\\n    google_serper_component.k = 2\\n\\n    wrapper = google_serper_component._build_wrapper()\\n    assert wrapper.serper_api_key == \\\"test_api_key\\\"\\n    assert wrapper.k == 2\\n\\n\\ndef test_build_method(google_serper_component):\\n    build_result = google_serper_component.build()\\n    assert build_result == google_serper_component.search_serper\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/bundles/huggingface/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8ecad7f7ce99fbad55f00bc15bf2cd70b754a23e7d6dd9f6fe7b618af3be8473\",\"content\":\"\\\"\\\"\\\"Hugging Face components test package.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/bundles/langwatch/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/bundles/langwatch/test_langwatch_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8f863f6f93ee4757b3142a6e8184dfce72899b3865065260b248615acad479b1\",\"content\":\"import json\\nimport os\\nfrom unittest.mock import Mock, patch\\n\\nimport httpx\\nimport pytest\\nimport respx\\nfrom httpx import Response\\n\\npytest.importorskip(\\\"lfx_bundles\\\")\\n\\nfrom lfx.base.langwatch.utils import get_cached_evaluators\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dotdict import dotdict\\nfrom lfx_bundles.langwatch.langwatch import LangWatchComponent\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestLangWatchComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return LangWatchComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"evaluator_name\\\": \\\"test_evaluator\\\",\\n            \\\"api_key\\\": \\\"test_api_key\\\",\\n            \\\"input\\\": \\\"test input\\\",\\n            \\\"output\\\": \\\"test output\\\",\\n            \\\"expected_output\\\": \\\"expected output\\\",\\n            \\\"contexts\\\": \\\"context1, context2\\\",\\n            \\\"timeout\\\": 30,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    @pytest.fixture\\n    def mock_evaluators(self):\\n        \\\"\\\"\\\"Mock evaluators data.\\\"\\\"\\\"\\n        return {\\n            \\\"test_evaluator\\\": {\\n                \\\"name\\\": \\\"test_evaluator\\\",\\n                \\\"requiredFields\\\": [\\\"input\\\", \\\"output\\\"],\\n                \\\"optionalFields\\\": [\\\"contexts\\\"],\\n                \\\"settings\\\": {\\n                    \\\"temperature\\\": {\\n                        \\\"description\\\": \\\"Temperature setting\\\",\\n                        \\\"default\\\": 0.7,\\n                    }\\n                },\\n                \\\"settings_json_schema\\\": {\\n                    \\\"properties\\\": {\\n                        \\\"temperature\\\": {\\n                            \\\"type\\\": \\\"number\\\",\\n                            \\\"default\\\": 0.7,\\n                        }\\n                    }\\n                },\\n            },\\n            \\\"boolean_evaluator\\\": {\\n                \\\"name\\\": \\\"boolean_evaluator\\\",\\n                \\\"requiredFields\\\": [\\\"input\\\"],\\n                \\\"optionalFields\\\": [],\\n                \\\"settings\\\": {\\n                    \\\"strict_mode\\\": {\\n                        \\\"description\\\": \\\"Strict mode setting\\\",\\n                        \\\"default\\\": True,\\n                    }\\n                },\\n                \\\"settings_json_schema\\\": {\\n                    \\\"properties\\\": {\\n                        \\\"strict_mode\\\": {\\n                            \\\"type\\\": \\\"boolean\\\",\\n                            \\\"default\\\": True,\\n                        }\\n                    }\\n                },\\n            },\\n        }\\n\\n    @pytest.fixture\\n    async def component(self, component_class, default_kwargs, mock_evaluators):\\n        \\\"\\\"\\\"Return a component instance.\\\"\\\"\\\"\\n        comp = component_class(**default_kwargs)\\n        comp.evaluators = mock_evaluators\\n        return comp\\n\\n    @pytest.fixture(autouse=True)\\n    def clear_cache(self):\\n        \\\"\\\"\\\"Clear the LRU cache before each test.\\\"\\\"\\\"\\n        get_cached_evaluators.cache_clear()\\n\\n    @patch(\\\"lfx_bundles.langwatch.langwatch.httpx.get\\\")\\n    async def test_set_evaluators_success(self, mock_get, component, mock_evaluators):\\n        \\\"\\\"\\\"Test successful setting of evaluators.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"evaluators\\\": mock_evaluators}\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        endpoint = \\\"https://app.langwatch.ai\\\"\\n        component.set_evaluators(endpoint)\\n        assert component.evaluators == mock_evaluators\\n\\n    @patch(\\\"lfx_bundles.langwatch.langwatch.httpx.get\\\")\\n    async def test_set_evaluators_empty_response(self, mock_get, component):\\n        \\\"\\\"\\\"Test setting evaluators with empty response.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"evaluators\\\": {}}\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        endpoint = \\\"https://app.langwatch.ai\\\"\\n        with pytest.raises(ValueError, match=\\\"No evaluators found\\\"):\\n            component.set_evaluators(endpoint)\\n\\n    def test_get_dynamic_inputs(self, component, mock_evaluators):\\n        \\\"\\\"\\\"Test dynamic input generation.\\\"\\\"\\\"\\n        evaluator = mock_evaluators[\\\"test_evaluator\\\"]\\n        dynamic_inputs = component.get_dynamic_inputs(evaluator)\\n\\n        # Should create inputs for contexts (from optionalFields)\\n        assert \\\"contexts\\\" in dynamic_inputs\\n        # Should create inputs for temperature (from settings)\\n        assert \\\"temperature\\\" in dynamic_inputs\\n\\n    def test_get_dynamic_inputs_with_boolean_setting(self, component, mock_evaluators):\\n        \\\"\\\"\\\"Test dynamic input generation with boolean settings.\\\"\\\"\\\"\\n        evaluator = mock_evaluators[\\\"boolean_evaluator\\\"]\\n        dynamic_inputs = component.get_dynamic_inputs(evaluator)\\n\\n        # Should create boolean input for strict_mode\\n        assert \\\"strict_mode\\\" in dynamic_inputs\\n\\n    def test_get_dynamic_inputs_error_handling(self, component):\\n        \\\"\\\"\\\"Test error handling in dynamic input generation.\\\"\\\"\\\"\\n        # Test with invalid evaluator data\\n        invalid_evaluator = {\\\"invalid\\\": \\\"data\\\"}\\n        result = component.get_dynamic_inputs(invalid_evaluator)\\n        assert result == {}\\n\\n    @patch.dict(os.environ, {\\\"LANGWATCH_ENDPOINT\\\": \\\"https://test.langwatch.ai\\\"})\\n    def test_update_build_config_basic(self, component, mock_evaluators):\\n        \\\"\\\"\\\"Test basic build config update.\\\"\\\"\\\"\\n        build_config = dotdict(\\n            {\\n                \\\"evaluator_name\\\": {\\\"options\\\": [], \\\"value\\\": None},\\n                \\\"api_key\\\": {\\\"value\\\": \\\"test_key\\\"},\\n                \\\"code\\\": {\\\"value\\\": \\\"\\\"},\\n                \\\"_type\\\": {\\\"value\\\": \\\"\\\"},\\n                \\\"input\\\": {\\\"value\\\": \\\"\\\"},\\n                \\\"output\\\": {\\\"value\\\": \\\"\\\"},\\n                \\\"timeout\\\": {\\\"value\\\": 30},\\n            }\\n        )\\n\\n        # Mock the get_evaluators method (which doesn't exist, so create it)\\n        def mock_get_evaluators(endpoint):  # noqa: ARG001\\n            return mock_evaluators\\n\\n        with patch.object(component, \\\"get_evaluators\\\", side_effect=mock_get_evaluators, create=True):\\n            result = component.update_build_config(build_config, None, None)\\n\\n            # Should populate evaluator options\\n            assert \\\"test_evaluator\\\" in result[\\\"evaluator_name\\\"][\\\"options\\\"]\\n            assert \\\"boolean_evaluator\\\" in result[\\\"evaluator_name\\\"][\\\"options\\\"]\\n\\n    @patch.dict(os.environ, {\\\"LANGWATCH_ENDPOINT\\\": \\\"https://test.langwatch.ai\\\"})\\n    def test_update_build_config_with_evaluator_selection(self, component, mock_evaluators):\\n        \\\"\\\"\\\"Test build config update with evaluator selection.\\\"\\\"\\\"\\n        build_config = dotdict(\\n            {\\n                \\\"evaluator_name\\\": {\\\"options\\\": [], \\\"value\\\": None},\\n                \\\"api_key\\\": {\\\"value\\\": \\\"test_key\\\"},\\n                \\\"code\\\": {\\\"value\\\": \\\"\\\"},\\n                \\\"_type\\\": {\\\"value\\\": \\\"\\\"},\\n                \\\"input\\\": {\\\"value\\\": \\\"\\\"},\\n                \\\"output\\\": {\\\"value\\\": \\\"\\\"},\\n                \\\"timeout\\\": {\\\"value\\\": 30},\\n            }\\n        )\\n\\n        # Mock the get_evaluators method (which doesn't exist, so create it)\\n        def mock_get_evaluators(endpoint):  # noqa: ARG001\\n            return mock_evaluators\\n\\n        with patch.object(component, \\\"get_evaluators\\\", side_effect=mock_get_evaluators, create=True):\\n            # Initialize current_evaluator attribute\\n            component.current_evaluator = None\\n            result = component.update_build_config(build_config, \\\"test_evaluator\\\", \\\"evaluator_name\\\")\\n\\n            # Should set the selected evaluator\\n            assert result[\\\"evaluator_name\\\"][\\\"value\\\"] == \\\"test_evaluator\\\"\\n\\n    @patch(\\\"lfx_bundles.langwatch.langwatch.httpx.get\\\")\\n    @respx.mock\\n    async def test_evaluate_success(self, mock_get, component, mock_evaluators):\\n        \\\"\\\"\\\"Test successful evaluation.\\\"\\\"\\\"\\n        # Mock the evaluators HTTP request\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"evaluators\\\": mock_evaluators}\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        # Mock the evaluation endpoint\\n        eval_url = \\\"https://app.langwatch.ai/api/evaluations/test_evaluator/evaluate\\\"\\n        expected_response = {\\\"score\\\": 0.95, \\\"reasoning\\\": \\\"Good evaluation\\\"}\\n        respx.post(eval_url).mock(return_value=Response(200, json=expected_response))\\n\\n        # Set up component\\n        component.evaluator_name = \\\"test_evaluator\\\"\\n        component.api_key = \\\"test_api_key\\\"\\n        component.input = \\\"test input\\\"\\n        component.output = \\\"test output\\\"\\n        component.contexts = \\\"context1, context2\\\"\\n\\n        result = await component.evaluate()\\n\\n        assert isinstance(result, Data)\\n        assert result.data == expected_response\\n\\n    @respx.mock\\n    async def test_evaluate_no_api_key(self, component):\\n        \\\"\\\"\\\"Test evaluation with missing API key.\\\"\\\"\\\"\\n        component.api_key = None\\n\\n        result = await component.evaluate()\\n\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"error\\\"] == \\\"API key is required\\\"\\n\\n    async def test_evaluate_no_evaluators(self, component):\\n        \\\"\\\"\\\"Test evaluation when no evaluators are available.\\\"\\\"\\\"\\n        component.api_key = \\\"test_api_key\\\"\\n        component.evaluator_name = None\\n\\n        # Mock set_evaluators to avoid external HTTP calls\\n        with patch.object(component, \\\"set_evaluators\\\"):\\n            component.evaluators = {}  # Set empty evaluators directly\\n            component.current_evaluator = None  # Initialize the attribute\\n\\n            result = await component.evaluate()\\n\\n            assert isinstance(result, Data)\\n            assert \\\"No evaluator selected\\\" in result.data[\\\"error\\\"]\\n\\n    @patch(\\\"lfx_bundles.langwatch.langwatch.httpx.get\\\")\\n    @respx.mock\\n    async def test_evaluate_evaluator_not_found(self, mock_get, component, mock_evaluators):\\n        \\\"\\\"\\\"Test evaluation with non-existent evaluator.\\\"\\\"\\\"\\n        # Mock evaluators HTTP request\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"evaluators\\\": mock_evaluators}\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        component.api_key = \\\"test_api_key\\\"\\n        component.evaluator_name = \\\"non_existent_evaluator\\\"\\n\\n        result = await component.evaluate()\\n\\n        assert isinstance(result, Data)\\n        assert \\\"Selected evaluator 'non_existent_evaluator' not found\\\" in result.data[\\\"error\\\"]\\n\\n    @patch(\\\"lfx_bundles.langwatch.langwatch.httpx.get\\\")\\n    @respx.mock\\n    async def test_evaluate_http_error(self, mock_get, component, mock_evaluators):\\n        \\\"\\\"\\\"Test evaluation with HTTP error.\\\"\\\"\\\"\\n        # Mock evaluators HTTP request\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"evaluators\\\": mock_evaluators}\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        # Mock evaluation endpoint with error\\n        eval_url = \\\"https://app.langwatch.ai/api/evaluations/test_evaluator/evaluate\\\"\\n        respx.post(eval_url).mock(side_effect=httpx.RequestError(\\\"Connection failed\\\"))\\n\\n        component.api_key = \\\"test_api_key\\\"\\n        component.evaluator_name = \\\"test_evaluator\\\"\\n        component.input = \\\"test input\\\"\\n        component.output = \\\"test output\\\"\\n\\n        result = await component.evaluate()\\n\\n        assert isinstance(result, Data)\\n        assert \\\"Evaluation error\\\" in result.data[\\\"error\\\"]\\n\\n    @patch(\\\"lfx_bundles.langwatch.langwatch.httpx.get\\\")\\n    @respx.mock\\n    async def test_evaluate_with_tracing(self, mock_get, component, mock_evaluators):\\n        \\\"\\\"\\\"Test evaluation with tracing service.\\\"\\\"\\\"\\n        # Mock evaluators HTTP request\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"evaluators\\\": mock_evaluators}\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        # Mock evaluation endpoint\\n        eval_url = \\\"https://app.langwatch.ai/api/evaluations/test_evaluator/evaluate\\\"\\n        expected_response = {\\\"score\\\": 0.95, \\\"reasoning\\\": \\\"Good evaluation\\\"}\\n\\n        # Set up request capture\\n        request_data = None\\n\\n        def capture_request(request):\\n            nonlocal request_data\\n            request_data = json.loads(request.content.decode())\\n            return Response(200, json=expected_response)\\n\\n        respx.post(eval_url).mock(side_effect=capture_request)\\n\\n        # Set up component with mock tracing\\n        component.api_key = \\\"test_api_key\\\"\\n        component.evaluator_name = \\\"test_evaluator\\\"\\n        component.input = \\\"test input\\\"\\n        component.output = \\\"test output\\\"\\n\\n        # Mock tracing service\\n        mock_tracer = Mock()\\n        mock_tracer.trace_id = \\\"test_trace_id\\\"\\n        component._tracing_service = Mock()\\n        component._tracing_service.get_tracer.return_value = mock_tracer\\n\\n        result = await component.evaluate()\\n\\n        # Verify trace_id was included in the request\\n        assert request_data[\\\"settings\\\"][\\\"trace_id\\\"] == \\\"test_trace_id\\\"\\n        assert isinstance(result, Data)\\n        assert result.data == expected_response\\n\\n    @patch(\\\"lfx_bundles.langwatch.langwatch.httpx.get\\\")\\n    @respx.mock\\n    async def test_evaluate_with_contexts_parsing(self, mock_get, component, mock_evaluators):\\n        \\\"\\\"\\\"Test evaluation with contexts parsing.\\\"\\\"\\\"\\n        # Mock evaluators HTTP request\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"evaluators\\\": mock_evaluators}\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        # Mock evaluation endpoint\\n        eval_url = \\\"https://app.langwatch.ai/api/evaluations/test_evaluator/evaluate\\\"\\n        expected_response = {\\\"score\\\": 0.95, \\\"reasoning\\\": \\\"Good evaluation\\\"}\\n\\n        # Set up request capture\\n        request_data = None\\n\\n        def capture_request(request):\\n            nonlocal request_data\\n            request_data = json.loads(request.content.decode())\\n            return Response(200, json=expected_response)\\n\\n        respx.post(eval_url).mock(side_effect=capture_request)\\n\\n        # Set up component\\n        component.api_key = \\\"test_api_key\\\"\\n        component.evaluator_name = \\\"test_evaluator\\\"\\n        component.input = \\\"test input\\\"\\n        component.output = \\\"test output\\\"\\n        component.contexts = \\\"context1, context2, context3\\\"\\n\\n        result = await component.evaluate()\\n\\n        # Verify contexts were parsed correctly (contexts are split by comma, including whitespace)\\n        assert request_data[\\\"data\\\"][\\\"contexts\\\"] == [\\\"context1\\\", \\\" context2\\\", \\\" context3\\\"]\\n        assert isinstance(result, Data)\\n        assert result.data == expected_response\\n\\n    @patch(\\\"lfx_bundles.langwatch.langwatch.httpx.get\\\")\\n    @respx.mock\\n    async def test_evaluate_timeout_handling(self, mock_get, component, mock_evaluators):\\n        \\\"\\\"\\\"Test evaluation with timeout.\\\"\\\"\\\"\\n        # Mock evaluators HTTP request\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"evaluators\\\": mock_evaluators}\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        # Mock evaluation endpoint with timeout\\n        eval_url = \\\"https://app.langwatch.ai/api/evaluations/test_evaluator/evaluate\\\"\\n        respx.post(eval_url).mock(side_effect=httpx.TimeoutException(\\\"Request timed out\\\"))\\n\\n        component.api_key = \\\"test_api_key\\\"\\n        component.evaluator_name = \\\"test_evaluator\\\"\\n        component.input = \\\"test input\\\"\\n        component.output = \\\"test output\\\"\\n        component.timeout = 5\\n\\n        result = await component.evaluate()\\n\\n        assert isinstance(result, Data)\\n        assert \\\"Evaluation error\\\" in result.data[\\\"error\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/bundles/mem0/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"349cc32b07325efb96acbd63a847ccc1236d7212ac7674abce44efa54b8d5526\",\"content\":\"\\\"\\\"\\\"Tests for Mem0 components.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/bundles/nvidia/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"15364f38b4b1978bb2c6c61765cbcf339e936a2aef314d61d99327fe75fd11ff\",\"content\":\"\\\"\\\"\\\"NVIDIA components test package.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/bundles/twelvelabs/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"974ddc8c4abd20b57c87dd4d61a78438d50b4ffda82c614db1d129183dc94c68\",\"content\":\"\\\"\\\"\\\"Tests for TwelveLabs components.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/bundles/youtube/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/bundles/youtube/test_youtube_transcript_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8618defb69450117022a3a7fd85a5f181aec0a5afb27f1c276333764aeeded98\",\"content\":\"from unittest.mock import Mock, patch\\n\\nimport pytest\\n\\npytest.importorskip(\\\"lfx_bundles\\\")\\n\\nfrom lfx.components.youtube.youtube_transcripts import YouTubeTranscriptsComponent\\nfrom lfx.schema import Data, DataFrame, Message\\nfrom youtube_transcript_api import NoTranscriptFound, TranscriptsDisabled\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass FetchedTranscriptSnippetMock:\\n    \\\"\\\"\\\"Mock for youtube_transcript_api FetchedTranscriptSnippet.\\\"\\\"\\\"\\n\\n    def __init__(self, text: str, start: float, duration: float):\\n        self.text = text\\n        self.start = start\\n        self.duration = duration\\n\\n\\nclass TestYouTubeTranscriptsComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return YouTubeTranscriptsComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"url\\\": \\\"https://www.youtube.com/watch?v=test123\\\",\\n            \\\"chunk_size_seconds\\\": 60,\\n            \\\"translation\\\": \\\"\\\",\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return the file names mapping for different versions.\\\"\\\"\\\"\\n        return []\\n\\n    @pytest.fixture\\n    def mock_transcript_data(self):\\n        \\\"\\\"\\\"Return mock transcript data using new API format.\\\"\\\"\\\"\\n        return [\\n            FetchedTranscriptSnippetMock(\\\"First part of the transcript\\\", 0.0, 30.0),\\n            FetchedTranscriptSnippetMock(\\\"Second part of the transcript\\\", 30.0, 30.0),\\n            FetchedTranscriptSnippetMock(\\\"Third part of the transcript\\\", 60.0, 30.0),\\n        ]\\n\\n    @pytest.fixture\\n    def mock_transcript_list(self):\\n        \\\"\\\"\\\"Return mock transcript list.\\\"\\\"\\\"\\n        mock_transcript = Mock()\\n        mock_transcript.video_id = \\\"test123\\\"\\n        mock_transcript.language_code = \\\"en\\\"\\n        mock_transcript.language = \\\"English\\\"\\n\\n        mock_list = Mock()\\n        mock_list.find_transcript.return_value = mock_transcript\\n        mock_list.find_generated_transcript.return_value = mock_transcript\\n        return mock_list\\n\\n    def test_basic_setup(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test basic component initialization.\\\"\\\"\\\"\\n        component = component_class()\\n        component.set_attributes(default_kwargs)\\n        assert component.url == default_kwargs[\\\"url\\\"]\\n        assert component.chunk_size_seconds == default_kwargs[\\\"chunk_size_seconds\\\"]\\n        assert component.translation == default_kwargs[\\\"translation\\\"]\\n\\n    def test_extract_video_id_watch_url(self, component_class):\\n        \\\"\\\"\\\"Test video ID extraction from standard watch URL.\\\"\\\"\\\"\\n        component = component_class()\\n        component.set_attributes({\\\"url\\\": \\\"https://www.youtube.com/watch?v=abc123\\\"})\\n        video_id = component._extract_video_id(component.url)\\n        assert video_id == \\\"abc123\\\"\\n\\n    def test_extract_video_id_short_url(self, component_class):\\n        \\\"\\\"\\\"Test video ID extraction from short URL.\\\"\\\"\\\"\\n        component = component_class()\\n        component.set_attributes({\\\"url\\\": \\\"https://youtu.be/xyz789\\\"})\\n        video_id = component._extract_video_id(component.url)\\n        assert video_id == \\\"xyz789\\\"\\n\\n    def test_extract_video_id_embed_url(self, component_class):\\n        \\\"\\\"\\\"Test video ID extraction from embed URL.\\\"\\\"\\\"\\n        component = component_class()\\n        component.set_attributes({\\\"url\\\": \\\"https://www.youtube.com/embed/embed123\\\"})\\n        video_id = component._extract_video_id(component.url)\\n        assert video_id == \\\"embed123\\\"\\n\\n    def test_extract_video_id_with_params(self, component_class):\\n        \\\"\\\"\\\"Test video ID extraction from URL with extra parameters.\\\"\\\"\\\"\\n        component = component_class()\\n        component.set_attributes({\\\"url\\\": \\\"https://www.youtube.com/watch?v=param123&t=30s\\\"})\\n        video_id = component._extract_video_id(component.url)\\n        assert video_id == \\\"param123\\\"\\n\\n    def test_extract_video_id_invalid_url(self, component_class):\\n        \\\"\\\"\\\"Test video ID extraction from invalid URL.\\\"\\\"\\\"\\n        component = component_class()\\n        component.set_attributes({\\\"url\\\": \\\"https://example.com/not-a-youtube-url\\\"})\\n        with pytest.raises(ValueError, match=\\\"Could not extract video ID\\\"):\\n            component._extract_video_id(component.url)\\n\\n    @patch(\\\"lfx.components.youtube.youtube_transcripts.YouTubeTranscriptApi\\\")\\n    def test_get_dataframe_output_success(\\n        self, mock_api_class, component_class, default_kwargs, mock_transcript_data, mock_transcript_list\\n    ):\\n        \\\"\\\"\\\"Test successful DataFrame output generation.\\\"\\\"\\\"\\n        mock_api = Mock()\\n        mock_api.list.return_value = mock_transcript_list\\n        mock_api.fetch.return_value = mock_transcript_data\\n        mock_api_class.return_value = mock_api\\n\\n        component = component_class()\\n        component.set_attributes(default_kwargs)\\n        result = component.get_dataframe_output()\\n\\n        assert isinstance(result, DataFrame)\\n        result_df = result\\n        assert len(result_df) == 2  # Two chunks (0-60s and 60-90s)\\n        assert list(result_df.columns) == [\\\"timestamp\\\", \\\"text\\\"]\\n        assert result_df.iloc[0][\\\"timestamp\\\"] == \\\"00:00\\\"\\n        assert result_df.iloc[1][\\\"timestamp\\\"] == \\\"01:00\\\"\\n        assert \\\"First part\\\" in result_df.iloc[0][\\\"text\\\"]\\n        assert \\\"Third part\\\" in result_df.iloc[1][\\\"text\\\"]\\n\\n    @patch(\\\"lfx.components.youtube.youtube_transcripts.YouTubeTranscriptApi\\\")\\n    def test_get_message_output_success(\\n        self, mock_api_class, component_class, default_kwargs, mock_transcript_data, mock_transcript_list\\n    ):\\n        \\\"\\\"\\\"Test successful Message output generation.\\\"\\\"\\\"\\n        mock_api = Mock()\\n        mock_api.list.return_value = mock_transcript_list\\n        mock_api.fetch.return_value = mock_transcript_data\\n        mock_api_class.return_value = mock_api\\n\\n        component = component_class()\\n        component.set_attributes(default_kwargs)\\n        result = component.get_message_output()\\n\\n        assert isinstance(result, Message)\\n        assert \\\"First part of the transcript\\\" in result.text\\n        assert \\\"Second part of the transcript\\\" in result.text\\n        assert \\\"Third part of the transcript\\\" in result.text\\n\\n    @patch(\\\"lfx.components.youtube.youtube_transcripts.YouTubeTranscriptApi\\\")\\n    def test_get_data_output_success(\\n        self, mock_api_class, component_class, default_kwargs, mock_transcript_data, mock_transcript_list\\n    ):\\n        \\\"\\\"\\\"Test successful Data output generation.\\\"\\\"\\\"\\n        mock_api = Mock()\\n        mock_api.list.return_value = mock_transcript_list\\n        mock_api.fetch.return_value = mock_transcript_data\\n        mock_api_class.return_value = mock_api\\n\\n        component = component_class()\\n        component.set_attributes(default_kwargs)\\n        result = component.get_data_output()\\n\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"video_url\\\"] == default_kwargs[\\\"url\\\"]\\n        assert \\\"First part\\\" in result.data[\\\"transcript\\\"]\\n        assert \\\"Second part\\\" in result.data[\\\"transcript\\\"]\\n        assert \\\"Third part\\\" in result.data[\\\"transcript\\\"]\\n        assert \\\"error\\\" not in result.data\\n\\n    @patch(\\\"lfx.components.youtube.youtube_transcripts.YouTubeTranscriptApi\\\")\\n    def test_transcript_disabled_error(self, mock_api_class, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test handling of TranscriptsDisabled error.\\\"\\\"\\\"\\n        mock_api = Mock()\\n        mock_api.list.side_effect = TranscriptsDisabled(\\\"test123\\\")\\n        mock_api_class.return_value = mock_api\\n\\n        component = component_class()\\n        component.set_attributes(default_kwargs)\\n\\n        # Test DataFrame output\\n        df_result = component.get_dataframe_output()\\n        assert isinstance(df_result, DataFrame)\\n        assert len(df_result) == 1\\n        assert \\\"error\\\" in df_result.columns\\n        assert \\\"Failed to get YouTube transcripts\\\" in df_result[\\\"error\\\"][0]\\n\\n        # Test Message output\\n        msg_result = component.get_message_output()\\n        assert isinstance(msg_result, Message)\\n        assert \\\"Failed to get YouTube transcripts\\\" in msg_result.text\\n\\n        # Test Data output\\n        data_result = component.get_data_output()\\n        assert isinstance(data_result, Data)\\n        assert data_result.data[\\\"error\\\"] is not None\\n        assert data_result.data[\\\"transcript\\\"] == \\\"\\\"\\n\\n    @patch(\\\"lfx.components.youtube.youtube_transcripts.YouTubeTranscriptApi\\\")\\n    def test_no_transcript_found_error(self, mock_api_class, component_class, default_kwargs, mock_transcript_list):\\n        \\\"\\\"\\\"Test handling of NoTranscriptFound error.\\\"\\\"\\\"\\n        mock_transcript_list.find_transcript.side_effect = NoTranscriptFound(\\n            \\\"test123\\\", [\\\"en\\\"], {\\\"en\\\": {\\\"translationLanguages\\\": []}}\\n        )\\n        mock_transcript_list.find_generated_transcript.side_effect = NoTranscriptFound(\\n            \\\"test123\\\", [\\\"en\\\"], {\\\"en\\\": {\\\"translationLanguages\\\": []}}\\n        )\\n\\n        mock_api = Mock()\\n        mock_api.list.return_value = mock_transcript_list\\n        mock_api_class.return_value = mock_api\\n\\n        component = component_class()\\n        component.set_attributes(default_kwargs)\\n\\n        data_result = component.get_data_output()\\n        assert isinstance(data_result, Data)\\n        assert data_result.data[\\\"error\\\"] is not None\\n        assert data_result.data[\\\"transcript\\\"] == \\\"\\\"\\n\\n    def test_translation_setting(self, component_class):\\n        \\\"\\\"\\\"Test setting different translation languages.\\\"\\\"\\\"\\n        component = component_class()\\n        test_cases = [\\\"en\\\", \\\"es\\\", \\\"fr\\\", \\\"\\\"]\\n\\n        for lang in test_cases:\\n            component.set_attributes({\\\"url\\\": \\\"https://youtube.com/watch?v=test\\\", \\\"translation\\\": lang})\\n            assert component.translation == lang\\n\\n    @patch(\\\"lfx.components.youtube.youtube_transcripts.YouTubeTranscriptApi\\\")\\n    def test_empty_transcript_handling(self, mock_api_class, component_class, default_kwargs, mock_transcript_list):\\n        \\\"\\\"\\\"Test handling of empty transcript response.\\\"\\\"\\\"\\n        mock_api = Mock()\\n        mock_api.list.return_value = mock_transcript_list\\n        mock_api.fetch.return_value = []\\n        mock_api_class.return_value = mock_api\\n\\n        component = component_class()\\n        component.set_attributes(default_kwargs)\\n\\n        # Test Data output with empty transcript\\n        data_result = component.get_data_output()\\n        assert data_result.data[\\\"error\\\"] == \\\"No transcripts found.\\\"\\n        assert data_result.data[\\\"transcript\\\"] == \\\"\\\"\\n\\n        # Test DataFrame output with empty transcript\\n        df_result = component.get_dataframe_output()\\n        assert len(df_result) == 0\\n\\n    @patch(\\\"lfx.components.youtube.youtube_transcripts.YouTubeTranscriptApi\\\")\\n    def test_chunking_behavior(self, mock_api_class, component_class, default_kwargs, mock_transcript_list):\\n        \\\"\\\"\\\"Test transcript chunking with custom chunk size.\\\"\\\"\\\"\\n        # Create transcript data spanning 150 seconds\\n        mock_data = [\\n            FetchedTranscriptSnippetMock(\\\"Part 1\\\", 0.0, 30.0),\\n            FetchedTranscriptSnippetMock(\\\"Part 2\\\", 30.0, 30.0),\\n            FetchedTranscriptSnippetMock(\\\"Part 3\\\", 60.0, 30.0),\\n            FetchedTranscriptSnippetMock(\\\"Part 4\\\", 90.0, 30.0),\\n            FetchedTranscriptSnippetMock(\\\"Part 5\\\", 120.0, 30.0),\\n        ]\\n\\n        mock_api = Mock()\\n        mock_api.list.return_value = mock_transcript_list\\n        mock_api.fetch.return_value = mock_data\\n        mock_api_class.return_value = mock_api\\n\\n        # Test with 60-second chunks\\n        component = component_class()\\n        component.set_attributes({**default_kwargs, \\\"chunk_size_seconds\\\": 60})\\n        result = component.get_dataframe_output()\\n\\n        # Should have 3 chunks: 0-60s, 60-120s, 120-150s\\n        assert len(result) == 3\\n        assert result.iloc[0][\\\"timestamp\\\"] == \\\"00:00\\\"\\n        assert result.iloc[1][\\\"timestamp\\\"] == \\\"01:00\\\"\\n        assert result.iloc[2][\\\"timestamp\\\"] == \\\"02:00\\\"\\n\\n    @patch(\\\"lfx.components.youtube.youtube_transcripts.YouTubeTranscriptApi\\\")\\n    def test_translation_parameter(\\n        self, mock_api_class, component_class, default_kwargs, mock_transcript_list, mock_transcript_data\\n    ):\\n        \\\"\\\"\\\"Test transcript translation functionality.\\\"\\\"\\\"\\n        mock_translated = Mock()\\n        mock_translated.video_id = \\\"test123\\\"\\n        mock_translated.language_code = \\\"es\\\"\\n        mock_transcript_list.find_transcript.return_value.translate.return_value = mock_translated\\n\\n        mock_api = Mock()\\n        mock_api.list.return_value = mock_transcript_list\\n        mock_api.fetch.return_value = mock_transcript_data\\n        mock_api_class.return_value = mock_api\\n\\n        component = component_class()\\n        component.set_attributes({**default_kwargs, \\\"translation\\\": \\\"es\\\"})\\n        result = component.get_message_output()\\n\\n        # Verify translate was called\\n        mock_transcript_list.find_transcript.return_value.translate.assert_called_once_with(\\\"es\\\")\\n        assert isinstance(result, Message)\\n\\n    @patch(\\\"lfx.components.youtube.youtube_transcripts.YouTubeTranscriptApi\\\")\\n    def test_general_exception_handling(self, mock_api_class, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test handling of general exceptions.\\\"\\\"\\\"\\n        mock_api = Mock()\\n        mock_api.list.side_effect = RuntimeError(\\\"Network error\\\")\\n        mock_api_class.return_value = mock_api\\n\\n        component = component_class()\\n        component.set_attributes(default_kwargs)\\n\\n        result = component.get_data_output()\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"error\\\"] is not None\\n        assert \\\"Could not retrieve transcripts\\\" in str(result.data[\\\"error\\\"])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/codeagents/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/codeagents/test_codeagents_imports.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7233eb2b7448efba0fc5b629724e4d2313d78f69a4fd910794e9aeb10b42869b\",\"content\":\"import importlib\\nimport sys\\n\\nimport pytest\\n\\npytest.importorskip(\\\"lfx_bundles\\\")\\n\\n\\ndef test_codeagents_bundle_exposed_via_components_package():\\n    components = importlib.import_module(\\\"lfx.components\\\")\\n    assert hasattr(components, \\\"codeagents\\\"), \\\"codeagents bundle should be discoverable\\\"\\n\\n\\ndef test_codeagents_components_lazy_import():\\n    codeagents = importlib.import_module(\\\"lfx_bundles.codeagents\\\")\\n    # Ensure dynamic imports map includes both components\\n    assert hasattr(codeagents, \\\"CodeActAgentSmolagentsComponent\\\")\\n    assert hasattr(codeagents, \\\"OpenDsStarAgentComponent\\\")\\n\\n\\n@pytest.mark.parametrize(\\\"class_name\\\", [\\\"CodeActAgentSmolagentsComponent\\\", \\\"OpenDsStarAgentComponent\\\"])\\ndef test_codeagents_without_opendsstar_explain_manual_install(monkeypatch, class_name):\\n    \\\"\\\"\\\"Saved component classes still load; execution explains the explicit opt-in.\\\"\\\"\\\"\\n    monkeypatch.setitem(sys.modules, \\\"OpenDsStar\\\", None)\\n    codeagents = importlib.import_module(\\\"lfx_bundles.codeagents\\\")\\n    component = getattr(codeagents, class_name)()\\n\\n    with pytest.raises(ImportError, match=r\\\"uv pip install 'OpenDsStar==1\\\\.0\\\\.26' 'langchain-litellm==0\\\\.5\\\\.1'\\\"):\\n        component.create_agent_runnable()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/conftest.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0cb4c8236c663c0dea4ad4dc0bb86d79981948d849316a95e3b4f7c4f6d5a5dc\",\"content\":\"import importlib.util\\nimport sys\\nfrom types import ModuleType\\nfrom unittest.mock import MagicMock\\n\\nimport pytest\\n\\n\\n@pytest.fixture\\ndef fake_googleapiclient(monkeypatch):\\n    if importlib.util.find_spec(\\\"googleapiclient\\\") is not None:\\n        return\\n\\n    googleapiclient = ModuleType(\\\"googleapiclient\\\")\\n    googleapiclient.__path__ = []\\n\\n    discovery = ModuleType(\\\"googleapiclient.discovery\\\")\\n    discovery.build = MagicMock(name=\\\"build\\\")\\n\\n    http = ModuleType(\\\"googleapiclient.http\\\")\\n    http.MediaFileUpload = MagicMock(name=\\\"MediaFileUpload\\\")\\n    http.MediaIoBaseDownload = MagicMock(name=\\\"MediaIoBaseDownload\\\")\\n\\n    googleapiclient.discovery = discovery\\n    googleapiclient.http = http\\n\\n    monkeypatch.setitem(sys.modules, \\\"googleapiclient\\\", googleapiclient)\\n    monkeypatch.setitem(sys.modules, \\\"googleapiclient.discovery\\\", discovery)\\n    monkeypatch.setitem(sys.modules, \\\"googleapiclient.http\\\", http)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/data_source/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/data_source/table_schema_demo_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ff7eb2ec92f133a7317579e208ca3962cade4494eb6a9a73ad05ea5540fb18b8\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import Output, TableInput\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.table import Column\\n\\n\\nclass TableSchemaDemoComponent(Component):\\n    display_name = \\\"Table Schema Demo\\\"\\n    description = \\\"Demonstrates table column schema with load_from_db functionality for global variables\\\"\\n    icon = \\\"table\\\"\\n    name = \\\"TableSchemaDemo\\\"\\n\\n    inputs = [\\n        TableInput(\\n            name=\\\"table_data\\\",\\n            display_name=\\\"Table Data\\\",\\n            info=\\\"Table with schema defining which columns can load from global variables\\\",\\n            table_schema=[\\n                Column(\\n                    name=\\\"username\\\",\\n                    display_name=\\\"Username\\\",\\n                    type=\\\"text\\\",\\n                    default=\\\"admin\\\",\\n                    load_from_db=True,  # This column can load from global variables\\n                    description=\\\"Username that can be loaded from global variables\\\",\\n                ),\\n                Column(\\n                    name=\\\"email\\\",\\n                    display_name=\\\"Email Address\\\",\\n                    type=\\\"text\\\",\\n                    default=\\\"user@example.com\\\",\\n                    load_from_db=True,  # This column can load from global variables\\n                    description=\\\"Email address that can be loaded from global variables\\\",\\n                ),\\n                Column(\\n                    name=\\\"role\\\",\\n                    display_name=\\\"User Role\\\",\\n                    type=\\\"text\\\",\\n                    default=\\\"user\\\",\\n                    load_from_db=False,  # This column uses static default\\n                    description=\\\"User role with static default value\\\",\\n                ),\\n                Column(\\n                    name=\\\"active\\\",\\n                    display_name=\\\"Active Status\\\",\\n                    type=\\\"boolean\\\",\\n                    default=True,\\n                    load_from_db=False,  # This column uses static default\\n                    description=\\\"Whether the user is active\\\",\\n                ),\\n            ],\\n            value=[\\n                {\\\"username\\\": \\\"admin\\\", \\\"email\\\": \\\"admin@example.com\\\", \\\"role\\\": \\\"admin\\\", \\\"active\\\": True},\\n                {\\\"username\\\": \\\"user1\\\", \\\"email\\\": \\\"user1@example.com\\\", \\\"role\\\": \\\"user\\\", \\\"active\\\": True},\\n            ],\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"data_list\\\", display_name=\\\"Data List\\\", method=\\\"load_table_data\\\"),\\n        Output(name=\\\"schema_info\\\", display_name=\\\"Schema Info\\\", method=\\\"get_schema_info\\\"),\\n    ]\\n\\n    def load_table_data(self) -> list[Data]:\\n        \\\"\\\"\\\"Convert table input data to a list of Data objects.\\\"\\\"\\\"\\n        if not self.table_data:\\n            self.status = \\\"No table data provided.\\\"\\n            return []\\n\\n        try:\\n            # Convert each row in the table to a Data object\\n            result = []\\n            for i, row in enumerate(self.table_data):\\n                if isinstance(row, dict):\\n                    # Create Data object with the row data\\n                    data_obj = Data(data=row)\\n                    result.append(data_obj)\\n                elif isinstance(row, Data):\\n                    # Already a Data object, just add it\\n                    result.append(row)\\n                else:\\n                    # Try to convert to Data object\\n                    data_obj = Data(data={\\\"row\\\": str(row), \\\"index\\\": i})\\n                    result.append(data_obj)\\n\\n        except Exception as e:\\n            error_message = f\\\"Error processing table data: {e}\\\"\\n            self.status = error_message\\n            raise ValueError(error_message) from e\\n        else:\\n            self.status = f\\\"Successfully loaded {len(result)} rows from table data\\\"\\n            return result\\n\\n    def get_schema_info(self) -> Data:\\n        \\\"\\\"\\\"Return information about the table schema and which columns load from DB.\\\"\\\"\\\"\\n        try:\\n            # Get the table schema from the input\\n            table_input = getattr(self.inputs[0], \\\"table_schema\\\", None)\\n\\n            schema_info = {\\n                \\\"total_columns\\\": len(table_input) if table_input else 0,\\n                \\\"columns_with_load_from_db\\\": [],\\n                \\\"columns_with_static_defaults\\\": [],\\n            }\\n\\n            if table_input:\\n                for col in table_input:\\n                    col_info = {\\n                        \\\"name\\\": col.name,\\n                        \\\"display_name\\\": col.display_name,\\n                        \\\"type\\\": col.type,\\n                        \\\"default\\\": col.default,\\n                    }\\n\\n                    if col.load_from_db:\\n                        schema_info[\\\"columns_with_load_from_db\\\"].append(col_info)\\n                    else:\\n                        schema_info[\\\"columns_with_static_defaults\\\"].append(col_info)\\n            else:\\n                self.status = \\\"No table schema available\\\"\\n                return Data(data={\\\"error\\\": \\\"No table schema available\\\"})\\n\\n            return Data(data=schema_info)\\n\\n        except ValueError as e:\\n            error_message = f\\\"Error getting schema info: {e}\\\"\\n            self.status = error_message\\n            return Data(data={\\\"error\\\": error_message})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/data_source/test_api_request_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8b24dab11456dba4863482a97695400394c7568ade59472ec11484f7343ded11\",\"content\":\"import ipaddress\\nimport os\\nimport socket\\nfrom pathlib import Path\\nfrom unittest.mock import patch\\n\\nimport aiofiles\\nimport aiofiles.os\\nimport httpx\\nimport pytest\\nimport respx\\nfrom httpx import Response\\nfrom lfx.components.data_source.api_request import APIRequestComponent\\nfrom lfx.schema import Data\\nfrom lfx.schema.dotdict import dotdict\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestAPIRequestComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return APIRequestComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"url_input\\\": \\\"https://example.com/api/test\\\",\\n            \\\"method\\\": \\\"GET\\\",\\n            \\\"headers\\\": [{\\\"key\\\": \\\"User-Agent\\\", \\\"value\\\": \\\"test-agent\\\"}],\\n            \\\"body\\\": [],\\n            \\\"timeout\\\": 30,\\n            \\\"follow_redirects\\\": False,  # Changed default for SSRF security\\n            \\\"save_to_file\\\": False,\\n            \\\"include_httpx_metadata\\\": False,\\n            \\\"mode\\\": \\\"URL\\\",\\n            \\\"curl_input\\\": \\\"\\\",\\n            \\\"query_params\\\": {},\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    @pytest.fixture\\n    async def component(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Return a component instance.\\\"\\\"\\\"\\n        return component_class(**default_kwargs)\\n\\n    async def test_parse_curl(self, component):\\n        # Test basic curl command parsing\\n        curl_cmd = (\\n            \\\"curl -X GET https://example.com/api/test -H 'Content-Type: application/json' -d '{\\\\\\\"key\\\\\\\": \\\\\\\"value\\\\\\\"}'\\\"\\n        )\\n        build_config = dotdict(\\n            {\\n                \\\"method\\\": {\\\"value\\\": \\\"\\\"},\\n                \\\"url_input\\\": {\\\"value\\\": \\\"\\\"},\\n                \\\"headers\\\": {\\\"value\\\": []},\\n                \\\"body\\\": {\\\"value\\\": []},\\n            }\\n        )\\n        new_build_config = component.parse_curl(curl_cmd, build_config.copy())\\n\\n        assert new_build_config[\\\"method\\\"][\\\"value\\\"] == \\\"GET\\\"\\n        assert new_build_config[\\\"url_input\\\"][\\\"value\\\"] == \\\"https://example.com/api/test\\\"\\n        assert new_build_config[\\\"headers\\\"][\\\"value\\\"] == [{\\\"key\\\": \\\"Content-Type\\\", \\\"value\\\": \\\"application/json\\\"}]\\n        assert new_build_config[\\\"body\\\"][\\\"value\\\"] == [{\\\"key\\\": \\\"key\\\", \\\"value\\\": \\\"value\\\"}]\\n\\n    @respx.mock\\n    async def test_make_request_success(self, component):\\n        # Test successful request with JSON response\\n        url = \\\"https://example.com/api/test\\\"\\n        response_data = {\\\"key\\\": \\\"value\\\"}\\n        respx.get(url).mock(return_value=Response(200, json=response_data))\\n\\n        result = await component.make_request(\\n            client=httpx.AsyncClient(),\\n            method=\\\"GET\\\",\\n            url=url,\\n        )\\n\\n        assert isinstance(result, Data), result\\n        assert result.data[\\\"source\\\"] == url\\n        assert \\\"result\\\" in result.data, result.data\\n        assert result.data[\\\"result\\\"][\\\"key\\\"] == \\\"value\\\"\\n\\n    @respx.mock\\n    async def test_make_request_falls_back_when_json_is_not_utf8(self, component):\\n        url = \\\"https://example.com/api/test\\\"\\n        respx.get(url).mock(\\n            return_value=Response(\\n                200,\\n                content=b'{\\\"label\\\":\\\"caf\\\\xe9\\\"}',\\n                headers={\\\"Content-Type\\\": \\\"application/json\\\"},\\n            )\\n        )\\n\\n        result = await component.make_request(\\n            client=httpx.AsyncClient(),\\n            method=\\\"GET\\\",\\n            url=url,\\n        )\\n\\n        assert result.data[\\\"result\\\"].decode(\\\"utf-8\\\") == '{\\\"label\\\":\\\"caf\\\\ufffd\\\"}'\\n\\n    @respx.mock\\n    async def test_make_request_with_metadata(self, component):\\n        # Test request with metadata included\\n        url = \\\"https://example.com/api/test\\\"\\n        headers = {\\\"Custom-Header\\\": \\\"Value\\\"}\\n        response_data = {\\\"key\\\": \\\"value\\\"}\\n        respx.get(url).mock(return_value=Response(200, json=response_data, headers=headers))\\n\\n        result = await component.make_request(\\n            client=httpx.AsyncClient(),\\n            method=\\\"GET\\\",\\n            url=url,\\n            include_httpx_metadata=True,\\n        )\\n\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"source\\\"] == url\\n        assert result.data[\\\"status_code\\\"] == 200\\n        assert result.data[\\\"response_headers\\\"][\\\"custom-header\\\"] == \\\"Value\\\"\\n\\n    @respx.mock\\n    async def test_make_request_save_to_file(self, component):\\n        # Test saving response to file\\n        url = \\\"https://example.com/api/test\\\"\\n        content = \\\"Test content\\\"\\n        respx.get(url).mock(return_value=Response(200, text=content))\\n\\n        result = await component.make_request(\\n            client=httpx.AsyncClient(),\\n            method=\\\"GET\\\",\\n            url=url,\\n            save_to_file=True,\\n        )\\n\\n        assert isinstance(result, Data)\\n        assert \\\"file_path\\\" in result.data\\n        file_path = Path(result.data[\\\"file_path\\\"])\\n\\n        # Use async file operations\\n        assert await aiofiles.os.path.exists(file_path)\\n        async with aiofiles.open(file_path) as f:\\n            saved_content = await f.read()\\n        assert saved_content == content\\n\\n        # Cleanup using async operation\\n        await aiofiles.os.remove(file_path)\\n\\n    @respx.mock\\n    async def test_make_request_binary_response(self, component):\\n        # Test handling binary response\\n        url = \\\"https://example.com/api/binary\\\"\\n        binary_content = b\\\"Binary content\\\"\\n        headers = {\\\"Content-Type\\\": \\\"application/octet-stream\\\"}\\n        respx.get(url).mock(return_value=Response(200, content=binary_content, headers=headers))\\n\\n        result = await component.make_request(\\n            client=httpx.AsyncClient(),\\n            method=\\\"GET\\\",\\n            url=url,\\n        )\\n\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"source\\\"] == url\\n        assert result.data[\\\"result\\\"] == binary_content\\n\\n    @respx.mock\\n    async def test_make_request_timeout(self, component):\\n        # Test request timeout\\n        url = \\\"https://example.com/api/test\\\"\\n        respx.get(url).mock(side_effect=httpx.TimeoutException(\\\"Request timed out\\\"))\\n\\n        result = await component.make_request(\\n            client=httpx.AsyncClient(),\\n            method=\\\"GET\\\",\\n            url=url,\\n            timeout=1,\\n        )\\n\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"status_code\\\"] == 500\\n        assert \\\"Request timed out\\\" in result.data[\\\"error\\\"]\\n\\n    @respx.mock\\n    async def test_make_request_with_redirects(self, component):\\n        # Test handling redirects\\n        url = \\\"https://example.com/api/test\\\"\\n        redirect_url = \\\"https://example.com/api/redirect\\\"\\n        final_data = {\\\"key\\\": \\\"value\\\"}\\n\\n        respx.get(url).mock(return_value=Response(303, headers={\\\"Location\\\": redirect_url}))\\n        respx.get(redirect_url).mock(return_value=Response(200, json=final_data))\\n\\n        result = await component.make_request(\\n            client=httpx.AsyncClient(),\\n            method=\\\"GET\\\",\\n            url=url,\\n            include_httpx_metadata=True,\\n            follow_redirects=True,\\n        )\\n\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"source\\\"] == url\\n        assert result.data[\\\"status_code\\\"] == 200\\n        assert result.data[\\\"redirection_history\\\"] == [{\\\"url\\\": redirect_url, \\\"status_code\\\": 303}]\\n\\n    @respx.mock\\n    async def test_get_request_does_not_send_body(self, component):\\n        \\\"\\\"\\\"GET requests must not include a body (HTTP spec); avoids 413 with Cloudflare etc.\\\"\\\"\\\"\\n        url = \\\"https://example.com/api/test\\\"\\n        respx.get(url).mock(return_value=Response(200, json={\\\"ok\\\": True}))\\n\\n        await component.make_request(\\n            client=httpx.AsyncClient(),\\n            method=\\\"GET\\\",\\n            url=url,\\n            body={\\\"unused\\\": \\\"get-must-not-send-this\\\"},\\n        )\\n\\n        assert len(respx.calls) == 1\\n        request = respx.calls[0].request\\n        assert request.method == \\\"GET\\\"\\n        assert request.content == b\\\"\\\"\\n        assert request.headers.get(\\\"content-type\\\") is None\\n\\n    async def test_process_headers(self, component):\\n        # Test header processing\\n        headers_list = [\\n            {\\\"key\\\": \\\"Content-Type\\\", \\\"value\\\": \\\"application/json\\\"},\\n            {\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer token\\\"},\\n        ]\\n        processed = component._process_headers(headers_list)\\n        assert processed == {\\n            \\\"Content-Type\\\": \\\"application/json\\\",\\n            \\\"Authorization\\\": \\\"Bearer token\\\",\\n        }\\n\\n        # Test invalid headers\\n        assert component._process_headers(None) == {}\\n        assert component._process_headers([{\\\"invalid\\\": \\\"format\\\"}]) == {}\\n\\n    async def test_process_body(self, component):\\n        # Test body processing\\n        # Test dictionary body\\n        dict_body = {\\\"key\\\": \\\"value\\\", \\\"nested\\\": {\\\"inner\\\": \\\"value\\\"}}\\n        assert component._process_body(dict_body) == dict_body\\n\\n        # Test string body\\n        json_str = '{\\\"key\\\": \\\"value\\\"}'\\n        assert component._process_body(json_str) == {\\\"key\\\": \\\"value\\\"}\\n\\n        # Test list body\\n        list_body = [{\\\"key\\\": \\\"key1\\\", \\\"value\\\": \\\"value1\\\"}, {\\\"key\\\": \\\"key2\\\", \\\"value\\\": \\\"value2\\\"}]\\n        assert component._process_body(list_body) == {\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": \\\"value2\\\"}\\n\\n        # Test Data object body\\n        data_body = Data(data={\\\"id\\\": 123, \\\"name\\\": \\\"John Doe\\\"})\\n        assert component._process_body(data_body) == {\\\"id\\\": 123, \\\"name\\\": \\\"John Doe\\\"}\\n\\n        # Test nested Data object (Data containing dict)\\n        nested_data_body = Data(data={\\\"user\\\": {\\\"id\\\": 456, \\\"email\\\": \\\"test@example.com\\\"}})\\n        assert component._process_body(nested_data_body) == {\\\"user\\\": {\\\"id\\\": 456, \\\"email\\\": \\\"test@example.com\\\"}}\\n\\n        # Test invalid body\\n        assert component._process_body(None) == {}\\n        assert component._process_body([{\\\"invalid\\\": \\\"format\\\"}]) == {}\\n\\n    async def test_add_query_params(self, component):\\n        # Test query parameter handling\\n        url = \\\"https://example.com/api/test\\\"\\n        params = {\\\"param1\\\": \\\"value1\\\", \\\"param2\\\": \\\"value2\\\"}\\n        result = component.add_query_params(url, params)\\n        assert \\\"param1=value1\\\" in result\\n        assert \\\"param2=value2\\\" in result\\n\\n        # Test with existing query params\\n        url_with_params = \\\"https://example.com/api/test?existing=true\\\"\\n        result = component.add_query_params(url_with_params, params)\\n        assert \\\"existing=true\\\" in result\\n        assert \\\"param1=value1\\\" in result\\n        assert \\\"param2=value2\\\" in result\\n\\n    async def test_make_api_request(self, component):\\n        # Test making API requests\\n        url = \\\"https://example.com/api/test\\\"\\n        response_data = {\\\"key\\\": \\\"value\\\"}\\n\\n        with respx.mock:\\n            respx.get(url).mock(return_value=Response(200, json=response_data))\\n\\n            result = await component.make_api_request()\\n\\n            assert isinstance(result, Data)\\n            assert result.data[\\\"source\\\"] == url\\n            assert result.data[\\\"result\\\"][\\\"key\\\"] == \\\"value\\\"\\n\\n    async def test_invalid_urls(self, component):\\n        # Test invalid URL handling\\n        component.url_input = \\\"not_a_valid_url\\\"\\n        with pytest.raises(ValueError, match=\\\"Invalid URL provided\\\"):\\n            await component.make_api_request()\\n\\n    async def test_update_build_config(self, component):\\n        # Test build config updates\\n        build_config = dotdict(\\n            {\\n                \\\"method\\\": {\\\"value\\\": \\\"GET\\\", \\\"advanced\\\": False},\\n                \\\"url_input\\\": {\\\"value\\\": \\\"\\\", \\\"advanced\\\": False},\\n                \\\"headers\\\": {\\\"value\\\": [], \\\"advanced\\\": True},\\n                \\\"body\\\": {\\\"value\\\": [], \\\"advanced\\\": True},\\n                \\\"mode\\\": {\\\"value\\\": \\\"URL\\\", \\\"advanced\\\": False},\\n                \\\"curl_input\\\": {\\\"value\\\": \\\"curl -X GET https://example.com/api/test\\\", \\\"advanced\\\": True},\\n                \\\"timeout\\\": {\\\"value\\\": 30, \\\"advanced\\\": True},\\n                \\\"follow_redirects\\\": {\\\"value\\\": True, \\\"advanced\\\": True},\\n                \\\"save_to_file\\\": {\\\"value\\\": False, \\\"advanced\\\": True},\\n                \\\"include_httpx_metadata\\\": {\\\"value\\\": False, \\\"advanced\\\": True},\\n                \\\"query_params\\\": {\\\"value\\\": {}, \\\"advanced\\\": True},\\n            }\\n        )\\n\\n        # Test URL mode\\n        updated = component.update_build_config(build_config=build_config.copy(), field_value=\\\"URL\\\", field_name=\\\"mode\\\")\\n        assert updated[\\\"curl_input\\\"][\\\"advanced\\\"] is True\\n        assert updated[\\\"url_input\\\"][\\\"advanced\\\"] is False\\n\\n        # Set the component's curl_input attribute to match the build_config before switching to cURL mode\\n        component.curl_input = build_config[\\\"curl_input\\\"][\\\"value\\\"]\\n        # Test cURL mode\\n        updated = component.update_build_config(build_config=build_config.copy(), field_value=\\\"cURL\\\", field_name=\\\"mode\\\")\\n        assert updated[\\\"curl_input\\\"][\\\"advanced\\\"] is False\\n        assert updated[\\\"url_input\\\"][\\\"advanced\\\"] is True\\n\\n    @respx.mock\\n    async def test_error_handling(self, component):\\n        # Test various error scenarios\\n        url = \\\"https://example.com/api/test\\\"\\n\\n        # Test connection error\\n        respx.get(url).mock(side_effect=httpx.ConnectError(\\\"Connection failed\\\"))\\n        result = await component.make_request(\\n            client=httpx.AsyncClient(),\\n            method=\\\"GET\\\",\\n            url=url,\\n        )\\n        assert result.data[\\\"status_code\\\"] == 500\\n        assert \\\"Connection failed\\\" in result.data[\\\"error\\\"]\\n\\n        # Test invalid method\\n        with pytest.raises(ValueError, match=\\\"Unsupported method\\\"):\\n            await component.make_request(\\n                client=httpx.AsyncClient(),\\n                method=\\\"INVALID\\\",\\n                url=url,\\n            )\\n\\n    async def test_response_info(self, component):\\n        # Test response info handling\\n        url = \\\"https://example.com/api/test\\\"\\n        request = httpx.Request(\\\"GET\\\", url)\\n        response = Response(200, text=\\\"test content\\\", request=request)\\n        is_binary, file_path = await component._response_info(response, with_file_path=True)\\n\\n        assert not is_binary\\n        assert file_path is not None\\n        assert file_path.suffix == \\\".txt\\\"\\n\\n        # Test binary response\\n        binary_response = Response(\\n            200, content=b\\\"binary content\\\", headers={\\\"Content-Type\\\": \\\"application/octet-stream\\\"}, request=request\\n        )\\n        is_binary, file_path = await component._response_info(binary_response, with_file_path=True)\\n\\n        assert is_binary\\n        assert file_path is not None\\n        assert file_path.suffix == \\\".bin\\\"\\n\\n    async def test_response_info_content_disposition_path_traversal(self, component):\\n        \\\"\\\"\\\"A malicious Content-Disposition filename must not escape the component temp dir.\\n\\n        Regression for GHSA-h3c6-fqr4-m99p path traversal.\\n        \\\"\\\"\\\"\\n        import tempfile\\n        from pathlib import Path\\n\\n        component_temp_dir = Path(tempfile.gettempdir()) / component.__class__.__name__\\n        request = httpx.Request(\\\"GET\\\", \\\"https://example.com/download\\\")\\n        malicious = Response(\\n            200,\\n            content=b\\\"payload\\\",\\n            headers={\\\"Content-Disposition\\\": 'attachment; filename=\\\"../../../../tmp/evil.sh\\\"'},\\n            request=request,\\n        )\\n\\n        _, file_path = await component._response_info(malicious, with_file_path=True)\\n\\n        assert file_path is not None\\n        # The filename was reduced to its basename, so the file stays inside the temp dir.\\n        assert file_path.parent.resolve() == component_temp_dir.resolve()\\n        assert file_path.name.endswith(\\\"evil.sh\\\")\\n        assert \\\"..\\\" not in file_path.parts\\n\\n    async def test_response_info_content_disposition_backslash_traversal(self, component):\\n        \\\"\\\"\\\"Windows-style backslash separators must also be reduced to the basename.\\n\\n        On POSIX, ``Path(...).name`` treats backslashes as ordinary filename\\n        characters, so the header value must be normalized before stripping\\n        directory parts. Regression for GHSA-h3c6-fqr4-m99p path traversal.\\n        \\\"\\\"\\\"\\n        import tempfile\\n        from pathlib import Path\\n\\n        component_temp_dir = Path(tempfile.gettempdir()) / component.__class__.__name__\\n        request = httpx.Request(\\\"GET\\\", \\\"https://example.com/download\\\")\\n        malicious = Response(\\n            200,\\n            content=b\\\"payload\\\",\\n            headers={\\\"Content-Disposition\\\": r'attachment; filename=\\\"..\\\\..\\\\..\\\\..\\\\tmp\\\\evil.sh\\\"'},\\n            request=request,\\n        )\\n\\n        _, file_path = await component._response_info(malicious, with_file_path=True)\\n\\n        assert file_path is not None\\n        assert file_path.parent.resolve() == component_temp_dir.resolve()\\n        assert file_path.name.endswith(\\\"evil.sh\\\")\\n        assert \\\"\\\\\\\\\\\" not in file_path.name\\n        assert \\\"..\\\" not in file_path.parts\\n\\n    async def test_response_info_content_disposition_null_byte(self, component):\\n        \\\"\\\"\\\"A NUL byte in the Content-Disposition filename must be stripped, not crash.\\n\\n        A NUL byte survives ``Path(...).name`` and would otherwise make the\\n        defense-in-depth ``.resolve()`` raise a cryptic \\\"embedded null character\\\"\\n        ValueError. It must be stripped so the path stays inside the temp dir and\\n        the file is written cleanly. Regression for GHSA-h3c6-fqr4-m99p.\\n        \\\"\\\"\\\"\\n        import tempfile\\n        from pathlib import Path\\n\\n        component_temp_dir = Path(tempfile.gettempdir()) / component.__class__.__name__\\n        request = httpx.Request(\\\"GET\\\", \\\"https://example.com/download\\\")\\n        malicious = Response(\\n            200,\\n            content=b\\\"payload\\\",\\n            headers={\\\"Content-Disposition\\\": 'attachment; filename=\\\"evil\\\\x00.sh\\\"'},\\n            request=request,\\n        )\\n\\n        _, file_path = await component._response_info(malicious, with_file_path=True)\\n\\n        assert file_path is not None\\n        assert file_path.parent.resolve() == component_temp_dir.resolve()\\n        assert \\\"\\\\x00\\\" not in str(file_path)\\n        assert file_path.name.endswith(\\\"evil.sh\\\")\\n        assert \\\"..\\\" not in file_path.parts\\n\\n\\nclass TestAPIRequestSSRFProtection:\\n    \\\"\\\"\\\"Rewritten SSRF Protection Tests for API Request Component.\\n\\n    These tests properly test the actual SSRF protection implementation without mocking\\n    the core security functions. They verify:\\n    1. Real SSRF blocking with actual private IPs\\n    2. DNS pinning actually prevents rebinding\\n    3. Allowlist functionality works correctly\\n    4. Custom transport is used when protection is enabled.\\n    \\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return APIRequestComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"url_input\\\": \\\"https://example.com/api/test\\\",\\n            \\\"method\\\": \\\"GET\\\",\\n            \\\"headers\\\": [],\\n            \\\"body\\\": [],\\n            \\\"timeout\\\": 30,\\n            \\\"follow_redirects\\\": False,\\n            \\\"save_to_file\\\": False,\\n            \\\"include_httpx_metadata\\\": False,\\n            \\\"mode\\\": \\\"URL\\\",\\n            \\\"curl_input\\\": \\\"\\\",\\n            \\\"query_params\\\": {},\\n        }\\n\\n    @pytest.fixture\\n    async def component(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Return a component instance.\\\"\\\"\\\"\\n        return component_class(**default_kwargs)\\n\\n    async def test_ssrf_protection_disabled_allows_all_urls(self, component):\\n        \\\"\\\"\\\"Test that when SSRF protection is disabled, all URLs are allowed.\\\"\\\"\\\"\\n        component.url_input = \\\"http://127.0.0.1:8080\\\"\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"false\\\"}),\\n            respx.mock,\\n        ):\\n            respx.get(\\\"http://127.0.0.1:8080\\\").mock(return_value=Response(200, json={\\\"status\\\": \\\"ok\\\"}))\\n\\n            result = await component.make_api_request()\\n            assert isinstance(result, Data)\\n            assert result.data[\\\"result\\\"][\\\"status\\\"] == \\\"ok\\\"\\n\\n    async def test_ssrf_protection_blocks_localhost_127_0_0_1(self, component):\\n        \\\"\\\"\\\"Test that SSRF protection blocks 127.0.0.1 (localhost).\\\"\\\"\\\"\\n        component.url_input = \\\"http://127.0.0.1:8080/admin\\\"\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            pytest.raises(ValueError, match=\\\"SSRF Protection\\\"),\\n        ):\\n            await component.make_api_request()\\n\\n    async def test_ssrf_protection_blocks_localhost_0_0_0_0(self, component):\\n        \\\"\\\"\\\"Test that SSRF protection blocks 0.0.0.0.\\\"\\\"\\\"\\n        component.url_input = \\\"http://0.0.0.0:8080/admin\\\"\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            pytest.raises(ValueError, match=\\\"SSRF Protection\\\"),\\n        ):\\n            await component.make_api_request()\\n\\n    async def test_ssrf_protection_blocks_private_network_192_168(self, component):\\n        \\\"\\\"\\\"Test that SSRF protection blocks 192.168.x.x private network.\\\"\\\"\\\"\\n        component.url_input = \\\"http://192.168.1.1/config\\\"\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            pytest.raises(ValueError, match=\\\"SSRF Protection\\\"),\\n        ):\\n            await component.make_api_request()\\n\\n    async def test_ssrf_protection_blocks_private_network_10_0(self, component):\\n        \\\"\\\"\\\"Test that SSRF protection blocks 10.x.x.x private network.\\\"\\\"\\\"\\n        component.url_input = \\\"http://10.0.0.1/admin\\\"\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            pytest.raises(ValueError, match=\\\"SSRF Protection\\\"),\\n        ):\\n            await component.make_api_request()\\n\\n    async def test_ssrf_protection_blocks_private_network_172_16(self, component):\\n        \\\"\\\"\\\"Test that SSRF protection blocks 172.16.x.x private network.\\\"\\\"\\\"\\n        component.url_input = \\\"http://172.16.0.1/internal\\\"\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            pytest.raises(ValueError, match=\\\"SSRF Protection\\\"),\\n        ):\\n            await component.make_api_request()\\n\\n    async def test_ssrf_protection_blocks_cloud_metadata_endpoint(self, component):\\n        \\\"\\\"\\\"Test that SSRF protection blocks AWS/GCP metadata endpoint.\\\"\\\"\\\"\\n        component.url_input = \\\"http://169.254.169.254/latest/meta-data/\\\"\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            pytest.raises(ValueError, match=\\\"SSRF Protection\\\"),\\n        ):\\n            await component.make_api_request()\\n\\n    async def test_ssrf_protection_blocks_link_local_169_254(self, component):\\n        \\\"\\\"\\\"Test that SSRF protection blocks link-local addresses.\\\"\\\"\\\"\\n        component.url_input = \\\"http://169.254.1.1/api\\\"\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            pytest.raises(ValueError, match=\\\"SSRF Protection\\\"),\\n        ):\\n            await component.make_api_request()\\n\\n    @respx.mock\\n    async def test_ssrf_protection_allows_public_urls(self, component):\\n        \\\"\\\"\\\"Test that SSRF protection allows legitimate public URLs.\\\"\\\"\\\"\\n        public_urls = [\\n            \\\"https://api.openai.com/v1/chat/completions\\\",\\n            \\\"https://api.github.com/repos/langflow-ai/langflow\\\",\\n            \\\"https://www.google.com\\\",\\n        ]\\n\\n        with patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}):\\n            for url in public_urls:\\n                component.url_input = url\\n                respx.get(url).mock(return_value=Response(200, json={\\\"status\\\": \\\"ok\\\"}))\\n\\n                result = await component.make_api_request()\\n                assert isinstance(result, Data)\\n                assert result.data[\\\"result\\\"][\\\"status\\\"] == \\\"ok\\\"\\n\\n    async def test_ssrf_allowlist_hostname(self, component):\\n        \\\"\\\"\\\"Test that allowlisted hostnames bypass SSRF protection.\\\"\\\"\\\"\\n        component.url_input = \\\"http://internal.company.local/api\\\"\\n\\n        with (\\n            patch.dict(\\n                os.environ,\\n                {\\n                    \\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\",\\n                    \\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\": \\\"internal.company.local\\\",\\n                },\\n            ),\\n            respx.mock,\\n        ):\\n            respx.get(\\\"http://internal.company.local/api\\\").mock(return_value=Response(200, json={\\\"status\\\": \\\"ok\\\"}))\\n\\n            result = await component.make_api_request()\\n            assert isinstance(result, Data)\\n            assert result.data[\\\"result\\\"][\\\"status\\\"] == \\\"ok\\\"\\n\\n    async def test_ssrf_allowlist_ip_address(self, component):\\n        \\\"\\\"\\\"Test that allowlisted IP addresses bypass SSRF protection.\\\"\\\"\\\"\\n        component.url_input = \\\"http://192.168.1.100/api\\\"\\n\\n        with (\\n            patch.dict(\\n                os.environ,\\n                {\\n                    \\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\",\\n                    \\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\": \\\"192.168.1.100\\\",\\n                },\\n            ),\\n            respx.mock,\\n        ):\\n            respx.get(\\\"http://192.168.1.100/api\\\").mock(return_value=Response(200, json={\\\"status\\\": \\\"ok\\\"}))\\n\\n            result = await component.make_api_request()\\n            assert isinstance(result, Data)\\n            assert result.data[\\\"result\\\"][\\\"status\\\"] == \\\"ok\\\"\\n\\n    async def test_ssrf_allowlist_cidr_range(self, component):\\n        \\\"\\\"\\\"Test that CIDR ranges in allowlist work correctly.\\\"\\\"\\\"\\n        component.url_input = \\\"http://192.168.1.5/api\\\"\\n\\n        with (\\n            patch.dict(\\n                os.environ,\\n                {\\n                    \\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\",\\n                    \\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\": \\\"192.168.1.0/24\\\",\\n                },\\n            ),\\n            respx.mock,\\n        ):\\n            respx.get(\\\"http://192.168.1.5/api\\\").mock(return_value=Response(200, json={\\\"status\\\": \\\"ok\\\"}))\\n\\n            result = await component.make_api_request()\\n            assert isinstance(result, Data)\\n            assert result.data[\\\"result\\\"][\\\"status\\\"] == \\\"ok\\\"\\n\\n    async def test_ssrf_allowlist_multiple_entries(self, component):\\n        \\\"\\\"\\\"Test that multiple allowlist entries work correctly.\\\"\\\"\\\"\\n        component.url_input = \\\"http://192.168.1.5/api\\\"\\n\\n        with (\\n            patch.dict(\\n                os.environ,\\n                {\\n                    \\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\",\\n                    \\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\": \\\"localhost,192.168.1.0/24,internal.local\\\",\\n                },\\n            ),\\n            respx.mock,\\n        ):\\n            respx.get(\\\"http://192.168.1.5/api\\\").mock(return_value=Response(200, json={\\\"status\\\": \\\"ok\\\"}))\\n\\n            result = await component.make_api_request()\\n            assert isinstance(result, Data)\\n\\n    async def test_dns_pinning_is_used_when_protection_enabled(self, component):\\n        \\\"\\\"\\\"Test that DNS pinning (custom transport) is used when SSRF protection is enabled.\\\"\\\"\\\"\\n        from unittest.mock import AsyncMock\\n\\n        component.url_input = \\\"https://example.com/api\\\"\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"lfx.components.data_source.api_request.create_ssrf_protected_client\\\") as mock_create_client,\\n            respx.mock,\\n        ):\\n            # Mock the context manager returned by create_ssrf_protected_client\\n            mock_client = AsyncMock()\\n            mock_client.__aenter__.return_value = mock_client\\n            mock_client.__aexit__.return_value = None\\n            mock_create_client.return_value = mock_client\\n\\n            # Mock the make_request to return a Data object\\n            component.make_request = AsyncMock(return_value=Data(data={\\\"status\\\": \\\"ok\\\"}))\\n\\n            await component.make_api_request()\\n\\n            # Verify that create_ssrf_protected_client was called (DNS pinning is used)\\n            mock_create_client.assert_called_once()\\n            call_kwargs = mock_create_client.call_args[1]\\n            assert call_kwargs[\\\"hostname\\\"] == \\\"example.com\\\"\\n            assert len(call_kwargs[\\\"validated_ips\\\"]) > 0  # Should have validated IPs\\n\\n    async def test_normal_client_used_when_protection_disabled(self, component):\\n        \\\"\\\"\\\"Test that normal httpx client is used when SSRF protection is disabled.\\\"\\\"\\\"\\n        component.url_input = \\\"https://example.com/api\\\"\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"false\\\"}),\\n            patch(\\\"lfx.components.data_source.api_request.create_ssrf_protected_client\\\") as mock_create_client,\\n            respx.mock,\\n        ):\\n            respx.get(\\\"https://example.com/api\\\").mock(return_value=Response(200, json={\\\"status\\\": \\\"ok\\\"}))\\n\\n            result = await component.make_api_request()\\n\\n            # Verify that create_ssrf_protected_client was NOT called\\n            mock_create_client.assert_not_called()\\n            assert isinstance(result, Data)\\n\\n    async def test_follow_redirects_security_warning(self, component):\\n        \\\"\\\"\\\"Test that enabling follow_redirects logs a security warning.\\\"\\\"\\\"\\n        from unittest.mock import MagicMock\\n\\n        component.url_input = \\\"https://example.com/api\\\"\\n        component.follow_redirects = True\\n        component.log = MagicMock()\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"false\\\"}),\\n            respx.mock,\\n        ):\\n            respx.get(\\\"https://example.com/api\\\").mock(return_value=Response(200, json={\\\"status\\\": \\\"ok\\\"}))\\n\\n            await component.make_api_request()\\n\\n            # Verify security warning was logged\\n            component.log.assert_called()\\n            all_log_messages = [call[0][0] for call in component.log.call_args_list]\\n            security_warning_found = any(\\\"Security Warning\\\" in msg and \\\"SSRF bypass\\\" in msg for msg in all_log_messages)\\n            assert security_warning_found, f\\\"Security warning not found in: {all_log_messages}\\\"\\n\\n    async def test_url_normalization_adds_https(self, component):\\n        \\\"\\\"\\\"Test that URLs without protocol get normalized to https://.\\\"\\\"\\\"\\n        component.url_input = \\\"example.com\\\"\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"false\\\"}),\\n            respx.mock,\\n        ):\\n            respx.get(\\\"https://example.com\\\").mock(return_value=Response(200, json={\\\"status\\\": \\\"ok\\\"}))\\n\\n            result = await component.make_api_request()\\n            assert result.data[\\\"source\\\"] == \\\"https://example.com\\\"\\n\\n    async def test_url_normalization_preserves_http(self, component):\\n        \\\"\\\"\\\"Test that http:// protocol is preserved.\\\"\\\"\\\"\\n        component.url_input = \\\"http://example.com\\\"\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"false\\\"}),\\n            respx.mock,\\n        ):\\n            respx.get(\\\"http://example.com\\\").mock(return_value=Response(200, json={\\\"status\\\": \\\"ok\\\"}))\\n\\n            result = await component.make_api_request()\\n            assert result.data[\\\"source\\\"] == \\\"http://example.com\\\"\\n\\n    async def test_invalid_url_raises_error(self, component):\\n        \\\"\\\"\\\"Test that invalid URLs raise ValueError.\\\"\\\"\\\"\\n        component.url_input = \\\"not_a_valid_url\\\"\\n\\n        with pytest.raises(ValueError, match=\\\"Invalid URL provided\\\"):\\n            await component.make_api_request()\\n\\n    async def test_follow_redirects_disabled_by_default(self, component):\\n        \\\"\\\"\\\"Test that follow_redirects is disabled by default for security.\\\"\\\"\\\"\\n        assert component.follow_redirects is False\\n\\n\\ndef _resolve_public(host, *_args, **_kwargs):\\n    \\\"\\\"\\\"socket.getaddrinfo stub: hostnames resolve to a public IP, literal IPs to themselves.\\n\\n    Mirrors real DNS: the public redirector hostnames map to a public address, while a\\n    literal IP (e.g. an internal 127.0.0.1 / 192.168.x redirect target) resolves to\\n    itself so SSRF validation still classifies it as internal.\\n    \\\"\\\"\\\"\\n    try:\\n        ipaddress.ip_address(host)\\n    except ValueError:\\n        ip = \\\"93.184.216.34\\\"  # hostname -> public IP\\n    else:\\n        ip = host  # literal IP -> itself\\n    family = socket.AF_INET6 if \\\":\\\" in ip else socket.AF_INET\\n    return [(family, socket.SOCK_STREAM, 6, \\\"\\\", (ip, 0))]\\n\\n\\nclass TestAPIRequestRedirectSSRFProtection:\\n    \\\"\\\"\\\"Regression tests for the SSRF redirect-following bypass.\\n\\n    When SSRF protection is enabled, a validated public URL must not be able to reach\\n    internal services by redirecting to them. The component follows redirects manually\\n    and re-validates every hop with the same denylist + DNS pinning used for the\\n    initial request, instead of trusting httpx to auto-follow unvalidated redirects.\\n    \\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component(self):\\n        \\\"\\\"\\\"Return a component configured to follow redirects.\\\"\\\"\\\"\\n        return APIRequestComponent(\\n            url_input=\\\"http://public.example.com/start\\\",\\n            method=\\\"GET\\\",\\n            headers=[],\\n            body=[],\\n            timeout=30,\\n            follow_redirects=True,\\n            save_to_file=False,\\n            include_httpx_metadata=True,\\n            mode=\\\"URL\\\",\\n            curl_input=\\\"\\\",\\n            query_params={},\\n        )\\n\\n    @respx.mock\\n    @pytest.mark.parametrize(\\n        (\\\"internal_url\\\", \\\"description\\\"),\\n        [\\n            (\\\"http://127.0.0.1:9999/secret\\\", \\\"loopback\\\"),\\n            (\\\"http://192.168.0.10/admin\\\", \\\"rfc1918-192\\\"),\\n            (\\\"http://10.0.0.5/internal\\\", \\\"rfc1918-10\\\"),\\n            (\\\"http://172.16.0.9/internal\\\", \\\"rfc1918-172\\\"),\\n            (\\\"http://169.254.169.254/latest/meta-data/\\\", \\\"link-local-metadata\\\"),\\n            (\\\"http://0.0.0.0:8080/admin\\\", \\\"unspecified\\\"),\\n        ],\\n    )\\n    async def test_redirect_to_internal_address_is_blocked(self, component, internal_url, description):\\n        \\\"\\\"\\\"A public URL that redirects to an internal address must be blocked, not followed.\\\"\\\"\\\"\\n        marker = \\\"INTERNAL_REDIRECT_SECRET_7a51f4\\\"\\n        respx.get(\\\"http://public.example.com/start\\\").mock(\\n            return_value=Response(302, headers={\\\"Location\\\": internal_url})\\n        )\\n        # If the fix regresses, the component would follow the redirect and serve this marker.\\n        internal_route = respx.get(internal_url).mock(return_value=Response(200, text=marker))\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            pytest.raises(ValueError, match=\\\"blocked redirect\\\"),\\n        ):\\n            await component.make_api_request()\\n\\n        assert not internal_route.called, f\\\"Redirect to {description} ({internal_url}) must not be followed\\\"\\n\\n    @respx.mock\\n    async def test_redirect_scheme_change_is_blocked(self, component):\\n        \\\"\\\"\\\"A redirect that switches to a non-http(s) scheme (e.g. file://) must be blocked.\\\"\\\"\\\"\\n        respx.get(\\\"http://public.example.com/start\\\").mock(\\n            return_value=Response(302, headers={\\\"Location\\\": \\\"file:///etc/passwd\\\"})\\n        )\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            pytest.raises(ValueError, match=\\\"blocked redirect\\\"),\\n        ):\\n            await component.make_api_request()\\n\\n    @respx.mock\\n    async def test_redirect_to_hostname_resolving_internal_is_blocked(self, component):\\n        \\\"\\\"\\\"A redirect to a hostname that resolves to an internal IP must be blocked.\\n\\n        Covers the DNS-rebinding-across-hops vector at the validation layer: the redirect\\n        target host resolves to a blocked address and is rejected before any connection.\\n        \\\"\\\"\\\"\\n\\n        def resolve(host, *_args, **_kwargs):\\n            ip = \\\"127.0.0.1\\\" if host == \\\"internal.example.com\\\" else \\\"93.184.216.34\\\"\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (ip, 0))]\\n\\n        respx.get(\\\"http://public.example.com/start\\\").mock(\\n            return_value=Response(302, headers={\\\"Location\\\": \\\"http://internal.example.com/secret\\\"})\\n        )\\n        internal_route = respx.get(\\\"http://internal.example.com/secret\\\").mock(return_value=Response(200, text=\\\"SECRET\\\"))\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=resolve),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            pytest.raises(ValueError, match=\\\"blocked redirect\\\"),\\n        ):\\n            await component.make_api_request()\\n\\n        assert not internal_route.called\\n\\n    @respx.mock\\n    async def test_chained_public_redirects_are_followed(self, component):\\n        \\\"\\\"\\\"Legitimate public-to-public redirect chains still work (redirects are not disabled).\\\"\\\"\\\"\\n        component.url_input = \\\"http://hop1.example.com/a\\\"\\n        respx.get(\\\"http://hop1.example.com/a\\\").mock(\\n            return_value=Response(302, headers={\\\"Location\\\": \\\"http://hop2.example.com/b\\\"})\\n        )\\n        respx.get(\\\"http://hop2.example.com/b\\\").mock(\\n            return_value=Response(307, headers={\\\"Location\\\": \\\"http://hop3.example.com/c\\\"})\\n        )\\n        respx.get(\\\"http://hop3.example.com/c\\\").mock(return_value=Response(200, json={\\\"status\\\": \\\"ok\\\"}))\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n        ):\\n            result = await component.make_api_request()\\n\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"status_code\\\"] == 200\\n        assert result.data[\\\"result\\\"][\\\"status\\\"] == \\\"ok\\\"\\n        assert result.data[\\\"redirection_history\\\"] == [\\n            {\\\"url\\\": \\\"http://hop2.example.com/b\\\", \\\"status_code\\\": 302},\\n            {\\\"url\\\": \\\"http://hop3.example.com/c\\\", \\\"status_code\\\": 307},\\n        ]\\n\\n    @respx.mock\\n    async def test_too_many_redirects_raises(self, component):\\n        \\\"\\\"\\\"A redirect loop is bounded and raises instead of looping forever.\\\"\\\"\\\"\\n        component.url_input = \\\"http://loop.example.com/a\\\"\\n        respx.get(\\\"http://loop.example.com/a\\\").mock(\\n            return_value=Response(302, headers={\\\"Location\\\": \\\"http://loop.example.com/b\\\"})\\n        )\\n        respx.get(\\\"http://loop.example.com/b\\\").mock(\\n            return_value=Response(302, headers={\\\"Location\\\": \\\"http://loop.example.com/a\\\"})\\n        )\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            pytest.raises(ValueError, match=\\\"exceeded the maximum\\\"),\\n        ):\\n            await component.make_api_request()\\n\\n    @respx.mock\\n    async def test_redirect_to_internal_allowed_when_protection_disabled(self, component):\\n        \\\"\\\"\\\"With SSRF protection disabled, redirect behavior is unchanged (user opted out).\\\"\\\"\\\"\\n        respx.get(\\\"http://public.example.com/start\\\").mock(\\n            return_value=Response(302, headers={\\\"Location\\\": \\\"http://127.0.0.1:9999/ok\\\"})\\n        )\\n        respx.get(\\\"http://127.0.0.1:9999/ok\\\").mock(return_value=Response(200, json={\\\"status\\\": \\\"reached\\\"}))\\n\\n        with patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"false\\\"}):\\n            result = await component.make_api_request()\\n\\n        assert result.data[\\\"status_code\\\"] == 200\\n        assert result.data[\\\"result\\\"][\\\"status\\\"] == \\\"reached\\\"\\n\\n    @respx.mock\\n    async def test_sensitive_headers_dropped_on_cross_host_redirect(self, component):\\n        \\\"\\\"\\\"Authorization/Cookie must not be forwarded to a different host on redirect.\\\"\\\"\\\"\\n        component.headers = [\\n            {\\\"key\\\": \\\"Authorization\\\", \\\"value\\\": \\\"Bearer secret-token\\\"},\\n            {\\\"key\\\": \\\"X-Custom\\\", \\\"value\\\": \\\"keep-me\\\"},\\n        ]\\n\\n        respx.get(\\\"http://public.example.com/start\\\").mock(\\n            return_value=Response(302, headers={\\\"Location\\\": \\\"http://other.example.com/next\\\"})\\n        )\\n        final_route = respx.get(\\\"http://other.example.com/next\\\").mock(return_value=Response(200, json={\\\"ok\\\": True}))\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n        ):\\n            result = await component.make_api_request()\\n\\n        assert isinstance(result, Data)\\n        assert final_route.called\\n        forwarded = final_route.calls.last.request.headers\\n        assert \\\"authorization\\\" not in {k.lower() for k in forwarded}, \\\"Authorization must be stripped cross-host\\\"\\n        assert forwarded.get(\\\"X-Custom\\\") == \\\"keep-me\\\", \\\"Non-sensitive headers should be preserved\\\"\\n\\n    def test_method_for_redirect_semantics(self):\\n        \\\"\\\"\\\"301/302/303 downgrade POST to GET; 307/308 preserve the method.\\\"\\\"\\\"\\n        assert APIRequestComponent._method_for_redirect(\\\"POST\\\", 301) == \\\"GET\\\"\\n        assert APIRequestComponent._method_for_redirect(\\\"POST\\\", 302) == \\\"GET\\\"\\n        assert APIRequestComponent._method_for_redirect(\\\"POST\\\", 303) == \\\"GET\\\"\\n        assert APIRequestComponent._method_for_redirect(\\\"POST\\\", 307) == \\\"POST\\\"\\n        assert APIRequestComponent._method_for_redirect(\\\"POST\\\", 308) == \\\"POST\\\"\\n        assert APIRequestComponent._method_for_redirect(\\\"GET\\\", 302) == \\\"GET\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/data_source/test_dns_rebinding.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fc4ced2a4a6ad44f446ae41b928fb6927094b52d5283d85b58b9223e8ae50801\",\"content\":\"\\\"\\\"\\\"Test DNS rebinding protection in API Request and URL components.\\n\\nThis test suite verifies that the DNS pinning implementation prevents\\nDNS rebinding attacks that could bypass SSRF protection in both the\\nAPI Request component and the URL component.\\n\\\"\\\"\\\"\\n# ruff: noqa: ARG001, SIM117\\n\\nimport os\\nimport socket\\nfrom unittest.mock import patch\\n\\nimport httpcore\\nimport httpx\\nimport pytest\\nfrom lfx.components.data_source.api_request import APIRequestComponent\\nfrom lfx.components.data_source.url import URLComponent\\nfrom lfx.schema import Data\\n\\n\\nclass TestDNSRebindingProtection:\\n    \\\"\\\"\\\"Test DNS rebinding attack prevention through DNS pinning.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component(self):\\n        \\\"\\\"\\\"Create a basic API request component.\\\"\\\"\\\"\\n        return APIRequestComponent(\\n            url_input=\\\"http://rebinding.test:8080/api\\\",\\n            method=\\\"GET\\\",\\n            headers=[],\\n            body=[],\\n            timeout=30,\\n            follow_redirects=False,\\n            save_to_file=False,\\n            include_httpx_metadata=False,\\n            mode=\\\"URL\\\",\\n            curl_input=\\\"\\\",\\n            query_params={},\\n        )\\n\\n    @pytest.mark.asyncio\\n    async def test_dns_pinning_prevents_rebinding_attack(self, component):\\n        \\\"\\\"\\\"Test that DNS pinning prevents DNS rebinding attacks.\\n\\n        This test simulates a DNS rebinding attack where:\\n        1. First DNS lookup (validation): returns public IP (8.8.8.8)\\n        2. Second DNS lookup (httpx): would return localhost (127.0.0.1)\\n\\n        With DNS pinning, the second lookup should NOT happen - the validated\\n        IP from the first lookup should be used directly at the network layer.\\n        \\\"\\\"\\\"\\n        call_count = 0\\n        connected_to_ip = None\\n\\n        def mock_getaddrinfo(_hostname, _port, *_args, **_kwargs):\\n            \\\"\\\"\\\"Mock DNS resolution to simulate rebinding attack.\\\"\\\"\\\"\\n            nonlocal call_count\\n            call_count += 1\\n\\n            if call_count == 1:\\n                # First call (during validation): return public IP\\n                return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"8.8.8.8\\\", 0))]\\n            # Second call (during httpx request): return localhost\\n            # This simulates the DNS rebinding attack\\n            # With DNS pinning, this should NOT be called\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"127.0.0.1\\\", 0))]\\n\\n        # Mock the network backend's connect_tcp to capture the actual IP being connected to\\n        async def mock_connect_tcp(self, host, port, **kwargs):\\n            \\\"\\\"\\\"Capture the IP that's actually being connected to.\\\"\\\"\\\"\\n            nonlocal connected_to_ip\\n            connected_to_ip = host\\n            # Return a mock stream with proper format (list of bytes)\\n            return httpcore.AsyncMockStream(\\n                [\\n                    b\\\"HTTP/1.1 200 OK\\\\r\\\\n\\\",\\n                    b\\\"Content-Type: application/json\\\\r\\\\n\\\",\\n                    b\\\"Content-Length: 15\\\\r\\\\n\\\",\\n                    b\\\"\\\\r\\\\n\\\",\\n                    b'{\\\"status\\\":\\\"ok\\\"}',\\n                ]\\n            )\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch.object(httpcore.AnyIOBackend, \\\"connect_tcp\\\", mock_connect_tcp),\\n        ):\\n            # Execute the request\\n            result = await component.make_api_request()\\n\\n            # Verify the request succeeded\\n            assert result is not None\\n\\n            # CRITICAL CHECK: DNS should only be called once (during validation)\\n            # If called twice, DNS pinning failed and the attack succeeded\\n            assert call_count == 1, (\\n                f\\\"DNS was called {call_count} times. Expected 1 (validation only). \\\"\\n                \\\"DNS pinning failed - the component is vulnerable to DNS rebinding!\\\"\\n            )\\n\\n            # Verify the connection was made to the pinned IP\\n            assert connected_to_ip is not None, \\\"No TCP connection was made\\\"\\n            assert connected_to_ip == \\\"8.8.8.8\\\", (\\n                f\\\"Connection should be to pinned IP 8.8.8.8, but was to {connected_to_ip}\\\"\\n            )\\n\\n    @pytest.mark.asyncio\\n    async def test_dns_pinning_preserves_hostname_in_header(self, component):\\n        \\\"\\\"\\\"Test that DNS pinning connects to pinned IP while preserving hostname for TLS.\\n\\n        With network-level DNS pinning:\\n        - TCP connection goes to the pinned IP (93.184.216.34)\\n        - URL preserves the original hostname (rebinding.test)\\n        - This allows TLS SNI and certificate verification to work correctly\\n\\n        This is important for:\\n        - Virtual hosting (multiple sites on same IP)\\n        - SNI (Server Name Indication) for HTTPS\\n        - Certificate verification (cert is for hostname, not IP)\\n        \\\"\\\"\\\"\\n        connected_to_ip = None\\n\\n        def mock_getaddrinfo(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Mock DNS resolution.\\\"\\\"\\\"\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"93.184.216.34\\\", 0))]\\n\\n        # Mock network backend to capture TCP connection\\n        async def mock_connect_tcp(self, host, port, **kwargs):\\n            \\\"\\\"\\\"Capture the IP that TCP connects to.\\\"\\\"\\\"\\n            nonlocal connected_to_ip\\n            connected_to_ip = host\\n            return httpcore.AsyncMockStream(\\n                [\\n                    b\\\"HTTP/1.1 200 OK\\\\r\\\\n\\\",\\n                    b\\\"Content-Type: application/json\\\\r\\\\n\\\",\\n                    b\\\"Content-Length: 15\\\\r\\\\n\\\",\\n                    b\\\"\\\\r\\\\n\\\",\\n                    b'{\\\"status\\\":\\\"ok\\\"}',\\n                ]\\n            )\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch.object(httpcore.AnyIOBackend, \\\"connect_tcp\\\", mock_connect_tcp),\\n        ):\\n            result = await component.make_api_request()\\n\\n            # Verify the request succeeded\\n            assert result is not None\\n\\n            # Verify TCP connection was made to the pinned IP\\n            assert connected_to_ip is not None, \\\"No TCP connection was made\\\"\\n            assert connected_to_ip == \\\"93.184.216.34\\\", (\\n                f\\\"TCP connection should be to pinned IP 93.184.216.34, but was to {connected_to_ip}\\\"\\n            )\\n\\n    @pytest.mark.asyncio\\n    async def test_dns_pinning_with_direct_ip_address(self, component):\\n        \\\"\\\"\\\"Test that direct IP addresses work correctly (no DNS pinning needed).\\\"\\\"\\\"\\n        component.url_input = \\\"http://93.184.216.34:8080/api\\\"\\n\\n        def mock_getaddrinfo(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Mock DNS resolution - should not be called for direct IPs.\\\"\\\"\\\"\\n            # For direct IPs, socket.getaddrinfo is still called but returns the same IP\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"93.184.216.34\\\", 0))]\\n\\n        mock_response = httpx.Response(200, json={\\\"status\\\": \\\"ok\\\"})\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"httpx.AsyncClient.request\\\", return_value=mock_response) as mock_request,\\n        ):\\n            result = await component.make_api_request()\\n\\n            # Verify the request succeeded\\n            assert isinstance(result, Data)\\n            assert mock_request.called\\n\\n    @pytest.mark.asyncio\\n    async def test_dns_pinning_disabled_when_protection_disabled(self, component):\\n        \\\"\\\"\\\"Test that DNS pinning is skipped when SSRF protection is disabled.\\\"\\\"\\\"\\n        call_count = 0\\n\\n        def mock_getaddrinfo(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Mock DNS resolution.\\\"\\\"\\\"\\n            nonlocal call_count\\n            call_count += 1\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"8.8.8.8\\\", 0))]\\n\\n        mock_response = httpx.Response(200, json={\\\"status\\\": \\\"ok\\\"})\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"false\\\"}),\\n            patch(\\\"httpx.AsyncClient.request\\\", return_value=mock_response) as mock_request,\\n        ):\\n            result = await component.make_api_request()\\n\\n            # Verify the request succeeded\\n            assert isinstance(result, Data)\\n            assert mock_request.called\\n\\n            # When protection is disabled, DNS pinning is not used\\n            # So DNS might be called multiple times (once by httpx)\\n            # This is expected behavior when protection is off\\n\\n    @pytest.mark.asyncio\\n    async def test_dns_pinning_blocks_private_ip_resolution(self, component):\\n        \\\"\\\"\\\"Test that DNS pinning blocks hostnames that resolve to private IPs.\\\"\\\"\\\"\\n        component.url_input = \\\"http://internal.example.com/api\\\"\\n\\n        def mock_getaddrinfo(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Mock DNS resolution to return private IP.\\\"\\\"\\\"\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"192.168.1.1\\\", 0))]\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n        ):\\n            # Should raise ValueError due to SSRF protection\\n            with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n                await component.make_api_request()\\n\\n    @pytest.mark.asyncio\\n    async def test_dns_pinning_with_ipv6(self, component):\\n        \\\"\\\"\\\"Test that DNS pinning works with IPv6 addresses.\\n\\n        With network-level DNS pinning:\\n        - TCP connection goes to the IPv6 address\\n        - URL preserves the original hostname\\n        - IPv6 addresses don't need brackets in connect_tcp (only in URLs)\\n        \\\"\\\"\\\"\\n        component.url_input = \\\"http://ipv6.example.com/api\\\"\\n        connected_to_ip = None\\n\\n        def mock_getaddrinfo(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Mock DNS resolution to return IPv6.\\\"\\\"\\\"\\n            return [(socket.AF_INET6, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"2001:4860:4860::8888\\\", 0))]\\n\\n        # Mock network backend to capture TCP connection\\n        async def mock_connect_tcp(self, host, port, **kwargs):\\n            \\\"\\\"\\\"Capture the IP that TCP connects to.\\\"\\\"\\\"\\n            nonlocal connected_to_ip\\n            connected_to_ip = host\\n            return httpcore.AsyncMockStream(\\n                [\\n                    b\\\"HTTP/1.1 200 OK\\\\r\\\\n\\\",\\n                    b\\\"Content-Type: application/json\\\\r\\\\n\\\",\\n                    b\\\"Content-Length: 15\\\\r\\\\n\\\",\\n                    b\\\"\\\\r\\\\n\\\",\\n                    b'{\\\"status\\\":\\\"ok\\\"}',\\n                ]\\n            )\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch.object(httpcore.AnyIOBackend, \\\"connect_tcp\\\", mock_connect_tcp),\\n        ):\\n            result = await component.make_api_request()\\n\\n            # Verify the request succeeded\\n            assert isinstance(result, Data)\\n\\n            # Verify TCP connection was made to the IPv6 address\\n            assert connected_to_ip is not None, \\\"No TCP connection was made\\\"\\n            assert connected_to_ip == \\\"2001:4860:4860::8888\\\", (\\n                f\\\"TCP connection should be to IPv6 2001:4860:4860::8888, but was to {connected_to_ip}\\\"\\n            )\\n\\n    @pytest.mark.asyncio\\n    async def test_dns_pinning_with_allowlisted_host(self, component):\\n        \\\"\\\"\\\"Test that allowlisted hosts bypass DNS pinning and preserve original hostname.\\\"\\\"\\\"\\n        component.url_input = \\\"http://internal.example.com:8080/api\\\"  # Use a valid hostname format\\n        captured_request = None\\n\\n        def mock_getaddrinfo(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Mock DNS resolution.\\\"\\\"\\\"\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"10.0.0.1\\\", 0))]\\n\\n        # Mock the transport's handle_async_request to capture the rewritten request\\n        async def mock_handle_async_request(_self, request):\\n            \\\"\\\"\\\"Capture the request after transport rewrite.\\\"\\\"\\\"\\n            nonlocal captured_request\\n            captured_request = request\\n            return httpx.Response(200, json={\\\"status\\\": \\\"ok\\\"}, request=request)\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(\\n                os.environ,\\n                {\\n                    \\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\",\\n                    \\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\": \\\"internal.example.com,10.0.0.1\\\",\\n                },\\n            ),\\n            # Patch get_allowed_hosts to return the allowlist directly\\n            patch(\\n                \\\"lfx.utils.ssrf_protection.get_allowed_hosts\\\",\\n                return_value=[\\\"internal.example.com\\\", \\\"10.0.0.1\\\"],\\n            ),\\n            patch.object(httpx.AsyncHTTPTransport, \\\"handle_async_request\\\", mock_handle_async_request),\\n        ):\\n            result = await component.make_api_request()\\n\\n            # Verify the request succeeded\\n            assert isinstance(result, Data)\\n            assert captured_request is not None, \\\"Transport did not capture request\\\"\\n\\n            # Verify the original hostname is preserved (no DNS pinning for allowlisted hosts)\\n            url_str = str(captured_request.url)\\n            assert \\\"internal.example.com\\\" in url_str, f\\\"Allowlisted host should preserve hostname: {url_str}\\\"\\n            assert \\\"10.0.0.1\\\" not in url_str, f\\\"Allowlisted host should not use IP: {url_str}\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_dns_pinning_with_multiple_ips_fallback(self, component):\\n        \\\"\\\"\\\"Test that DNS pinning tries multiple IPs when first one fails (dual-stack/load balancing).\\\"\\\"\\\"\\n        component.url_input = \\\"http://dual-stack.example.com/api\\\"\\n\\n        # Track which IPs were attempted\\n        attempted_ips = []\\n\\n        def mock_getaddrinfo(host, port, family=0, type_=0, proto=0, flags=0):\\n            \\\"\\\"\\\"Mock DNS resolution to return multiple IPs (IPv4 and IPv6).\\\"\\\"\\\"\\n            if host == \\\"dual-stack.example.com\\\":\\n                # Return both IPv4 and IPv6 addresses (dual-stack)\\n                return [\\n                    (socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"93.184.216.34\\\", 0)),  # IPv4\\n                    (socket.AF_INET6, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"2606:2800:220:1:248:1893:25c8:1946\\\", 0)),  # IPv6\\n                ]\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (host, 0))]\\n\\n        async def mock_connect_tcp(self, host, port, **kwargs):\\n            \\\"\\\"\\\"Mock connection that fails on first IP, succeeds on second.\\\"\\\"\\\"\\n            nonlocal attempted_ips\\n            attempted_ips.append(host)\\n\\n            # First IP fails (simulating IPv4 unreachable)\\n            if host == \\\"93.184.216.34\\\":\\n                msg = \\\"Connection refused\\\"\\n                raise OSError(msg)\\n\\n            # Second IP succeeds (IPv6 works)\\n            if host == \\\"2606:2800:220:1:248:1893:25c8:1946\\\":\\n                return httpcore.AsyncMockStream(\\n                    [\\n                        b\\\"HTTP/1.1 200 OK\\\\r\\\\n\\\",\\n                        b\\\"Content-Type: application/json\\\\r\\\\n\\\",\\n                        b\\\"Content-Length: 15\\\\r\\\\n\\\",\\n                        b\\\"\\\\r\\\\n\\\",\\n                        b'{\\\"status\\\":\\\"ok\\\"}',\\n                    ]\\n                )\\n\\n            msg = f\\\"Unexpected host: {host}\\\"\\n            raise OSError(msg)\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch.object(httpcore.AnyIOBackend, \\\"connect_tcp\\\", mock_connect_tcp),\\n        ):\\n            # Execute the request\\n            result = await component.make_api_request()\\n\\n            # Verify both IPs were attempted in order\\n            assert len(attempted_ips) == 2\\n            assert attempted_ips[0] == \\\"93.184.216.34\\\"  # IPv4 tried first\\n            assert attempted_ips[1] == \\\"2606:2800:220:1:248:1893:25c8:1946\\\"  # IPv6 tried second\\n\\n            # Verify the result (should succeed with second IP)\\n            assert isinstance(result, Data)\\n            assert result.data is not None\\n\\n    @pytest.mark.asyncio\\n    async def test_dns_pinning_applies_to_redirect_hops(self, component):\\n        \\\"\\\"\\\"Test that DNS pinning is enforced on every redirect hop, not just the first.\\n\\n        Simulates a redirect from a validated public host to a second host. With\\n        per-hop validation + pinning, both connections must go to the validated public\\n        IP - a rebinding attacker who flips the redirect target to 127.0.0.1 after\\n        validation can never cause a connection to the internal address.\\n        \\\"\\\"\\\"\\n        component.url_input = \\\"http://public.example.com/start\\\"\\n        component.follow_redirects = True\\n\\n        resolved = []\\n\\n        def mock_getaddrinfo(host, *_args, **_kwargs):\\n            \\\"\\\"\\\"Every host resolves to a public IP at validation time.\\\"\\\"\\\"\\n            resolved.append(host)\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"8.8.8.8\\\", 0))]\\n\\n        connect_calls = []\\n        redirect_response = [\\n            b\\\"HTTP/1.1 302 Found\\\\r\\\\n\\\",\\n            b\\\"Location: http://rebind.example.com/secret\\\\r\\\\n\\\",\\n            b\\\"Content-Length: 0\\\\r\\\\n\\\",\\n            b\\\"\\\\r\\\\n\\\",\\n        ]\\n        final_response = [\\n            b\\\"HTTP/1.1 200 OK\\\\r\\\\n\\\",\\n            b\\\"Content-Type: application/json\\\\r\\\\n\\\",\\n            b\\\"Content-Length: 15\\\\r\\\\n\\\",\\n            b\\\"\\\\r\\\\n\\\",\\n            b'{\\\"status\\\":\\\"ok\\\"}',\\n        ]\\n\\n        async def mock_connect_tcp(self, host, port, **kwargs):\\n            \\\"\\\"\\\"Capture every IP connected to; first hop redirects, second succeeds.\\\"\\\"\\\"\\n            connect_calls.append(host)\\n            stream = redirect_response if len(connect_calls) == 1 else final_response\\n            return httpcore.AsyncMockStream(list(stream))\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch.object(httpcore.AnyIOBackend, \\\"connect_tcp\\\", mock_connect_tcp),\\n        ):\\n            result = await component.make_api_request()\\n\\n        assert isinstance(result, Data)\\n        # Both the initial request and the redirect hop connected to the pinned public IP.\\n        assert connect_calls == [\\\"8.8.8.8\\\", \\\"8.8.8.8\\\"], connect_calls\\n        # The redirect target was resolved exactly once (validation only); httpx never\\n        # re-resolved it, so a rebinding flip after validation has no effect.\\n        assert resolved.count(\\\"rebind.example.com\\\") == 1, resolved\\n\\n\\nclass TestURLComponentDNSRebindingProtection:\\n    \\\"\\\"\\\"Test DNS rebinding attack prevention in URL component.\\n\\n    This test suite verifies that the URL component is protected against DNS rebinding\\n    attacks where an attacker controls a DNS server that returns different IPs on\\n    successive queries.\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_url_component_prevents_dns_rebinding_attack(self):\\n        \\\"\\\"\\\"Test that URL component prevents DNS rebinding attacks via DNS pinning.\\n\\n        This is a regression test for the SSRF vulnerability reported in the security disclosure.\\n        It verifies that only ONE DNS query occurs during the entire fetch operation.\\n\\n        Attack scenario:\\n        1. First DNS query: attacker.test -> 1.1.1.1 (public IP, passes validation)\\n        2. Attacker changes DNS with TTL=0\\n        3. Second DNS query: attacker.test -> 127.0.0.1 (localhost, should be blocked)\\n        4. Without DNS pinning: fetch reaches localhost (SSRF bypass)\\n        5. With DNS pinning: fetch uses pinned 1.1.1.1 (attack prevented)\\n        \\\"\\\"\\\"\\n        call_count = 0\\n        connected_to_ip = None\\n\\n        def mock_getaddrinfo(_hostname, _port, *_args, **_kwargs):\\n            \\\"\\\"\\\"Mock DNS resolution to simulate rebinding attack.\\\"\\\"\\\"\\n            nonlocal call_count\\n            call_count += 1\\n\\n            if call_count == 1:\\n                # First call (during validation): return public IP\\n                return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"1.1.1.1\\\", 0))]\\n            # Second call (during httpx request): return localhost\\n            # This simulates the DNS rebinding attack\\n            # With DNS pinning, this should NOT be called\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"127.0.0.1\\\", 0))]\\n\\n        # Mock the network backend's connect_tcp to capture the actual IP being connected to\\n        async def mock_connect_tcp(self, host, port, **kwargs):\\n            \\\"\\\"\\\"Capture the IP that's actually being connected to.\\\"\\\"\\\"\\n            nonlocal connected_to_ip\\n            connected_to_ip = host\\n            # Return a mock stream with HTML content\\n            return httpcore.AsyncMockStream(\\n                [\\n                    b\\\"HTTP/1.1 200 OK\\\\r\\\\n\\\",\\n                    b\\\"Content-Type: text/html\\\\r\\\\n\\\",\\n                    b\\\"Content-Length: 38\\\\r\\\\n\\\",\\n                    b\\\"\\\\r\\\\n\\\",\\n                    b\\\"<html><body>Test content</body></html>\\\",\\n                ]\\n            )\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch.object(httpcore.AnyIOBackend, \\\"connect_tcp\\\", mock_connect_tcp),\\n        ):\\n            # Create URL component\\n            component = URLComponent()\\n            component.urls = [\\\"http://attacker.test/\\\"]\\n            component.max_depth = 1\\n            component.format = \\\"Text\\\"\\n            component.headers = [{\\\"key\\\": \\\"User-Agent\\\", \\\"value\\\": \\\"Test\\\"}]\\n            component.timeout = 30\\n            component.prevent_outside = True\\n            component.use_async = True\\n            component.filter_text_html = False\\n            component.continue_on_failure = False\\n            component.check_response_status = False\\n            component.autoset_encoding = True\\n\\n            # Execute the component\\n            result = await component.fetch_url_contents()\\n\\n            # Verify results\\n            assert len(result) == 1\\n            assert \\\"Test content\\\" in result[0][\\\"text\\\"]\\n\\n            # CRITICAL VERIFICATION: Only ONE DNS query should have occurred\\n            assert call_count == 1, (\\n                f\\\"DNS rebinding attack NOT prevented! \\\"\\n                f\\\"Expected 1 DNS query (during validation), but {call_count} occurred. \\\"\\n                f\\\"The URL component is vulnerable to DNS rebinding attacks.\\\"\\n            )\\n\\n            # Verify the connection was made to the pinned IP\\n            assert connected_to_ip is not None, \\\"No TCP connection was made\\\"\\n            assert connected_to_ip == \\\"1.1.1.1\\\", (\\n                f\\\"Connection should be to pinned IP 1.1.1.1, but was to {connected_to_ip}. DNS pinning failed!\\\"\\n            )\\n\\n    @pytest.mark.asyncio\\n    async def test_url_component_blocks_localhost_on_first_query(self):\\n        \\\"\\\"\\\"Test that localhost is blocked even on the first DNS query.\\\"\\\"\\\"\\n\\n        def mock_getaddrinfo_localhost(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Return localhost immediately.\\\"\\\"\\\"\\n            return [\\n                (\\n                    socket.AF_INET,\\n                    socket.SOCK_STREAM,\\n                    6,\\n                    \\\"\\\",\\n                    (\\\"127.0.0.1\\\", port or 0),\\n                )\\n            ]\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo_localhost),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n        ):\\n            component = URLComponent()\\n            component.urls = [\\\"http://localhost-test.example/\\\"]\\n            component.max_depth = 1\\n            component.format = \\\"Text\\\"\\n            component.headers = []\\n            component.timeout = 30\\n\\n            # Should raise ValueError due to SSRF protection\\n            with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n                await component.fetch_url_contents()\\n\\n    @pytest.mark.asyncio\\n    async def test_url_component_blocks_aws_metadata_on_first_query(self):\\n        \\\"\\\"\\\"Test that AWS metadata endpoint is blocked even on the first DNS query.\\\"\\\"\\\"\\n\\n        def mock_getaddrinfo_metadata(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Return AWS metadata IP immediately.\\\"\\\"\\\"\\n            return [\\n                (\\n                    socket.AF_INET,\\n                    socket.SOCK_STREAM,\\n                    6,\\n                    \\\"\\\",\\n                    (\\\"169.254.169.254\\\", port or 0),\\n                )\\n            ]\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo_metadata),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n        ):\\n            component = URLComponent()\\n            component.urls = [\\\"http://metadata.example/\\\"]\\n            component.max_depth = 1\\n            component.format = \\\"Text\\\"\\n            component.headers = []\\n            component.timeout = 30\\n\\n            # Should raise ValueError due to SSRF protection\\n            with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n                await component.fetch_url_contents()\\n\\n    @pytest.mark.asyncio\\n    async def test_url_component_revalidates_discovered_links(self):\\n        \\\"\\\"\\\"Test that each discovered link during recursive crawling is re-validated.\\n\\n        This ensures that even if the initial URL is safe, any links discovered\\n        during crawling are also validated before being fetched.\\n        \\\"\\\"\\\"\\n        call_count = 0\\n        validated_hosts = []\\n\\n        def mock_getaddrinfo(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Track which hosts are validated.\\\"\\\"\\\"\\n            nonlocal call_count\\n            call_count += 1\\n            validated_hosts.append(hostname)\\n\\n            # First host (safe.com) resolves to public IP\\n            if hostname == \\\"safe.com\\\":\\n                return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"1.1.1.1\\\", 0))]\\n            # Second host (evil.com) resolves to localhost - should be blocked\\n            if hostname == \\\"evil.com\\\":\\n                return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"127.0.0.1\\\", 0))]\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"8.8.8.8\\\", 0))]\\n\\n        async def mock_connect_tcp(self, host, port, **kwargs):\\n            \\\"\\\"\\\"Return HTML with a link to evil.com.\\\"\\\"\\\"\\n            return httpcore.AsyncMockStream(\\n                [\\n                    b\\\"HTTP/1.1 200 OK\\\\r\\\\n\\\",\\n                    b\\\"Content-Type: text/html\\\\r\\\\n\\\",\\n                    b\\\"Content-Length: 61\\\\r\\\\n\\\",\\n                    b\\\"\\\\r\\\\n\\\",\\n                    b'<html><body><a href=\\\"http://evil.com/\\\">Link</a></body></html>',\\n                ]\\n            )\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch.object(httpcore.AnyIOBackend, \\\"connect_tcp\\\", mock_connect_tcp),\\n        ):\\n            component = URLComponent()\\n            component.urls = [\\\"http://safe.com/\\\"]\\n            component.max_depth = 2  # Allow following links\\n            component.format = \\\"Text\\\"\\n            component.headers = []\\n            component.timeout = 30\\n            component.prevent_outside = False  # Allow external links\\n            component.continue_on_failure = True  # Continue even if evil.com is blocked\\n\\n            # Execute - should fetch safe.com but block evil.com\\n            result = await component.fetch_url_contents()\\n\\n            # Verify safe.com was fetched\\n            assert len(result) >= 1\\n\\n            # Verify both hosts were validated\\n            assert \\\"safe.com\\\" in validated_hosts, \\\"Initial URL should be validated\\\"\\n            assert \\\"evil.com\\\" in validated_hosts, \\\"Discovered link should be validated\\\"\\n\\n            # Verify evil.com was blocked (only safe.com content returned)\\n            assert len(result) == 1, \\\"evil.com should have been blocked, only safe.com content returned\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_url_component_blocks_mixed_safe_unsafe_dns_answers(self):\\n        \\\"\\\"\\\"Test that hostnames resolving to both safe and unsafe IPs are blocked.\\n\\n        This prevents attacks where a hostname resolves to multiple IPs including\\n        both public (safe) and private/localhost (unsafe) addresses. The entire\\n        hostname must be blocked if ANY resolved IP is unsafe.\\n        \\\"\\\"\\\"\\n\\n        def mock_getaddrinfo(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Return both safe and unsafe IPs for the same hostname.\\\"\\\"\\\"\\n            return [\\n                # First IP: safe public address\\n                (socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"8.8.8.8\\\", 0)),\\n                # Second IP: unsafe localhost\\n                (socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"127.0.0.1\\\", 0)),\\n            ]\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n        ):\\n            component = URLComponent()\\n            component.urls = [\\\"http://mixed-dns.example/\\\"]\\n            component.max_depth = 1\\n            component.format = \\\"Text\\\"\\n            component.headers = []\\n            component.timeout = 30\\n\\n            # Should raise ValueError due to SSRF protection blocking the unsafe IP\\n            with pytest.raises(ValueError, match=r\\\"SSRF Protection.*127\\\\.0\\\\.0\\\\.1\\\"):\\n                await component.fetch_url_contents()\\n\\n    @pytest.mark.asyncio\\n    async def test_url_component_blocks_ipv4_mapped_ipv6_localhost(self):\\n        \\\"\\\"\\\"Test that IPv4-mapped IPv6 localhost addresses are blocked.\\n\\n        IPv4-mapped IPv6 addresses like ::ffff:127.0.0.1 are a common SSRF bypass\\n        technique. The protection must recognize and block these.\\n        \\\"\\\"\\\"\\n\\n        def mock_getaddrinfo(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Return IPv4-mapped IPv6 localhost.\\\"\\\"\\\"\\n            return [\\n                (\\n                    socket.AF_INET6,\\n                    socket.SOCK_STREAM,\\n                    6,\\n                    \\\"\\\",\\n                    (\\\"::ffff:127.0.0.1\\\", 0),\\n                )\\n            ]\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n        ):\\n            component = URLComponent()\\n            component.urls = [\\\"http://ipv4-mapped.example/\\\"]\\n            component.max_depth = 1\\n            component.format = \\\"Text\\\"\\n            component.headers = []\\n            component.timeout = 30\\n\\n            # Should raise ValueError due to SSRF protection\\n            with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n                await component.fetch_url_contents()\\n\\n    @pytest.mark.asyncio\\n    async def test_url_component_blocks_ipv4_mapped_ipv6_private_network(self):\\n        \\\"\\\"\\\"Test that IPv4-mapped IPv6 private network addresses are blocked.\\n\\n        Tests ::ffff:192.168.1.1 (IPv4-mapped private network).\\n        \\\"\\\"\\\"\\n\\n        def mock_getaddrinfo(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Return IPv4-mapped IPv6 private network address.\\\"\\\"\\\"\\n            return [\\n                (\\n                    socket.AF_INET6,\\n                    socket.SOCK_STREAM,\\n                    6,\\n                    \\\"\\\",\\n                    (\\\"::ffff:192.168.1.1\\\", 0),\\n                )\\n            ]\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n        ):\\n            component = URLComponent()\\n            component.urls = [\\\"http://ipv4-mapped-private.example/\\\"]\\n            component.max_depth = 1\\n            component.format = \\\"Text\\\"\\n            component.headers = []\\n            component.timeout = 30\\n\\n            # Should raise ValueError due to SSRF protection\\n            with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n                await component.fetch_url_contents()\\n\\n    @pytest.mark.asyncio\\n    async def test_url_component_follows_redirects_with_per_hop_pinning(self):\\n        \\\"\\\"\\\"Test that the URL component follows redirects and re-validates/pins every hop.\\n\\n        Regression test: the component previously sent every request with\\n        follow_redirects=False, so a site that 301s to its canonical URL (http->https or\\n        www normalization - extremely common) returned the redirect stub instead of the\\n        page. Redirects are now followed, and each hop is independently DNS-pinned so a\\n        rebinding attacker who flips the redirect target after validation can never cause\\n        a connection to an unvalidated address.\\n        \\\"\\\"\\\"\\n        resolved = []\\n\\n        def mock_getaddrinfo(host, *_args, **_kwargs):\\n            \\\"\\\"\\\"Every host resolves to the same public IP at validation time.\\\"\\\"\\\"\\n            resolved.append(host)\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"8.8.8.8\\\", 0))]\\n\\n        connect_hosts = []\\n        redirect_response = [\\n            b\\\"HTTP/1.1 301 Moved Permanently\\\\r\\\\n\\\",\\n            b\\\"Location: https://final.test/\\\\r\\\\n\\\",\\n            b\\\"Content-Length: 0\\\\r\\\\n\\\",\\n            b\\\"\\\\r\\\\n\\\",\\n        ]\\n        final_response = [\\n            b\\\"HTTP/1.1 200 OK\\\\r\\\\n\\\",\\n            b\\\"Content-Type: text/html\\\\r\\\\n\\\",\\n            b\\\"Content-Length: 39\\\\r\\\\n\\\",\\n            b\\\"\\\\r\\\\n\\\",\\n            b\\\"<html><body>Final content</body></html>\\\",\\n        ]\\n\\n        async def mock_connect_tcp(self, host, port, **kwargs):\\n            \\\"\\\"\\\"Capture every IP connected to; first hop redirects, second succeeds.\\\"\\\"\\\"\\n            connect_hosts.append(host)\\n            stream = redirect_response if len(connect_hosts) == 1 else final_response\\n            return httpcore.AsyncMockStream(list(stream))\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch.object(httpcore.AnyIOBackend, \\\"connect_tcp\\\", mock_connect_tcp),\\n        ):\\n            component = URLComponent()\\n            component.urls = [\\\"http://redirect.test/\\\"]\\n            component.max_depth = 1\\n            component.format = \\\"Text\\\"\\n            component.headers = [{\\\"key\\\": \\\"User-Agent\\\", \\\"value\\\": \\\"Test\\\"}]\\n            component.timeout = 30\\n            component.prevent_outside = True\\n            component.use_async = True\\n            component.follow_redirects = True\\n            component.filter_text_html = False\\n            component.continue_on_failure = False\\n            component.check_response_status = False\\n            component.autoset_encoding = True\\n\\n            result = await component.fetch_url_contents()\\n\\n        # The redirect was followed through to the final page's content.\\n        assert len(result) == 1\\n        assert \\\"Final content\\\" in result[0][\\\"text\\\"]\\n        # Both the initial request and the redirect hop connected to the pinned public IP.\\n        assert connect_hosts == [\\\"8.8.8.8\\\", \\\"8.8.8.8\\\"], connect_hosts\\n        # The redirect target was resolved exactly once (validation only); httpx never\\n        # re-resolved it, so a rebinding flip after validation has no effect.\\n        assert resolved.count(\\\"final.test\\\") == 1, resolved\\n\\n    @pytest.mark.asyncio\\n    async def test_url_component_blocks_redirect_to_internal_ip(self):\\n        \\\"\\\"\\\"Test that a redirect pointing at an internal address is blocked before connecting.\\n\\n        A validated public host redirects to a host that resolves to localhost. The hop\\n        is re-validated with the SSRF denylist, so the component raises rather than\\n        fetching the internal resource, and never opens a connection to it.\\n        \\\"\\\"\\\"\\n        resolved = []\\n\\n        def mock_getaddrinfo(host, *_args, **_kwargs):\\n            \\\"\\\"\\\"The public redirector resolves to a public IP; the target to localhost.\\\"\\\"\\\"\\n            resolved.append(host)\\n            if host == \\\"internal.test\\\":\\n                return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"127.0.0.1\\\", 0))]\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"8.8.8.8\\\", 0))]\\n\\n        connect_hosts = []\\n        redirect_response = [\\n            b\\\"HTTP/1.1 302 Found\\\\r\\\\n\\\",\\n            b\\\"Location: http://internal.test/secret\\\\r\\\\n\\\",\\n            b\\\"Content-Length: 0\\\\r\\\\n\\\",\\n            b\\\"\\\\r\\\\n\\\",\\n        ]\\n\\n        async def mock_connect_tcp(self, host, port, **kwargs):\\n            \\\"\\\"\\\"First (and only) connection returns a redirect to the internal host.\\\"\\\"\\\"\\n            connect_hosts.append(host)\\n            return httpcore.AsyncMockStream(list(redirect_response))\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch.object(httpcore.AnyIOBackend, \\\"connect_tcp\\\", mock_connect_tcp),\\n        ):\\n            component = URLComponent()\\n            component.urls = [\\\"http://safe-redirector.test/\\\"]\\n            component.max_depth = 1\\n            component.format = \\\"Text\\\"\\n            component.headers = [{\\\"key\\\": \\\"User-Agent\\\", \\\"value\\\": \\\"Test\\\"}]\\n            component.timeout = 30\\n            component.prevent_outside = True\\n            component.use_async = True\\n            component.follow_redirects = True\\n            component.filter_text_html = False\\n            component.continue_on_failure = False\\n            component.check_response_status = False\\n            component.autoset_encoding = True\\n\\n            # The redirect to a localhost-resolving host must be blocked by SSRF protection.\\n            with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n                await component.fetch_url_contents()\\n\\n        # Only the first (public) hop ever connected; the internal target was never reached.\\n        assert connect_hosts == [\\\"8.8.8.8\\\"], connect_hosts\\n        assert \\\"internal.test\\\" in resolved, resolved\\n\\n    @pytest.mark.asyncio\\n    async def test_url_component_crawls_links_from_redirected_base(self):\\n        \\\"\\\"\\\"Test that depth>1 crawls resolve links against the final post-redirect URL.\\n\\n        Regression test: after following http://redirect.test/ -> https://final.test/,\\n        relative links were still resolved against the original URL (sending /about to\\n        http://redirect.test/about) and prevent_outside compared link domains against\\n        the pre-redirect host, skipping same-site absolute links. Links must be resolved\\n        against the URL the content actually came from, and the canonical URL itself is\\n        marked visited so links back to it are not re-crawled.\\n        \\\"\\\"\\\"\\n        resolved = []\\n\\n        def mock_getaddrinfo(host, *_args, **_kwargs):\\n            \\\"\\\"\\\"Every host resolves to the same public IP at validation time.\\\"\\\"\\\"\\n            resolved.append(host)\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"8.8.8.8\\\", 0))]\\n\\n        def http_ok(body: bytes) -> list[bytes]:\\n            return [\\n                b\\\"HTTP/1.1 200 OK\\\\r\\\\n\\\",\\n                b\\\"Content-Type: text/html\\\\r\\\\n\\\",\\n                b\\\"Content-Length: \\\" + str(len(body)).encode() + b\\\"\\\\r\\\\n\\\",\\n                b\\\"\\\\r\\\\n\\\",\\n                body,\\n            ]\\n\\n        responses = [\\n            [\\n                b\\\"HTTP/1.1 301 Moved Permanently\\\\r\\\\n\\\",\\n                b\\\"Location: https://final.test/\\\\r\\\\n\\\",\\n                b\\\"Content-Length: 0\\\\r\\\\n\\\",\\n                b\\\"\\\\r\\\\n\\\",\\n            ],\\n            http_ok(\\n                b\\\"<html><body>Final page\\\"\\n                b'<a href=\\\"/about\\\">About</a>'\\n                b'<a href=\\\"https://final.test/contact\\\">Contact</a>'\\n                b'<a href=\\\"https://final.test/\\\">Home</a>'\\n                b\\\"</body></html>\\\"\\n            ),\\n            http_ok(b\\\"<html><body>About page</body></html>\\\"),\\n            http_ok(b\\\"<html><body>Contact page</body></html>\\\"),\\n        ]\\n\\n        connect_hosts = []\\n\\n        async def mock_connect_tcp(self, host, port, **kwargs):\\n            \\\"\\\"\\\"Serve the redirect, the final page, then one page per crawled link.\\\"\\\"\\\"\\n            connect_hosts.append(host)\\n            return httpcore.AsyncMockStream(list(responses[len(connect_hosts) - 1]))\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch.object(httpcore.AnyIOBackend, \\\"connect_tcp\\\", mock_connect_tcp),\\n        ):\\n            component = URLComponent()\\n            component.urls = [\\\"http://redirect.test/\\\"]\\n            component.max_depth = 2\\n            component.format = \\\"Text\\\"\\n            component.headers = [{\\\"key\\\": \\\"User-Agent\\\", \\\"value\\\": \\\"Test\\\"}]\\n            component.timeout = 30\\n            component.prevent_outside = True\\n            component.use_async = True\\n            component.follow_redirects = True\\n            component.filter_text_html = False\\n            component.continue_on_failure = False\\n            component.check_response_status = False\\n            component.autoset_encoding = True\\n\\n            result = await component.fetch_url_contents()\\n\\n        # The final page and both same-site links (relative and absolute) were crawled.\\n        assert [doc[\\\"url\\\"] for doc in result] == [\\n            \\\"https://final.test/\\\",\\n            \\\"https://final.test/about\\\",\\n            \\\"https://final.test/contact\\\",\\n        ]\\n        assert \\\"About page\\\" in result[1][\\\"text\\\"]\\n        # The back-link to the canonical URL was already visited - exactly 4 connections\\n        # (initial + redirect hop + 2 links), all to the pinned public IP.\\n        assert connect_hosts == [\\\"8.8.8.8\\\"] * 4, connect_hosts\\n        # Links validated against the post-redirect host; the pre-redirect host was only\\n        # resolved once, for the initial URL validation.\\n        assert resolved.count(\\\"redirect.test\\\") == 1, resolved\\n        assert resolved.count(\\\"final.test\\\") == 3, resolved\\n\\n\\nclass TestAPIRequestDNSRebindingEdgeCases:\\n    \\\"\\\"\\\"Additional edge case tests for API Request component DNS rebinding protection.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component(self):\\n        \\\"\\\"\\\"Create a basic API request component.\\\"\\\"\\\"\\n        return APIRequestComponent(\\n            url_input=\\\"http://test.example:8080/api\\\",\\n            method=\\\"GET\\\",\\n            headers=[],\\n            body=[],\\n            timeout=30,\\n            follow_redirects=False,\\n            save_to_file=False,\\n            include_httpx_metadata=False,\\n            mode=\\\"URL\\\",\\n            curl_input=\\\"\\\",\\n            query_params={},\\n        )\\n\\n    @pytest.mark.asyncio\\n    async def test_api_request_blocks_mixed_safe_unsafe_dns_answers(self, component):\\n        \\\"\\\"\\\"Test that hostnames resolving to both safe and unsafe IPs are blocked.\\\"\\\"\\\"\\n\\n        def mock_getaddrinfo(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Return both safe and unsafe IPs.\\\"\\\"\\\"\\n            return [\\n                (socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"8.8.8.8\\\", 0)),\\n                (socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"127.0.0.1\\\", 0)),\\n            ]\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n        ):\\n            with pytest.raises(ValueError, match=r\\\"SSRF Protection.*127\\\\.0\\\\.0\\\\.1\\\"):\\n                await component.make_api_request()\\n\\n    @pytest.mark.asyncio\\n    async def test_api_request_blocks_ipv4_mapped_ipv6_localhost(self, component):\\n        \\\"\\\"\\\"Test that IPv4-mapped IPv6 localhost is blocked.\\\"\\\"\\\"\\n\\n        def mock_getaddrinfo(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Return IPv4-mapped IPv6 localhost.\\\"\\\"\\\"\\n            return [(socket.AF_INET6, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"::ffff:127.0.0.1\\\", 0))]\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n        ):\\n            with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n                await component.make_api_request()\\n\\n    @pytest.mark.asyncio\\n    async def test_api_request_blocks_ipv4_mapped_ipv6_metadata(self, component):\\n        \\\"\\\"\\\"Test that IPv4-mapped IPv6 AWS metadata is blocked.\\\"\\\"\\\"\\n\\n        def mock_getaddrinfo(hostname, port, *args, **kwargs):\\n            \\\"\\\"\\\"Return IPv4-mapped IPv6 AWS metadata address.\\\"\\\"\\\"\\n            return [(socket.AF_INET6, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"::ffff:169.254.169.254\\\", 0))]\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n        ):\\n            with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n                await component.make_api_request()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/data_source/test_news_search.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c844005605839191ce9fc505f34515ed22d4adb1c9a8f21feb4f9ef507ba3eea\",\"content\":\"from unittest.mock import Mock, patch\\n\\nimport pytest\\nimport requests\\nfrom lfx.components.data_source.news_search import NewsSearchComponent\\nfrom lfx.schema import DataFrame\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestNewsSearchComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        return NewsSearchComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {\\\"query\\\": \\\"OpenAI\\\"}\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        return []\\n\\n    def test_successful_news_search(self):\\n        # Mock Google News RSS feed content\\n        mock_rss_content = \\\"\\\"\\\"\\n        <?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>\\n        <rss version=\\\"2.0\\\">\\n            <channel>\\n                <item>\\n                    <title>Test News 1</title>\\n                    <link>https://example.com/1</link>\\n                    <pubDate>2024-03-20</pubDate>\\n                    <description>Summary 1</description>\\n                </item>\\n                <item>\\n                    <title>Test News 2</title>\\n                    <link>https://example.com/2</link>\\n                    <pubDate>2024-03-21</pubDate>\\n                    <description>Summary 2</description>\\n                </item>\\n            </channel>\\n        </rss>\\n        \\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.content = mock_rss_content.encode(\\\"utf-8\\\")\\n        mock_response.raise_for_status = Mock()\\n\\n        with patch(\\\"requests.get\\\", return_value=mock_response):\\n            component = NewsSearchComponent(query=\\\"OpenAI\\\")\\n            result = component.search_news()\\n            assert isinstance(result, DataFrame)\\n            news_results_df = result\\n            assert len(news_results_df) == 2\\n            assert list(news_results_df.columns) == [\\\"title\\\", \\\"link\\\", \\\"published\\\", \\\"summary\\\"]\\n            assert news_results_df.iloc[0][\\\"title\\\"] == \\\"Test News 1\\\"\\n            assert news_results_df.iloc[1][\\\"title\\\"] == \\\"Test News 2\\\"\\n\\n    def test_news_search_error(self):\\n        with patch(\\\"requests.get\\\", side_effect=requests.RequestException(\\\"Network error\\\")):\\n            component = NewsSearchComponent(query=\\\"OpenAI\\\")\\n            result = component.search_news()\\n            assert isinstance(result, DataFrame)\\n            news_results_df = result\\n            assert len(news_results_df) == 1\\n            assert news_results_df.iloc[0][\\\"title\\\"] == \\\"Error\\\"\\n            assert \\\"Network error\\\" in news_results_df.iloc[0][\\\"summary\\\"]\\n\\n    def test_empty_news_results(self):\\n        # Mock empty RSS feed\\n        mock_rss_content = \\\"\\\"\\\"\\n        <?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>\\n        <rss version=\\\"2.0\\\">\\n            <channel>\\n            </channel>\\n        </rss>\\n        \\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.content = mock_rss_content.encode(\\\"utf-8\\\")\\n        mock_response.raise_for_status = Mock()\\n\\n        with patch(\\\"requests.get\\\", return_value=mock_response):\\n            component = NewsSearchComponent(query=\\\"OpenAI\\\")\\n            result = component.search_news()\\n            assert isinstance(result, DataFrame)\\n            news_results_df = result\\n            assert len(news_results_df) == 1\\n            assert news_results_df.iloc[0][\\\"title\\\"] == \\\"No articles found\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/data_source/test_rss.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d6585550aa7b7875ab288fe2ba6f9a9b26ab4a208ff0998b84cb488c763ea290\",\"content\":\"import ipaddress\\nimport os\\nimport socket\\nfrom unittest.mock import Mock, patch\\n\\nimport pytest\\nimport requests\\nfrom lfx.components.data_source.rss import RSSReaderComponent\\nfrom lfx.schema import DataFrame\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\ndef _resolve_public(host, *_args, **_kwargs):\\n    \\\"\\\"\\\"socket.getaddrinfo stub: hostnames resolve to a public IP, literal IPs to themselves.\\\"\\\"\\\"\\n    try:\\n        ipaddress.ip_address(host)\\n    except ValueError:\\n        ip = \\\"93.184.216.34\\\"  # hostname -> public IP\\n    else:\\n        ip = host  # literal IP -> itself\\n    family = socket.AF_INET6 if \\\":\\\" in ip else socket.AF_INET\\n    return [(family, socket.SOCK_STREAM, 6, \\\"\\\", (ip, 0))]\\n\\n\\n_VALID_RSS = (\\n    b'<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>'\\n    b'<rss version=\\\"2.0\\\"><channel>'\\n    b\\\"<item><title>A</title><link>https://example.com/a</link>\\\"\\n    b\\\"<pubDate>2024-03-20</pubDate><description>summary</description></item>\\\"\\n    b\\\"</channel></rss>\\\"\\n)\\n\\n\\ndef _mock_response(status_code=200, *, location=None, content=b\\\"\\\"):\\n    \\\"\\\"\\\"Build a minimal mock ``requests.Response``.\\\"\\\"\\\"\\n    response = Mock()\\n    response.status_code = status_code\\n    response.headers = {\\\"Location\\\": location} if location else {}\\n    response.content = content\\n    response.raise_for_status = Mock()\\n    return response\\n\\n\\nclass TestRSSReaderComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture(autouse=True)\\n    def _disable_ssrf_for_parsing_tests(self):\\n        \\\"\\\"\\\"Isolate the parsing-focused tests from SSRF validation and DNS resolution.\\n\\n        SSRF behavior is covered separately in ``TestRSSReaderSSRFProtection``.\\n        \\\"\\\"\\\"\\n        with patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"false\\\"}):\\n            yield\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return RSSReaderComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"rss_url\\\": \\\"https://example.com/feed.xml\\\",\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    def test_successful_rss_fetch(self):\\n        # Mock RSS feed content\\n        mock_rss_content = \\\"\\\"\\\"\\n        <?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>\\n        <rss version=\\\"2.0\\\">\\n            <channel>\\n                <item>\\n                    <title>Test Article 1</title>\\n                    <link>https://example.com/1</link>\\n                    <pubDate>2024-03-20</pubDate>\\n                    <description>Test summary 1</description>\\n                </item>\\n                <item>\\n                    <title>Test Article 2</title>\\n                    <link>https://example.com/2</link>\\n                    <pubDate>2024-03-21</pubDate>\\n                    <description>Test summary 2</description>\\n                </item>\\n            </channel>\\n        </rss>\\n        \\\"\\\"\\\"\\n\\n        # Mock the requests.get response\\n        mock_response = Mock()\\n        mock_response.content = mock_rss_content.encode(\\\"utf-8\\\")\\n        mock_response.raise_for_status = Mock()\\n\\n        with patch(\\\"requests.get\\\", return_value=mock_response):\\n            component = RSSReaderComponent(rss_url=\\\"https://example.com/feed.xml\\\")\\n            result = component.read_rss()\\n\\n            assert isinstance(result, DataFrame)\\n            assert len(result) == 2\\n            assert list(result.columns) == [\\\"title\\\", \\\"link\\\", \\\"published\\\", \\\"summary\\\"]\\n            assert result.iloc[0][\\\"title\\\"] == \\\"Test Article 1\\\"\\n            assert result.iloc[1][\\\"title\\\"] == \\\"Test Article 2\\\"\\n\\n    def test_rss_fetch_with_missing_fields(self):\\n        # Mock RSS feed content with missing fields\\n        mock_rss_content = \\\"\\\"\\\"\\n        <?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>\\n        <rss version=\\\"2.0\\\">\\n            <channel>\\n                <item>\\n                    <title>Test Article</title>\\n                    <!-- Missing link -->\\n                    <pubDate>2024-03-20</pubDate>\\n                    <!-- Missing description -->\\n                </item>\\n            </channel>\\n        </rss>\\n        \\\"\\\"\\\"\\n\\n        mock_response = Mock()\\n        mock_response.content = mock_rss_content.encode(\\\"utf-8\\\")\\n        mock_response.raise_for_status = Mock()\\n\\n        with patch(\\\"requests.get\\\", return_value=mock_response):\\n            component = RSSReaderComponent(rss_url=\\\"https://example.com/feed.xml\\\")\\n            result = component.read_rss()\\n\\n            assert isinstance(result, DataFrame)\\n            assert len(result) == 1\\n            assert result.iloc[0][\\\"title\\\"] == \\\"Test Article\\\"\\n            assert result.iloc[0][\\\"link\\\"] == \\\"\\\"\\n            assert result.iloc[0][\\\"summary\\\"] == \\\"\\\"\\n\\n    def test_rss_fetch_error(self):\\n        # Mock a failed request\\n        with patch(\\\"requests.get\\\", side_effect=requests.RequestException(\\\"Network error\\\")):\\n            component = RSSReaderComponent(rss_url=\\\"https://example.com/feed.xml\\\")\\n            result = component.read_rss()\\n\\n            assert isinstance(result, DataFrame)\\n            assert len(result) == 1\\n            assert result.iloc[0][\\\"title\\\"] == \\\"Error\\\"\\n            assert result.iloc[0][\\\"link\\\"] == \\\"\\\"\\n            assert result.iloc[0][\\\"published\\\"] == \\\"\\\"\\n            assert \\\"Network error\\\" in result.iloc[0][\\\"summary\\\"]\\n\\n    def test_empty_rss_feed(self):\\n        # Mock empty RSS feed\\n        mock_rss_content = \\\"\\\"\\\"\\n        <?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>\\n        <rss version=\\\"2.0\\\">\\n            <channel>\\n            </channel>\\n        </rss>\\n        \\\"\\\"\\\"\\n\\n        mock_response = Mock()\\n        mock_response.content = mock_rss_content.encode(\\\"utf-8\\\")\\n        mock_response.raise_for_status = Mock()\\n\\n        with patch(\\\"requests.get\\\", return_value=mock_response):\\n            component = RSSReaderComponent(rss_url=\\\"https://example.com/feed.xml\\\")\\n            result = component.read_rss()\\n\\n            assert isinstance(result, DataFrame)\\n            assert len(result) == 0\\n            assert list(result.columns) == [\\\"title\\\", \\\"link\\\", \\\"published\\\", \\\"summary\\\"]\\n\\n\\nclass TestRSSReaderSSRFProtection:\\n    \\\"\\\"\\\"Regression tests for the SSRF bypass via the legacy RSS Reader component.\\n\\n    With SSRF protection enabled, the user-supplied feed URL (and any redirect it\\n    follows) must not be able to reach internal services such as the cloud metadata\\n    endpoint, loopback, or private networks.\\n    \\\"\\\"\\\"\\n\\n    def test_blocks_cloud_metadata_endpoint(self):\\n        \\\"\\\"\\\"The cloud metadata endpoint is blocked; no request is made.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"requests.get\\\") as mock_get,\\n        ):\\n            component = RSSReaderComponent(rss_url=\\\"http://169.254.169.254/latest/meta-data/iam/security-credentials/\\\")\\n            result = component.read_rss()\\n\\n        assert isinstance(result, DataFrame)\\n        assert result.iloc[0][\\\"title\\\"] == \\\"Error\\\"\\n        assert \\\"blocked\\\" in result.iloc[0][\\\"summary\\\"].lower() or \\\"ssrf\\\" in result.iloc[0][\\\"summary\\\"].lower()\\n        mock_get.assert_not_called()\\n\\n    def test_blocks_localhost(self):\\n        \\\"\\\"\\\"A loopback feed URL is blocked; no request is made.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"requests.get\\\") as mock_get,\\n        ):\\n            component = RSSReaderComponent(rss_url=\\\"http://127.0.0.1:8080/feed.xml\\\")\\n            result = component.read_rss()\\n\\n        assert result.iloc[0][\\\"title\\\"] == \\\"Error\\\"\\n        mock_get.assert_not_called()\\n\\n    def test_blocks_private_network(self):\\n        \\\"\\\"\\\"An RFC1918 feed URL is blocked; no request is made.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"requests.get\\\") as mock_get,\\n        ):\\n            component = RSSReaderComponent(rss_url=\\\"http://192.168.1.1/feed.xml\\\")\\n            result = component.read_rss()\\n\\n        assert result.iloc[0][\\\"title\\\"] == \\\"Error\\\"\\n        mock_get.assert_not_called()\\n\\n    def test_blocks_redirect_to_metadata(self):\\n        \\\"\\\"\\\"A public feed that redirects to the metadata endpoint is blocked at the redirect hop.\\\"\\\"\\\"\\n        redirect = _mock_response(302, location=\\\"http://169.254.169.254/latest/meta-data/\\\")\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch(\\\"requests.get\\\", return_value=redirect) as mock_get,\\n        ):\\n            component = RSSReaderComponent(rss_url=\\\"http://public-feed.example.com/rss\\\")\\n            result = component.read_rss()\\n\\n        assert result.iloc[0][\\\"title\\\"] == \\\"Error\\\"\\n        # Only the first (public) hop was requested; the internal redirect was not followed.\\n        assert mock_get.call_count == 1\\n\\n    def test_allows_public_feed(self):\\n        \\\"\\\"\\\"A legitimate public RSS feed is fetched and parsed with SSRF protection enabled.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch(\\\"requests.get\\\", return_value=_mock_response(200, content=_VALID_RSS)),\\n        ):\\n            component = RSSReaderComponent(rss_url=\\\"http://feed.example.com/rss\\\")\\n            result = component.read_rss()\\n\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 1\\n        assert result.iloc[0][\\\"title\\\"] == \\\"A\\\"\\n\\n    def test_protection_disabled_allows_internal(self):\\n        \\\"\\\"\\\"With SSRF protection disabled, internal URLs are reachable (user opted out).\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"false\\\"}),\\n            patch(\\\"requests.get\\\", return_value=_mock_response(200, content=_VALID_RSS)) as mock_get,\\n        ):\\n            component = RSSReaderComponent(rss_url=\\\"http://127.0.0.1:8080/feed.xml\\\")\\n            result = component.read_rss()\\n\\n        assert len(result) == 1\\n        assert result.iloc[0][\\\"title\\\"] == \\\"A\\\"\\n        mock_get.assert_called_once()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/data_source/test_s3_components.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"09c07bf90beb62d0c2f04f081a67ec2a3032b9108fcaa1374a2441ffad374423\",\"content\":\"\\\"\\\"\\\"S3-specific test class for components that work with S3 storage.\\n\\nThis test class focuses on components that are compatible with S3 storage.\\n\\\"\\\"\\\"\\n\\nfrom contextlib import contextmanager\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom lfx.components.files_and_knowledge.file import FileComponent\\nfrom lfx.components.files_and_knowledge.save_file import SaveToFileComponent\\nfrom lfx.components.langchain_utilities.csv_agent import CSVAgentComponent\\nfrom lfx.components.langchain_utilities.json_agent import JsonAgentComponent\\n\\n\\n@contextmanager\\ndef mock_s3_environment(settings, storage_service):\\n    \\\"\\\"\\\"Context manager to mock S3 storage environment.\\n\\n    This patches all the necessary get_settings_service and get_storage_service\\n    calls across the codebase to enable S3 testing.\\n    \\\"\\\"\\\"\\n    patches = [\\n        patch(\\\"lfx.services.deps.get_settings_service\\\", return_value=settings),\\n        patch(\\\"lfx.base.data.base_file.get_settings_service\\\", return_value=settings),\\n        patch(\\\"lfx.base.data.storage_utils.get_settings_service\\\", return_value=settings),\\n        patch(\\\"lfx.base.data.storage_utils.get_storage_service\\\", return_value=storage_service),\\n        patch(\\\"lfx.base.data.utils.get_settings_service\\\", return_value=settings),\\n        patch(\\\"lfx.components.files_and_knowledge.file.get_settings_service\\\", return_value=settings),\\n        patch(\\\"lfx.components.files_and_knowledge.file.get_storage_service\\\", return_value=storage_service),\\n        patch(\\\"lfx.components.langchain_utilities.csv_agent.get_settings_service\\\", return_value=settings),\\n        patch(\\\"lfx.components.langchain_utilities.json_agent.get_settings_service\\\", return_value=settings),\\n    ]\\n\\n    # Start all patches\\n    [p.start() for p in patches]\\n    try:\\n        yield\\n    finally:\\n        # Stop all patches\\n        for p in patches:\\n            p.stop()\\n\\n\\nclass TestS3CompatibleComponents:\\n    \\\"\\\"\\\"Test components that work with S3 storage.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def s3_settings(self):\\n        \\\"\\\"\\\"Mock S3 settings.\\\"\\\"\\\"\\n        settings = MagicMock()\\n        settings.settings.storage_type = \\\"s3\\\"\\n        return settings\\n\\n    @pytest.fixture\\n    def local_settings(self):\\n        \\\"\\\"\\\"Mock local settings.\\\"\\\"\\\"\\n        settings = MagicMock()\\n        settings.settings.storage_type = \\\"local\\\"\\n        return settings\\n\\n    @pytest.fixture\\n    def mock_storage_service(self):\\n        \\\"\\\"\\\"Mock storage service for S3 operations.\\\"\\\"\\\"\\n        return AsyncMock()\\n\\n    def test_file_component_s3_path_handling(self, s3_settings, mock_storage_service):\\n        \\\"\\\"\\\"Test FileComponent with S3 paths.\\\"\\\"\\\"\\n        s3_path = \\\"user_123/document.txt\\\"\\n        mock_storage_service.get_file.return_value = b\\\"file content\\\"\\n\\n        with mock_s3_environment(s3_settings, mock_storage_service):\\n            component = FileComponent()\\n            component.path = s3_path  # Use 'path' property, not 'file_path'\\n\\n            result = component.load_files()\\n\\n            # Should process S3 file successfully\\n            assert result is not None\\n            assert len(result) > 0\\n            mock_storage_service.get_file.assert_called_with(\\\"user_123\\\", \\\"document.txt\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_file_component_get_local_file_for_docling_s3(self, s3_settings, mock_storage_service):\\n        \\\"\\\"\\\"Test FileComponent._get_local_file_for_docling with S3 paths uses parse_storage_path and Path.\\\"\\\"\\\"\\n        component = FileComponent()\\n        s3_path = \\\"user_123/document.pdf\\\"\\n\\n        # Configure mock storage service\\n        mock_storage_service.get_file = AsyncMock(return_value=b\\\"pdf content\\\")\\n\\n        # Mock tempfile\\n        mock_temp_file = MagicMock()\\n        mock_temp_file.name = \\\"/tmp/temp_file.pdf\\\"  # noqa: S108\\n        mock_temp_file.write = MagicMock()\\n\\n        with (\\n            mock_s3_environment(s3_settings, mock_storage_service),\\n            patch(\\n                \\\"lfx.components.files_and_knowledge.file.parse_storage_path\\\", return_value=(\\\"user_123\\\", \\\"document.pdf\\\")\\n            ) as mock_parse,\\n            patch(\\\"lfx.components.files_and_knowledge.file.NamedTemporaryFile\\\") as mock_temp,\\n        ):\\n            mock_temp.return_value.__enter__.return_value = mock_temp_file\\n\\n            local_path, should_delete = await component._get_local_file_for_docling(s3_path)\\n\\n            # Verify parse_storage_path was called with S3 path (imported at module level)\\n            mock_parse.assert_called_once_with(s3_path)\\n            # Verify storage service was called\\n            mock_storage_service.get_file.assert_called_once_with(\\\"user_123\\\", \\\"document.pdf\\\")\\n            # Verify temp file was created\\n            assert should_delete is True\\n            assert local_path == \\\"/tmp/temp_file.pdf\\\"  # noqa: S108\\n\\n    @pytest.mark.asyncio\\n    async def test_file_component_get_local_file_for_docling_local(self, local_settings):\\n        \\\"\\\"\\\"Test FileComponent._get_local_file_for_docling with local paths.\\\"\\\"\\\"\\n        with patch(\\\"lfx.services.deps.get_settings_service\\\", return_value=local_settings):\\n            component = FileComponent()\\n            local_path = \\\"/local/path/document.pdf\\\"\\n\\n            result_path, should_delete = await component._get_local_file_for_docling(local_path)\\n\\n            # Should return local path as-is, no deletion needed\\n            assert result_path == local_path\\n            assert should_delete is False\\n\\n    @pytest.mark.asyncio\\n    async def test_save_file_component_s3_upload(self, s3_settings):\\n        \\\"\\\"\\\"Test SaveToFileComponent with S3 storage.\\\"\\\"\\\"\\n        # Mock boto3 S3 client\\n        mock_s3_client = MagicMock()\\n        mock_s3_client.put_object.return_value = {\\\"ResponseMetadata\\\": {\\\"HTTPStatusCode\\\": 200}}\\n\\n        with (\\n            patch(\\\"lfx.services.deps.get_settings_service\\\", return_value=s3_settings),\\n            patch(\\\"boto3.client\\\", return_value=mock_s3_client),\\n        ):\\n            component = SaveToFileComponent()\\n\\n            # Mock database and storage services\\n            with (\\n                patch(\\\"lfx.services.deps.session_scope\\\"),\\n                patch(\\n                    \\\"langflow.services.database.models.user.crud.get_user_by_id\\\", new_callable=AsyncMock\\n                ) as mock_get_user,\\n                patch(\\\"langflow.api.v2.files.upload_user_file\\\", new_callable=AsyncMock) as mock_upload,\\n            ):\\n                mock_get_user.return_value = MagicMock()\\n                mock_upload.return_value = \\\"s3_file.txt\\\"\\n\\n                # Test with DataFrame\\n                from langflow.schema import Data, DataFrame\\n\\n                test_data = DataFrame(data=[Data(data={\\\"text\\\": \\\"test content\\\"})])\\n                component.input = test_data  # Use 'input' not 'data'\\n                component.file_name = \\\"test_output.csv\\\"\\n                component.storage_location = [{\\\"name\\\": \\\"AWS\\\"}]  # Set S3 storage location\\n                # Set required AWS credentials (will be mocked out anyway)\\n                component.aws_access_key_id = \\\"test_key\\\"\\n                component.aws_secret_access_key = \\\"test_secret\\\"  # noqa: S105  # pragma: allowlist secret\\n                component.aws_region = \\\"us-east-1\\\"\\n                component.bucket_name = \\\"test-bucket\\\"\\n\\n                result = await component.save_to_file()\\n\\n                # Should upload to S3 successfully\\n                assert \\\"successfully uploaded\\\" in result.text\\n                assert \\\"s3://\\\" in result.text\\n                assert \\\"test-bucket\\\" in result.text\\n\\n    @pytest.mark.asyncio\\n    async def test_csv_agent_s3_file_handling(self, s3_settings):\\n        \\\"\\\"\\\"Test CSVAgentComponent with S3 files.\\\"\\\"\\\"\\n        with patch(\\\"lfx.services.deps.get_settings_service\\\", return_value=s3_settings):\\n            component = CSVAgentComponent()\\n            component.set_attributes({\\\"llm\\\": MagicMock(), \\\"path\\\": \\\"user_123/data.csv\\\", \\\"verbose\\\": False})\\n\\n            # Mock storage utils\\n            with patch(\\n                \\\"lfx.base.data.storage_utils.read_file_bytes\\\", new_callable=AsyncMock, return_value=b\\\"name,age\\\\nJohn,30\\\"\\n            ):\\n                local_path = component._get_local_path()\\n\\n                # Should handle S3 path correctly\\n                assert local_path is not None\\n\\n    @pytest.mark.asyncio\\n    async def test_json_agent_s3_file_handling(self, s3_settings):\\n        \\\"\\\"\\\"Test JsonAgentComponent with S3 files.\\\"\\\"\\\"\\n        with patch(\\\"lfx.services.deps.get_settings_service\\\", return_value=s3_settings):\\n            component = JsonAgentComponent()\\n            component.set_attributes({\\\"llm\\\": MagicMock(), \\\"path\\\": \\\"user_123/data.json\\\", \\\"verbose\\\": False})\\n\\n            # Mock storage utils\\n            with patch(\\n                \\\"lfx.base.data.storage_utils.read_file_bytes\\\", new_callable=AsyncMock, return_value=b'{\\\"key\\\": \\\"value\\\"}'\\n            ):\\n                local_path = component._get_local_path()\\n\\n                # Should handle S3 path correctly\\n                assert local_path is not None\\n\\n    @pytest.mark.asyncio\\n    async def test_components_work_in_local_mode(self, local_settings):\\n        \\\"\\\"\\\"Test that components work in local mode.\\\"\\\"\\\"\\n        with patch(\\\"langflow.services.deps.get_settings_service\\\", return_value=local_settings):\\n            component = FileComponent()\\n            component.file_path = \\\"/local/path/file.txt\\\"\\n\\n            # Should work with local paths\\n            assert component.file_path == \\\"/local/path/file.txt\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_s3_path_parsing(self, s3_settings):\\n        \\\"\\\"\\\"Test S3 path parsing in components.\\\"\\\"\\\"\\n        with patch(\\\"lfx.services.deps.get_settings_service\\\", return_value=s3_settings):\\n            # Test various S3 path formats\\n            test_paths = [\\\"user_123/file.txt\\\", \\\"flow_456/document.pdf\\\", \\\"user_789/folder/subfolder/file.json\\\"]\\n\\n            for path in test_paths:\\n                component = FileComponent()\\n                component.file_path = path\\n\\n                # Should accept S3 paths\\n                assert component.file_path == path\\n\\n    def test_s3_file_download_and_processing(self, s3_settings, mock_storage_service):\\n        \\\"\\\"\\\"Test downloading and processing S3 files.\\\"\\\"\\\"\\n        mock_storage_service.get_file.return_value = b\\\"csv,content\\\\n1,2\\\"\\n\\n        with mock_s3_environment(s3_settings, mock_storage_service):\\n            component = FileComponent()\\n            component.path = \\\"user_123/large_file.csv\\\"\\n\\n            result = component.load_files()\\n\\n            # Should process downloaded content\\n            assert result is not None\\n            mock_storage_service.get_file.assert_called_with(\\\"user_123\\\", \\\"large_file.csv\\\")\\n\\n    def test_s3_error_handling(self, s3_settings, mock_storage_service):\\n        \\\"\\\"\\\"Test error handling with S3 operations.\\\"\\\"\\\"\\n        mock_storage_service.get_file.side_effect = FileNotFoundError(\\\"File not found\\\")\\n\\n        with mock_s3_environment(s3_settings, mock_storage_service):\\n            component = FileComponent()\\n            component.path = \\\"user_123/nonexistent.txt\\\"\\n            component.silent_errors = False\\n\\n            # Should raise ValueError (wraps FileNotFoundError)\\n            with pytest.raises(ValueError, match=\\\"Error loading file\\\"):\\n                component.load_files()\\n\\n    def test_s3_streaming_operations(self, s3_settings, mock_storage_service):\\n        \\\"\\\"\\\"Test streaming operations with S3.\\\"\\\"\\\"\\n        mock_storage_service.get_file.return_value = b\\\"chunk1chunk2chunk3\\\"\\n\\n        with mock_s3_environment(s3_settings, mock_storage_service):\\n            component = FileComponent()\\n            component.path = \\\"user_123/large_file.txt\\\"\\n\\n            result = component.load_files()\\n\\n            # Should handle streaming content\\n            assert result is not None\\n            mock_storage_service.get_file.assert_called_with(\\\"user_123\\\", \\\"large_file.txt\\\")\\n\\n    def test_s3_metadata_handling(self, s3_settings, mock_storage_service):\\n        \\\"\\\"\\\"Test metadata handling with S3 files.\\\"\\\"\\\"\\n        file_content = b'{\\\"name\\\": \\\"test\\\", \\\"size\\\": 1024, \\\"type\\\": \\\"application/json\\\"}'\\n        mock_storage_service.get_file.return_value = file_content\\n\\n        with mock_s3_environment(s3_settings, mock_storage_service):\\n            component = FileComponent()\\n            component.path = \\\"user_123/metadata_file.json\\\"\\n\\n            result = component.load_files()\\n\\n            # Should preserve metadata\\n            assert result is not None\\n            mock_storage_service.get_file.assert_called_with(\\\"user_123\\\", \\\"metadata_file.json\\\")\\n\\n    def test_s3_concurrent_operations(self, s3_settings, mock_storage_service):\\n        \\\"\\\"\\\"Test concurrent S3 operations.\\\"\\\"\\\"\\n        mock_storage_service.get_file.return_value = b\\\"content\\\"\\n\\n        with mock_s3_environment(s3_settings, mock_storage_service):\\n            # Process multiple files\\n            results = []\\n            for file_path in [\\\"user_123/file1.txt\\\", \\\"user_123/file2.txt\\\", \\\"user_123/file3.txt\\\"]:\\n                component = FileComponent()\\n                component.path = file_path\\n                result = component.load_files()\\n                results.append(result)\\n\\n            # All should succeed\\n            assert len(results) == 3\\n            assert all(result is not None for result in results)\\n            # Verify all files were requested\\n            assert mock_storage_service.get_file.call_count == 3\\n\\n    @pytest.mark.asyncio\\n    async def test_csv_to_data_fileinput_local_only(self, s3_settings, local_settings):\\n        \\\"\\\"\\\"Test CSVToDataComponent with FileInput - always treats as local.\\\"\\\"\\\"\\n        from lfx.components.data_source.csv_to_data import CSVToDataComponent\\n\\n        # Test with S3 storage - FileInput should still be treated as local\\n        with patch(\\\"lfx.services.deps.get_settings_service\\\", return_value=s3_settings):\\n            component = CSVToDataComponent()\\n            component.csv_file = \\\"/local/path/data.csv\\\"\\n\\n            # Mock local file read\\n            with (\\n                patch(\\\"pathlib.Path.read_bytes\\\", return_value=b\\\"name,age\\\\nJohn,30\\\"),\\n                patch(\\\"pathlib.Path.exists\\\", return_value=True),\\n            ):\\n                result = component.load_csv_to_data()\\n\\n                # Should read from local filesystem, not S3\\n                assert len(result) == 1\\n                assert result[0].data == {\\\"name\\\": \\\"John\\\", \\\"age\\\": \\\"30\\\"}\\n\\n        # Test with local storage\\n        with patch(\\\"lfx.services.deps.get_settings_service\\\", return_value=local_settings):\\n            component = CSVToDataComponent()\\n            component.csv_file = \\\"/local/path/data.csv\\\"\\n\\n            with (\\n                patch(\\\"pathlib.Path.read_bytes\\\", return_value=b\\\"name,age\\\\nJane,25\\\"),\\n                patch(\\\"pathlib.Path.exists\\\", return_value=True),\\n            ):\\n                result = component.load_csv_to_data()\\n\\n                assert len(result) == 1\\n                assert result[0].data == {\\\"name\\\": \\\"Jane\\\", \\\"age\\\": \\\"25\\\"}\\n\\n    @pytest.mark.asyncio\\n    async def test_csv_to_data_path_s3_key(self, s3_settings, mock_storage_service):\\n        \\\"\\\"\\\"Test CSVToDataComponent with text path input - handles S3 keys.\\\"\\\"\\\"\\n        from lfx.components.data_source.csv_to_data import CSVToDataComponent\\n\\n        mock_storage_service.get_file.return_value = b\\\"name,age\\\\nBob,35\\\"\\n\\n        with mock_s3_environment(s3_settings, mock_storage_service):\\n            component = CSVToDataComponent()\\n            component.csv_path = \\\"user_123/data.csv\\\"  # S3 key format\\n\\n            result = component.load_csv_to_data()\\n\\n            # Should read from S3\\n            assert len(result) == 1\\n            assert result[0].data == {\\\"name\\\": \\\"Bob\\\", \\\"age\\\": \\\"35\\\"}\\n            mock_storage_service.get_file.assert_called_once_with(\\\"user_123\\\", \\\"data.csv\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_csv_to_data_path_local(self, local_settings):\\n        \\\"\\\"\\\"Test CSVToDataComponent with text path input - handles local paths.\\\"\\\"\\\"\\n        from lfx.components.data_source.csv_to_data import CSVToDataComponent\\n\\n        with (\\n            patch(\\\"lfx.services.deps.get_settings_service\\\", return_value=local_settings),\\n            patch(\\\"lfx.base.data.storage_utils.get_settings_service\\\", return_value=local_settings),\\n            patch(\\\"lfx.base.data.storage_utils.read_file_text\\\", new_callable=AsyncMock) as mock_read_file,\\n            patch(\\n                \\\"lfx.components.data_source.csv_to_data.read_file_text\\\", new_callable=AsyncMock\\n            ) as mock_read_file_component,\\n        ):\\n            mock_read_file.return_value = \\\"name,age\\\\nAlice,28\\\"\\n            mock_read_file_component.return_value = \\\"name,age\\\\nAlice,28\\\"\\n            component = CSVToDataComponent()\\n            component.csv_path = \\\"/local/path/data.csv\\\"\\n\\n            result = component.load_csv_to_data()\\n\\n            # Should read from local filesystem\\n            assert len(result) == 1\\n            assert result[0].data == {\\\"name\\\": \\\"Alice\\\", \\\"age\\\": \\\"28\\\"}\\n\\n    @pytest.mark.asyncio\\n    async def test_json_to_data_fileinput_local_only(self, s3_settings, local_settings):\\n        \\\"\\\"\\\"Test JSONToDataComponent with FileInput - always treats as local.\\\"\\\"\\\"\\n        from lfx.components.data_source.json_to_data import JSONToDataComponent\\n\\n        # Test with S3 storage - FileInput should still be treated as local\\n        with patch(\\\"lfx.services.deps.get_settings_service\\\", return_value=s3_settings):\\n            component = JSONToDataComponent()\\n            component.json_file = \\\"/local/path/data.json\\\"\\n\\n            # Mock local file read\\n            with (\\n                patch(\\\"pathlib.Path.read_text\\\", return_value='{\\\"key\\\": \\\"value\\\"}'),\\n                patch(\\\"pathlib.Path.exists\\\", return_value=True),\\n            ):\\n                result = component.convert_json_to_data()\\n\\n                # Should read from local filesystem, not S3\\n                from lfx.schema.data import Data\\n\\n                assert isinstance(result, Data)\\n                assert result.data == {\\\"key\\\": \\\"value\\\"}\\n\\n        # Test with local storage\\n        with patch(\\\"lfx.services.deps.get_settings_service\\\", return_value=local_settings):\\n            component = JSONToDataComponent()\\n            component.json_file = \\\"/local/path/data.json\\\"\\n\\n            with (\\n                patch(\\\"pathlib.Path.read_text\\\", return_value='{\\\"name\\\": \\\"test\\\"}'),\\n                patch(\\\"pathlib.Path.exists\\\", return_value=True),\\n            ):\\n                result = component.convert_json_to_data()\\n\\n                from lfx.schema.data import Data\\n\\n                assert isinstance(result, Data)\\n                assert result.data == {\\\"name\\\": \\\"test\\\"}\\n\\n    @pytest.mark.asyncio\\n    async def test_json_to_data_path_s3_key(self, s3_settings, mock_storage_service):\\n        \\\"\\\"\\\"Test JSONToDataComponent with text path input - handles S3 keys.\\\"\\\"\\\"\\n        from lfx.components.data_source.json_to_data import JSONToDataComponent\\n\\n        mock_storage_service.get_file.return_value = b'{\\\"key\\\": \\\"s3_value\\\"}'\\n\\n        with mock_s3_environment(s3_settings, mock_storage_service):\\n            component = JSONToDataComponent()\\n            component.json_path = \\\"user_123/data.json\\\"  # S3 key format\\n\\n            result = component.convert_json_to_data()\\n\\n            # Should read from S3\\n            from lfx.schema.data import Data\\n\\n            assert isinstance(result, Data)\\n            assert result.data == {\\\"key\\\": \\\"s3_value\\\"}\\n            mock_storage_service.get_file.assert_called_once_with(\\\"user_123\\\", \\\"data.json\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_json_to_data_path_local(self, local_settings):\\n        \\\"\\\"\\\"Test JSONToDataComponent with text path input - handles local paths.\\\"\\\"\\\"\\n        from lfx.components.data_source.json_to_data import JSONToDataComponent\\n\\n        with (\\n            patch(\\\"lfx.services.deps.get_settings_service\\\", return_value=local_settings),\\n            patch(\\\"lfx.base.data.storage_utils.get_settings_service\\\", return_value=local_settings),\\n            patch(\\\"lfx.base.data.storage_utils.read_file_text\\\", new_callable=AsyncMock) as mock_read_file,\\n            patch(\\n                \\\"lfx.components.data_source.json_to_data.read_file_text\\\", new_callable=AsyncMock\\n            ) as mock_read_file_component,\\n        ):\\n            mock_read_file.return_value = '{\\\"local\\\": \\\"data\\\"}'\\n            mock_read_file_component.return_value = '{\\\"local\\\": \\\"data\\\"}'\\n            component = JSONToDataComponent()\\n            component.json_path = \\\"/local/path/data.json\\\"\\n\\n            result = component.convert_json_to_data()\\n\\n            # Should read from local filesystem\\n            from lfx.schema.data import Data\\n\\n            assert isinstance(result, Data)\\n            assert result.data == {\\\"local\\\": \\\"data\\\"}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/data_source/test_s3_uploader_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ff233272d0a709392856514eca041c698603fef14a769959c20fd7c4c23d53c4\",\"content\":\"import os\\nimport tempfile\\nimport uuid\\nfrom pathlib import Path\\n\\nimport boto3\\nimport pytest\\nfrom lfx.schema.data import Data\\nfrom lfx_amazon.components.amazon.s3_bucket_uploader import S3BucketUploaderComponent\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\n@pytest.mark.api_key_required\\nclass TestS3UploaderComponent(ComponentTestBaseWithoutClient):\\n    \\\"\\\"\\\"Unit tests for the S3BucketUploaderComponent.\\n\\n    This test class inherits from ComponentTestBaseWithoutClient and includes several pytest fixtures and a test method\\n    to verify the functionality of the S3BucketUploaderComponent.\\n\\n    Fixtures:\\n        component_class: Returns the component class to be tested.\\n        file_names_mapping: Returns an empty list since this component doesn't have version-specific files.\\n        default_kwargs: Returns an empty dictionary since this component doesn't have any default arguments.\\n        temp_files: Creates three temporary files with predefined content and yields them as Data objects.\\n        Cleans up the files after the test.\\n        s3_bucket: Creates a unique S3 bucket for testing, yields the bucket name, and deletes the bucket\\n        and its contents after the test.\\n\\n    Test Methods:\\n        test_upload: Tests the upload functionality of the S3BucketUploaderComponent by uploading temporary files\\n        to the S3 bucket and verifying their content.\\n    \\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return S3BucketUploaderComponent\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return an empty dictionary since this component doesn't have any default arguments.\\\"\\\"\\\"\\n        return {}\\n\\n    @pytest.fixture\\n    def temp_files(self):\\n        \\\"\\\"\\\"Setup: Create three temporary files.\\\"\\\"\\\"\\n        temp_files = []\\n        contents = [\\n            b\\\"Lorem ipsum dolor sit amet, consectetur adipiscing elit.\\\",\\n            b\\\"Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.\\\",\\n            b\\\"Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris \\\"\\n            b\\\"nisi ut aliquip ex ea commodo consequat.\\\",\\n        ]\\n\\n        for content in contents:\\n            with tempfile.NamedTemporaryFile(suffix=\\\".txt\\\", delete=False) as temp_file:\\n                temp_file.write(content)\\n                temp_file.flush()\\n                temp_file.close()\\n                temp_files.append(temp_file.name)\\n\\n        data = [\\n            Data(data={\\\"file_path\\\": file_path, \\\"text\\\": Path(file_path).read_text(encoding=\\\"utf-8\\\")})\\n            for file_path in temp_files\\n        ]\\n\\n        yield data\\n\\n        # Teardown: Explicitly delete the files\\n        for temp_file in temp_files:\\n            Path(temp_file).unlink()\\n\\n    @pytest.fixture\\n    def s3_bucket(self) -> str:\\n        \\\"\\\"\\\"Generate a unique bucket name (AWS requires globally unique names).\\\"\\\"\\\"\\n        bucket_name = f\\\"graphrag-test-bucket-{uuid.uuid4().hex[:8]}\\\"\\n\\n        # Initialize S3 client using environment variables for credentials\\n        s3 = boto3.client(\\\"s3\\\")\\n\\n        try:\\n            # Create an S3 bucket in your default region\\n            s3.create_bucket(Bucket=bucket_name)\\n\\n            yield bucket_name\\n\\n        finally:\\n            # Teardown: Delete the bucket and its contents\\n            try:\\n                # List and delete all objects in the bucket\\n                objects = s3.list_objects_v2(Bucket=bucket_name).get(\\\"Contents\\\", [])\\n                for obj in objects:\\n                    s3.delete_object(Bucket=bucket_name, Key=obj[\\\"Key\\\"])\\n\\n                # Delete the bucket\\n                s3.delete_bucket(Bucket=bucket_name)\\n            except boto3.exceptions.Boto3Error as e:\\n                pytest.fail(f\\\"Error during teardown: {e}\\\")\\n\\n    def test_upload(self, temp_files, s3_bucket):\\n        \\\"\\\"\\\"Test uploading files to an S3 bucket.\\\"\\\"\\\"\\n        component = S3BucketUploaderComponent()\\n\\n        # Set AWS credentials from environment variables\\n        aws_access_key_id = os.getenv(\\\"AWS_ACCESS_KEY_ID\\\")\\n        aws_secret_access_key = os.getenv(\\\"AWS_SECRET_ACCESS_KEY\\\")\\n        component.set_attributes(\\n            {\\n                \\\"aws_access_key_id\\\": aws_access_key_id,\\n                \\\"aws_secret_access_key\\\": aws_secret_access_key,\\n                \\\"bucket_name\\\": s3_bucket,\\n                \\\"strategy\\\": \\\"Store Original File\\\",\\n                \\\"data_inputs\\\": temp_files,\\n                \\\"s3_prefix\\\": \\\"test\\\",\\n                \\\"strip_path\\\": True,\\n            }\\n        )\\n\\n        component.process_files()\\n\\n        # Check if the files were uploaded. Assumes key and secret are set via environment variables\\n        s3 = boto3.client(\\\"s3\\\")\\n\\n        for temp_file in temp_files:\\n            key = f\\\"test/{Path(temp_file.data['file_path']).name}\\\"\\n            response = s3.get_object(Bucket=s3_bucket, Key=key)\\n            with Path(temp_file.data[\\\"file_path\\\"]).open(\\\"rb\\\") as f:\\n                assert response[\\\"Body\\\"].read() == f.read()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/data_source/test_sql_executor.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a71d921445493d1f8a57dc1ec8ccd1aa09b10238ee219bd3c3b37390ce51a926\",\"content\":\"import sqlite3\\nfrom pathlib import Path\\nfrom unittest.mock import Mock, patch\\n\\nimport pytest\\nfrom lfx.components.data_source.sql_executor import SQL_DATABASE_ENGINE_ARGS, SQLComponent\\nfrom lfx.schema import DataFrame, Message\\nfrom lfx.services.cache.utils import CacheMiss\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass FakeSharedComponentCache:\\n    def __init__(self, values=None):\\n        self.values = values or {}\\n\\n    def get(self, key):\\n        return self.values.get(key, CacheMiss())\\n\\n    def set(self, key, value):\\n        self.values[key] = value\\n\\n\\nclass TestSQLComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def test_db(self):\\n        \\\"\\\"\\\"Fixture that creates a temporary SQLite database for testing.\\\"\\\"\\\"\\n        test_data_dir = Path(__file__).parent.parent.parent.parent / \\\"data\\\"\\n        db_path = test_data_dir / \\\"test.db\\\"\\n        conn = sqlite3.connect(db_path)\\n        cursor = conn.cursor()\\n        cursor.execute(\\\"\\\"\\\"\\n            CREATE TABLE IF NOT EXISTS test (\\n                id INTEGER PRIMARY KEY,\\n                name TEXT\\n            )\\n        \\\"\\\"\\\")\\n        cursor.execute(\\\"\\\"\\\"\\n            INSERT INTO test (id, name)\\n            VALUES (1, 'name_test')\\n        \\\"\\\"\\\")\\n        conn.commit()\\n        conn.close()\\n        yield str(db_path)\\n\\n        Path(db_path).unlink()\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return SQLComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self, test_db):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"database_url\\\": f\\\"sqlite:///{test_db}\\\",\\n            \\\"query\\\": \\\"SELECT * FROM test\\\",\\n            \\\"include_columns\\\": True,\\n            \\\"add_error\\\": False,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return []\\n\\n    def test_successful_query_with_columns(self, component_class: type[SQLComponent], default_kwargs):\\n        \\\"\\\"\\\"Test a successful SQL query with columns included.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n\\n        result = component.build_component()\\n\\n        assert isinstance(result, Message)\\n        assert isinstance(result.text, str)\\n        assert result.text == \\\"[{'id': 1, 'name': 'name_test'}]\\\"\\n\\n    def test_successful_query_without_columns(self, component_class: type[SQLComponent], default_kwargs):\\n        \\\"\\\"\\\"Test a successful SQL query without columns included.\\\"\\\"\\\"\\n        default_kwargs[\\\"include_columns\\\"] = False\\n        component = component_class(**default_kwargs)\\n\\n        result = component.build_component()\\n\\n        assert isinstance(result, Message)\\n        assert isinstance(result.text, str)\\n        assert result.text == \\\"[(1, 'name_test')]\\\"\\n        assert component.status == \\\"[(1, 'name_test')]\\\"\\n        assert component.query == \\\"SELECT * FROM test\\\"\\n\\n    def test_query_error_with_add_error(self, component_class: type[SQLComponent], default_kwargs):\\n        \\\"\\\"\\\"Test a SQL query that raises an error with add_error=True.\\\"\\\"\\\"\\n        default_kwargs[\\\"add_error\\\"] = True\\n        default_kwargs[\\\"query\\\"] = \\\"SELECT * FROM non_existent_table\\\"\\n        component = component_class(**default_kwargs)\\n\\n        result = component.build_component()\\n\\n        assert isinstance(result, Message)\\n        assert isinstance(result.text, str)\\n        assert \\\"no such table: non_existent_table\\\" in result.text\\n        assert \\\"Error:\\\" in result.text\\n        assert \\\"Query: SELECT * FROM non_existent_table\\\" in result.text\\n\\n    def test_run_sql_query(self, component_class: type[SQLComponent], default_kwargs):\\n        \\\"\\\"\\\"Test building a DataFrame from a SQL query.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n\\n        result = component.run_sql_query()\\n\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 1\\n        assert \\\"id\\\" in result.columns\\n        assert \\\"name\\\" in result.columns\\n        assert result.iloc[0][\\\"id\\\"] == 1\\n        assert result.iloc[0][\\\"name\\\"] == \\\"name_test\\\"\\n\\n    def test_maybe_create_db_reuses_cached_database(self, component_class: type[SQLComponent], default_kwargs):\\n        \\\"\\\"\\\"Test cached database reuse without creating a new engine.\\\"\\\"\\\"\\n        cached_db = Mock()\\n        cache = FakeSharedComponentCache({default_kwargs[\\\"database_url\\\"]: cached_db})\\n        component = component_class(**default_kwargs)\\n        component._shared_component_cache = cache\\n\\n        with patch(\\\"lfx.components.data_source.sql_executor.SQLDatabase.from_uri\\\") as mock_from_uri:\\n            component.maybe_create_db()\\n\\n        assert component.db is cached_db\\n        mock_from_uri.assert_not_called()\\n\\n    def test_maybe_create_db_enables_pool_pre_ping(self, component_class: type[SQLComponent], default_kwargs):\\n        \\\"\\\"\\\"Test new cached databases validate stale pooled connections on checkout.\\\"\\\"\\\"\\n        created_db = Mock()\\n        cache = FakeSharedComponentCache()\\n        component = component_class(**default_kwargs)\\n        component._shared_component_cache = cache\\n\\n        with patch(\\n            \\\"lfx.components.data_source.sql_executor.SQLDatabase.from_uri\\\",\\n            return_value=created_db,\\n        ) as mock_from_uri:\\n            component.maybe_create_db()\\n\\n        mock_from_uri.assert_called_once_with(default_kwargs[\\\"database_url\\\"], engine_args=SQL_DATABASE_ENGINE_ARGS)\\n        assert component.db is created_db\\n        assert cache.values[default_kwargs[\\\"database_url\\\"]] is created_db\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/data_source/test_table_loader_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"47c29abfedb3429a33f283c7537bd843e83fe9e7e8f7fb030c65552f8d64616e\",\"content\":\"from lfx.schema.data import Data\\nfrom lfx.schema.table import Column\\n\\nfrom tests.unit.components.data_source.table_schema_demo_component import TableSchemaDemoComponent\\n\\n\\nclass TestTableSchemaDemoComponent:\\n    \\\"\\\"\\\"Tests for TableSchemaDemoComponent that demonstrates table columns with load_from_db functionality.\\\"\\\"\\\"\\n\\n    def test_component_initialization(self):\\n        \\\"\\\"\\\"Test that TableSchemaDemoComponent initializes correctly.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n\\n        assert component.display_name == \\\"Table Schema Demo\\\"\\n        assert component.name == \\\"TableSchemaDemo\\\"\\n        assert len(component.inputs) == 1\\n        assert len(component.outputs) == 2\\n\\n        # Check that the table input has the expected schema\\n        table_input = component.inputs[0]\\n        assert table_input.name == \\\"table_data\\\"\\n        assert hasattr(table_input, \\\"table_schema\\\")\\n\\n    def test_table_schema_configuration(self):\\n        \\\"\\\"\\\"Test that the table schema is properly configured with load_from_db columns.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n        table_input = component.inputs[0]\\n\\n        # The table schema should be defined in the input\\n        _ = [\\n            Column(\\n                name=\\\"username\\\",\\n                display_name=\\\"Username\\\",\\n                type=\\\"text\\\",\\n                default=\\\"admin\\\",\\n                load_from_db=True,\\n                description=\\\"Username that can be loaded from global variables\\\",\\n            ),\\n            Column(\\n                name=\\\"email\\\",\\n                display_name=\\\"Email Address\\\",\\n                type=\\\"text\\\",\\n                default=\\\"user@example.com\\\",\\n                load_from_db=True,\\n                description=\\\"Email address that can be loaded from global variables\\\",\\n            ),\\n            Column(\\n                name=\\\"role\\\",\\n                display_name=\\\"User Role\\\",\\n                type=\\\"text\\\",\\n                default=\\\"user\\\",\\n                load_from_db=False,\\n                description=\\\"User role with static default value\\\",\\n            ),\\n            Column(\\n                name=\\\"active\\\",\\n                display_name=\\\"Active Status\\\",\\n                type=\\\"boolean\\\",\\n                default=True,\\n                load_from_db=False,\\n                description=\\\"Whether the user is active\\\",\\n            ),\\n        ]\\n\\n        # Verify schema exists and has expected columns\\n        assert table_input.table_schema is not None\\n        assert len(table_input.table_schema) == 4\\n\\n        # Check each column's load_from_db setting\\n        schema_columns = table_input.table_schema\\n        assert schema_columns[0].load_from_db is True  # username\\n        assert schema_columns[1].load_from_db is True  # email\\n        assert schema_columns[2].load_from_db is False  # role\\n        assert schema_columns[3].load_from_db is False  # active\\n\\n    def test_load_table_data_with_dict_rows(self):\\n        \\\"\\\"\\\"Test loading table data when rows are dictionaries.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n        component.table_data = [\\n            {\\\"username\\\": \\\"admin\\\", \\\"email\\\": \\\"admin@example.com\\\", \\\"role\\\": \\\"admin\\\", \\\"active\\\": True},\\n            {\\\"username\\\": \\\"user1\\\", \\\"email\\\": \\\"user1@example.com\\\", \\\"role\\\": \\\"user\\\", \\\"active\\\": True},\\n        ]\\n\\n        result = component.load_table_data()\\n\\n        assert isinstance(result, list)\\n        assert len(result) == 2\\n        assert all(isinstance(item, Data) for item in result)\\n\\n        # Check the data content\\n        assert result[0].data[\\\"username\\\"] == \\\"admin\\\"\\n        assert result[0].data[\\\"email\\\"] == \\\"admin@example.com\\\"\\n        assert result[1].data[\\\"username\\\"] == \\\"user1\\\"\\n        assert result[1].data[\\\"email\\\"] == \\\"user1@example.com\\\"\\n\\n    def test_load_table_data_with_data_objects(self):\\n        \\\"\\\"\\\"Test loading table data when rows are already Data objects.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n        data_rows = [\\n            Data(data={\\\"username\\\": \\\"admin\\\", \\\"email\\\": \\\"admin@example.com\\\"}),\\n            Data(data={\\\"username\\\": \\\"user1\\\", \\\"email\\\": \\\"user1@example.com\\\"}),\\n        ]\\n        component.table_data = data_rows\\n\\n        result = component.load_table_data()\\n\\n        assert isinstance(result, list)\\n        assert len(result) == 2\\n        assert all(isinstance(item, Data) for item in result)\\n        assert result[0] == data_rows[0]\\n        assert result[1] == data_rows[1]\\n\\n    def test_load_table_data_with_mixed_types(self):\\n        \\\"\\\"\\\"Test loading table data with mixed types (string, etc.).\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n        component.table_data = [{\\\"username\\\": \\\"admin\\\"}, \\\"user_string\\\", 123]\\n\\n        result = component.load_table_data()\\n\\n        assert isinstance(result, list)\\n        assert len(result) == 3\\n        assert all(isinstance(item, Data) for item in result)\\n\\n        # First item should be a dict\\n        assert result[0].data[\\\"username\\\"] == \\\"admin\\\"\\n\\n        # Second item should be converted to Data with row/index\\n        assert result[1].data[\\\"row\\\"] == \\\"user_string\\\"\\n        assert result[1].data[\\\"index\\\"] == 1\\n\\n        # Third item should be converted to Data with row/index\\n        assert result[2].data[\\\"row\\\"] == \\\"123\\\"\\n        assert result[2].data[\\\"index\\\"] == 2\\n\\n    def test_load_table_data_empty(self):\\n        \\\"\\\"\\\"Test loading empty table data.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n        component.table_data = []\\n\\n        result = component.load_table_data()\\n\\n        assert isinstance(result, list)\\n        assert len(result) == 0\\n\\n    def test_load_table_data_none(self):\\n        \\\"\\\"\\\"Test loading when table_data is None.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n        component.table_data = None\\n\\n        result = component.load_table_data()\\n\\n        assert isinstance(result, list)\\n        assert len(result) == 0\\n\\n    def test_get_schema_info(self):\\n        \\\"\\\"\\\"Test getting schema information about load_from_db columns.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n\\n        # Mock the table_schema attribute access\\n        _ = component.inputs[0]\\n\\n        # The get_schema_info method should return information about the schema\\n        result = component.get_schema_info()\\n\\n        assert isinstance(result, Data)\\n        schema_data = result.data\\n\\n        # Check the structure of returned schema info\\n        assert \\\"total_columns\\\" in schema_data\\n        assert \\\"columns_with_load_from_db\\\" in schema_data\\n        assert \\\"columns_with_static_defaults\\\" in schema_data\\n\\n    def test_load_table_data_error_handling(self):\\n        \\\"\\\"\\\"Test error handling in load_table_data.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n\\n        # Create a mock scenario that would cause an error\\n        # We'll use an object that can't be converted properly\\n        class UnconvertibleObject:\\n            pass\\n\\n        # This should still work due to the error handling that converts to string\\n        component.table_data = [UnconvertibleObject()]\\n\\n        result = component.load_table_data()\\n\\n        # Should convert the unconvertible object to a string representation\\n        assert isinstance(result, list)\\n        assert len(result) == 1\\n        assert isinstance(result[0], Data)\\n\\n    def test_component_outputs(self):\\n        \\\"\\\"\\\"Test that the component has the expected outputs.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n\\n        assert len(component.outputs) == 2\\n\\n        output_names = [output.name for output in component.outputs]\\n        assert \\\"data_list\\\" in output_names\\n        assert \\\"schema_info\\\" in output_names\\n\\n        # Check output methods exist\\n        assert hasattr(component, \\\"load_table_data\\\")\\n        assert hasattr(component, \\\"get_schema_info\\\")\\n\\n\\nclass TestTableSchemaDemoIntegration:\\n    \\\"\\\"\\\"Integration tests for TableSchemaDemoComponent with load_from_db functionality.\\\"\\\"\\\"\\n\\n    def test_column_schema_with_load_from_db_true(self):\\n        \\\"\\\"\\\"Test columns configured with load_from_db=True.\\\"\\\"\\\"\\n        column = Column(name=\\\"api_key\\\", display_name=\\\"API Key\\\", default=\\\"default-key\\\", load_from_db=True, type=\\\"text\\\")\\n\\n        assert column.load_from_db is True\\n        assert column.default == \\\"default-key\\\"\\n        assert column.name == \\\"api_key\\\"\\n\\n    def test_column_schema_with_load_from_db_false(self):\\n        \\\"\\\"\\\"Test columns configured with load_from_db=False.\\\"\\\"\\\"\\n        column = Column(name=\\\"timeout\\\", display_name=\\\"Timeout\\\", default=30, load_from_db=False, type=\\\"integer\\\")\\n\\n        assert column.load_from_db is False\\n        assert column.default == \\\"30\\\"\\n        assert column.name == \\\"timeout\\\"\\n\\n    def test_table_component_schema_serialization(self):\\n        \\\"\\\"\\\"Test that table schema with load_from_db can be serialized.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n        table_input = component.inputs[0]\\n\\n        # The schema should be serializable (important for frontend/backend communication)\\n        assert table_input.table_schema is not None\\n\\n        # Each column should be serializable\\n        for column in table_input.table_schema:\\n            column_dict = column.model_dump()\\n            assert \\\"load_from_db\\\" in column_dict\\n            assert isinstance(column_dict[\\\"load_from_db\\\"], bool)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/data_source/test_table_schema_demo_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"95af7117b6b925930acf06cca3d0e0c5f7283d9287c72d3f5e82a538f7d0e096\",\"content\":\"from lfx.schema.data import Data\\nfrom lfx.schema.table import Column\\n\\nfrom .table_schema_demo_component import TableSchemaDemoComponent\\n\\n\\nclass TestTableSchemaDemoComponent:\\n    \\\"\\\"\\\"Tests for TableSchemaDemoComponent that demonstrates table columns with load_from_db functionality.\\\"\\\"\\\"\\n\\n    def test_component_initialization(self):\\n        \\\"\\\"\\\"Test that TableSchemaDemoComponent initializes correctly.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n\\n        assert component.display_name == \\\"Table Schema Demo\\\"\\n        assert component.name == \\\"TableSchemaDemo\\\"\\n        assert len(component.inputs) == 1\\n        assert len(component.outputs) == 2\\n\\n        # Check that the table input has the expected schema\\n        table_input = component.inputs[0]\\n        assert table_input.name == \\\"table_data\\\"\\n        assert hasattr(table_input, \\\"table_schema\\\")\\n\\n    def test_table_schema_configuration(self):\\n        \\\"\\\"\\\"Test that the table schema is properly configured with load_from_db columns.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n        table_input = component.inputs[0]\\n\\n        # Verify schema exists and has expected columns\\n        assert table_input.table_schema is not None\\n        assert len(table_input.table_schema) == 4\\n\\n        # Check each column's load_from_db setting\\n        schema_columns = table_input.table_schema\\n        assert schema_columns[0].load_from_db is True  # username\\n        assert schema_columns[1].load_from_db is True  # email\\n        assert schema_columns[2].load_from_db is False  # role\\n        assert schema_columns[3].load_from_db is False  # active\\n\\n    def test_load_table_data_with_dict_rows(self):\\n        \\\"\\\"\\\"Test loading table data when rows are dictionaries.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n        component.table_data = [\\n            {\\\"username\\\": \\\"admin\\\", \\\"email\\\": \\\"admin@example.com\\\", \\\"role\\\": \\\"admin\\\", \\\"active\\\": True},\\n            {\\\"username\\\": \\\"user1\\\", \\\"email\\\": \\\"user1@example.com\\\", \\\"role\\\": \\\"user\\\", \\\"active\\\": True},\\n        ]\\n\\n        result = component.load_table_data()\\n\\n        assert isinstance(result, list)\\n        assert len(result) == 2\\n        assert all(isinstance(item, Data) for item in result)\\n\\n        # Check the data content\\n        assert result[0].data[\\\"username\\\"] == \\\"admin\\\"\\n        assert result[0].data[\\\"email\\\"] == \\\"admin@example.com\\\"\\n        assert result[1].data[\\\"username\\\"] == \\\"user1\\\"\\n        assert result[1].data[\\\"email\\\"] == \\\"user1@example.com\\\"\\n\\n    def test_load_table_data_with_data_objects(self):\\n        \\\"\\\"\\\"Test loading table data when rows are already Data objects.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n        data_rows = [\\n            Data(data={\\\"username\\\": \\\"admin\\\", \\\"email\\\": \\\"admin@example.com\\\"}),\\n            Data(data={\\\"username\\\": \\\"user1\\\", \\\"email\\\": \\\"user1@example.com\\\"}),\\n        ]\\n        component.table_data = data_rows\\n\\n        result = component.load_table_data()\\n\\n        assert isinstance(result, list)\\n        assert len(result) == 2\\n        assert all(isinstance(item, Data) for item in result)\\n        assert result[0] == data_rows[0]\\n        assert result[1] == data_rows[1]\\n\\n    def test_load_table_data_with_mixed_types(self):\\n        \\\"\\\"\\\"Test loading table data with mixed types (string, etc.).\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n        component.table_data = [{\\\"username\\\": \\\"admin\\\"}, \\\"user_string\\\", 123]\\n\\n        result = component.load_table_data()\\n\\n        assert isinstance(result, list)\\n        assert len(result) == 3\\n        assert all(isinstance(item, Data) for item in result)\\n\\n        # First item should be a dict\\n        assert result[0].data[\\\"username\\\"] == \\\"admin\\\"\\n\\n        # Second item should be converted to Data with row/index\\n        assert result[1].data[\\\"row\\\"] == \\\"user_string\\\"\\n        assert result[1].data[\\\"index\\\"] == 1\\n\\n        # Third item should be converted to Data with row/index\\n        assert result[2].data[\\\"row\\\"] == \\\"123\\\"\\n        assert result[2].data[\\\"index\\\"] == 2\\n\\n    def test_load_table_data_empty(self):\\n        \\\"\\\"\\\"Test loading empty table data.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n        component.table_data = []\\n\\n        result = component.load_table_data()\\n\\n        assert isinstance(result, list)\\n        assert len(result) == 0\\n\\n    def test_load_table_data_none(self):\\n        \\\"\\\"\\\"Test loading when table_data is None.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n        component.table_data = None\\n\\n        result = component.load_table_data()\\n\\n        assert isinstance(result, list)\\n        assert len(result) == 0\\n\\n    def test_get_schema_info(self):\\n        \\\"\\\"\\\"Test getting schema information about load_from_db columns.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n\\n        # The get_schema_info method should return information about the schema\\n        result = component.get_schema_info()\\n\\n        assert isinstance(result, Data)\\n        schema_data = result.data\\n\\n        # Check the structure of returned schema info\\n        assert \\\"total_columns\\\" in schema_data\\n        assert \\\"columns_with_load_from_db\\\" in schema_data\\n        assert \\\"columns_with_static_defaults\\\" in schema_data\\n\\n    def test_load_table_data_error_handling(self):\\n        \\\"\\\"\\\"Test error handling in load_table_data.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n\\n        # Create a mock scenario that would cause an error\\n        # We'll use an object that can't be converted properly\\n        class UnconvertibleObject:\\n            pass\\n\\n        # This should still work due to the error handling that converts to string\\n        component.table_data = [UnconvertibleObject()]\\n\\n        result = component.load_table_data()\\n\\n        # Should convert the unconvertible object to a string representation\\n        assert isinstance(result, list)\\n        assert len(result) == 1\\n        assert isinstance(result[0], Data)\\n\\n    def test_component_outputs(self):\\n        \\\"\\\"\\\"Test that the component has the expected outputs.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n\\n        assert len(component.outputs) == 2\\n\\n        output_names = [output.name for output in component.outputs]\\n        assert \\\"data_list\\\" in output_names\\n        assert \\\"schema_info\\\" in output_names\\n\\n        # Check output methods exist\\n        assert hasattr(component, \\\"load_table_data\\\")\\n        assert hasattr(component, \\\"get_schema_info\\\")\\n\\n\\nclass TestTableSchemaDemoIntegration:\\n    \\\"\\\"\\\"Integration tests for TableSchemaDemoComponent with load_from_db functionality.\\\"\\\"\\\"\\n\\n    def test_column_schema_with_load_from_db_true(self):\\n        \\\"\\\"\\\"Test columns configured with load_from_db=True.\\\"\\\"\\\"\\n        column = Column(name=\\\"api_key\\\", display_name=\\\"API Key\\\", default=\\\"default-key\\\", load_from_db=True, type=\\\"text\\\")\\n\\n        assert column.load_from_db is True\\n        assert column.default == \\\"default-key\\\"\\n        assert column.name == \\\"api_key\\\"\\n\\n    def test_column_schema_with_load_from_db_false(self):\\n        \\\"\\\"\\\"Test columns configured with load_from_db=False.\\\"\\\"\\\"\\n        column = Column(name=\\\"timeout\\\", display_name=\\\"Timeout\\\", default=30, load_from_db=False, type=\\\"integer\\\")\\n\\n        assert column.load_from_db is False\\n        assert column.default == \\\"30\\\"\\n        assert column.name == \\\"timeout\\\"\\n\\n    def test_table_component_schema_serialization(self):\\n        \\\"\\\"\\\"Test that table schema with load_from_db can be serialized.\\\"\\\"\\\"\\n        component = TableSchemaDemoComponent()\\n        table_input = component.inputs[0]\\n\\n        # The schema should be serializable (important for frontend/backend communication)\\n        assert table_input.table_schema is not None\\n\\n        # Each column should be serializable\\n        for column in table_input.table_schema:\\n            column_dict = column.model_dump()\\n            assert \\\"load_from_db\\\" in column_dict\\n            assert isinstance(column_dict[\\\"load_from_db\\\"], bool)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/data_source/test_url_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a2d4714bd8445d73fa9adace38d31ddff922493c48e41cf84260994cfd4fc3c1\",\"content\":\"\\\"\\\"\\\"Tests for the URL component.\\n\\nThe URL component fetches pages with ``httpx`` and enforces DNS-pinned SSRF\\nprotection (see ``test_dns_rebinding.py`` for the rebinding-specific coverage).\\nThese tests exercise content extraction, output formats, URL normalization, and\\nthe SSRF guard without making real network requests by stubbing the per-URL\\nfetch (``_fetch_url_with_pinning``) and, for SSRF, validating direct IPs.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.components.data_source.url import URLComponent\\nfrom lfx.schema import DataFrame\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\ndef _static_fetch(html: str, metadata: dict):\\n    \\\"\\\"\\\"Build an async stand-in for ``URLComponent._fetch_url_with_pinning``.\\n\\n    Returns the same ``(html, metadata)`` for every URL so tests can drive the\\n    extraction / formatting logic without any network access.\\n    \\\"\\\"\\\"\\n\\n    async def _fetch(_self, _url, _validated_ips, _headers):\\n        return html, metadata\\n\\n    return _fetch\\n\\n\\ndef _per_url_fetch(pages: dict):\\n    \\\"\\\"\\\"Async stand-in returning ``(html, metadata)`` keyed by the requested URL.\\n\\n    Unknown URLs yield empty content (treated as \\\"nothing fetched\\\").\\n    \\\"\\\"\\\"\\n\\n    async def _fetch(_self, url, _validated_ips, _headers):\\n        return pages.get(url, (\\\"\\\", {}))\\n\\n    return _fetch\\n\\n\\n@pytest.fixture\\ndef disable_ssrf(monkeypatch):\\n    \\\"\\\"\\\"Disable SSRF protection so ``ensure_url`` skips DNS resolution.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"false\\\")\\n\\n\\nclass TestURLComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return URLComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"urls\\\": [\\\"https://google.com\\\"],\\n            \\\"format\\\": \\\"Text\\\",\\n            \\\"max_depth\\\": 1,\\n            \\\"prevent_outside\\\": True,\\n            \\\"use_async\\\": True,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return [\\n            {\\\"version\\\": \\\"1.0.19\\\", \\\"module\\\": \\\"data\\\", \\\"file_name\\\": \\\"URL\\\"},\\n            {\\\"version\\\": \\\"1.1.0\\\", \\\"module\\\": \\\"data\\\", \\\"file_name\\\": \\\"url\\\"},\\n            {\\\"version\\\": \\\"1.1.1\\\", \\\"module\\\": \\\"data\\\", \\\"file_name\\\": \\\"url\\\"},\\n            {\\\"version\\\": \\\"1.2.0\\\", \\\"module\\\": \\\"data\\\", \\\"file_name\\\": \\\"url\\\"},\\n        ]\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.usefixtures(\\\"disable_ssrf\\\")\\n    async def test_url_component_basic_functionality(self, monkeypatch):\\n        \\\"\\\"\\\"Fetched content and metadata are surfaced on the output DataFrame.\\\"\\\"\\\"\\n        metadata = {\\n            \\\"source\\\": \\\"https://example.com\\\",\\n            \\\"title\\\": \\\"Test Page\\\",\\n            \\\"description\\\": \\\"Test Description\\\",\\n            \\\"content_type\\\": \\\"text/html\\\",\\n            \\\"language\\\": \\\"en\\\",\\n        }\\n        monkeypatch.setattr(\\n            URLComponent,\\n            \\\"_fetch_url_with_pinning\\\",\\n            _static_fetch(\\\"<html><body>test content</body></html>\\\", metadata),\\n        )\\n        component = URLComponent()\\n        component.set_attributes({\\\"urls\\\": [\\\"https://example.com\\\"], \\\"max_depth\\\": 1, \\\"format\\\": \\\"Text\\\"})\\n\\n        data_frame = await component.fetch_content()\\n        assert isinstance(data_frame, DataFrame)\\n        assert len(data_frame) == 1\\n\\n        row = data_frame.iloc[0]\\n        assert row[\\\"text\\\"] == \\\"test content\\\"\\n        assert row[\\\"url\\\"] == \\\"https://example.com\\\"\\n        assert row[\\\"title\\\"] == \\\"Test Page\\\"\\n        assert row[\\\"description\\\"] == \\\"Test Description\\\"\\n        assert row[\\\"content_type\\\"] == \\\"text/html\\\"\\n        assert row[\\\"language\\\"] == \\\"en\\\"\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.usefixtures(\\\"disable_ssrf\\\")\\n    async def test_url_component_multiple_urls(self, monkeypatch):\\n        \\\"\\\"\\\"Each provided URL produces its own row.\\\"\\\"\\\"\\n        pages = {\\n            \\\"https://example.com\\\": (\\\"<html><body>first</body></html>\\\", {\\\"source\\\": \\\"https://example.com\\\"}),\\n            \\\"https://example.org\\\": (\\\"<html><body>second</body></html>\\\", {\\\"source\\\": \\\"https://example.org\\\"}),\\n        }\\n        monkeypatch.setattr(URLComponent, \\\"_fetch_url_with_pinning\\\", _per_url_fetch(pages))\\n        component = URLComponent()\\n        component.set_attributes({\\\"urls\\\": [\\\"https://example.com\\\", \\\"https://example.org\\\"], \\\"max_depth\\\": 1})\\n\\n        data_frame = await component.fetch_content()\\n        assert len(data_frame) == 2\\n        texts = set(data_frame[\\\"text\\\"])\\n        assert texts == {\\\"first\\\", \\\"second\\\"}\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.usefixtures(\\\"disable_ssrf\\\")\\n    async def test_url_component_text_format(self, monkeypatch):\\n        \\\"\\\"\\\"Text format strips HTML tags to plain text.\\\"\\\"\\\"\\n        html = \\\"<html><body><h1>Heading</h1><p>Hello world</p></body></html>\\\"\\n        monkeypatch.setattr(\\n            URLComponent, \\\"_fetch_url_with_pinning\\\", _static_fetch(html, {\\\"source\\\": \\\"https://example.com\\\"})\\n        )\\n        component = URLComponent()\\n        component.set_attributes({\\\"urls\\\": [\\\"https://example.com\\\"], \\\"format\\\": \\\"Text\\\"})\\n\\n        data_frame = await component.fetch_content()\\n        text = data_frame.iloc[0][\\\"text\\\"]\\n        assert \\\"<h1>\\\" not in text\\n        assert \\\"Heading\\\" in text\\n        assert \\\"Hello world\\\" in text\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.usefixtures(\\\"disable_ssrf\\\")\\n    async def test_url_component_html_format(self, monkeypatch):\\n        \\\"\\\"\\\"HTML format preserves the raw markup.\\\"\\\"\\\"\\n        html = \\\"<html><body><h1>Heading</h1><p>Hello world</p></body></html>\\\"\\n        monkeypatch.setattr(\\n            URLComponent, \\\"_fetch_url_with_pinning\\\", _static_fetch(html, {\\\"source\\\": \\\"https://example.com\\\"})\\n        )\\n        component = URLComponent()\\n        component.set_attributes({\\\"urls\\\": [\\\"https://example.com\\\"], \\\"format\\\": \\\"HTML\\\"})\\n\\n        data_frame = await component.fetch_content()\\n        text = data_frame.iloc[0][\\\"text\\\"]\\n        assert \\\"<h1>Heading</h1>\\\" in text\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.usefixtures(\\\"disable_ssrf\\\")\\n    async def test_url_component_markdown_format(self, monkeypatch):\\n        \\\"\\\"\\\"Markdown format converts HTML headings/paragraphs to markdown.\\\"\\\"\\\"\\n        html = \\\"<html><body><h1>Heading</h1><p>Hello world</p></body></html>\\\"\\n        monkeypatch.setattr(\\n            URLComponent, \\\"_fetch_url_with_pinning\\\", _static_fetch(html, {\\\"source\\\": \\\"https://example.com\\\"})\\n        )\\n        component = URLComponent()\\n        component.set_attributes({\\\"urls\\\": [\\\"https://example.com\\\"], \\\"format\\\": \\\"Markdown\\\"})\\n\\n        data_frame = await component.fetch_content()\\n        text = data_frame.iloc[0][\\\"text\\\"]\\n        assert \\\"# Heading\\\" in text\\n        assert \\\"Hello world\\\" in text\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.usefixtures(\\\"disable_ssrf\\\")\\n    async def test_url_component_missing_metadata(self, monkeypatch):\\n        \\\"\\\"\\\"Missing metadata fields default to empty strings.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\n            URLComponent,\\n            \\\"_fetch_url_with_pinning\\\",\\n            _static_fetch(\\\"<html><body>test content</body></html>\\\", {\\\"source\\\": \\\"https://example.com\\\"}),\\n        )\\n        component = URLComponent()\\n        component.set_attributes({\\\"urls\\\": [\\\"https://example.com\\\"]})\\n\\n        data_frame = await component.fetch_content()\\n        row = data_frame.iloc[0]\\n        assert row[\\\"text\\\"] == \\\"test content\\\"\\n        assert row[\\\"url\\\"] == \\\"https://example.com\\\"\\n        assert row[\\\"title\\\"] == \\\"\\\"\\n        assert row[\\\"description\\\"] == \\\"\\\"\\n        assert row[\\\"content_type\\\"] == \\\"\\\"\\n        assert row[\\\"language\\\"] == \\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.usefixtures(\\\"disable_ssrf\\\")\\n    async def test_url_component_error_handling_empty_urls(self):\\n        \\\"\\\"\\\"An empty URL list raises a clear error.\\\"\\\"\\\"\\n        component = URLComponent()\\n        component.set_attributes({\\\"urls\\\": []})\\n        with pytest.raises(ValueError, match=\\\"Error loading documents:\\\"):\\n            await component.fetch_content()\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.usefixtures(\\\"disable_ssrf\\\")\\n    async def test_url_component_error_handling_no_documents(self, monkeypatch):\\n        \\\"\\\"\\\"When no page yields content, a 'no documents' error is raised.\\\"\\\"\\\"\\n        monkeypatch.setattr(URLComponent, \\\"_fetch_url_with_pinning\\\", _static_fetch(\\\"\\\", {}))\\n        component = URLComponent()\\n        component.set_attributes({\\\"urls\\\": [\\\"https://example.com\\\"]})\\n        with pytest.raises(ValueError, match=\\\"Error loading documents:\\\"):\\n            await component.fetch_content()\\n\\n    @pytest.mark.usefixtures(\\\"disable_ssrf\\\")\\n    def test_url_component_ensure_url(self):\\n        \\\"\\\"\\\"ensure_url normalizes the scheme and rejects malformed URLs.\\\"\\\"\\\"\\n        component = URLComponent()\\n\\n        # Missing scheme defaults to https; returns (url, pinned_ips).\\n        url, ips = component.ensure_url(\\\"example.com\\\")\\n        assert url == \\\"https://example.com\\\"\\n        assert ips == []\\n\\n        # Existing scheme is preserved.\\n        url, _ips = component.ensure_url(\\\"https://example.com\\\")\\n        assert url == \\\"https://example.com\\\"\\n\\n        # Malformed URL is rejected.\\n        with pytest.raises(ValueError, match=\\\"Invalid URL\\\"):\\n            component.ensure_url(\\\"not a url\\\")\\n\\n\\nclass TestURLComponentSSRFProtection:\\n    \\\"\\\"\\\"SSRF protection is enforced when ensuring and fetching URLs.\\\"\\\"\\\"\\n\\n    @pytest.fixture(autouse=True)\\n    def enable_ssrf(self, monkeypatch):\\n        \\\"\\\"\\\"Enable SSRF protection with an empty allowlist for these tests.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"true\\\")\\n        monkeypatch.delenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", raising=False)\\n\\n    def test_ensure_url_blocks_localhost(self):\\n        \\\"\\\"\\\"Loopback addresses are blocked.\\\"\\\"\\\"\\n        component = URLComponent()\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            component.ensure_url(\\\"http://127.0.0.1:8080\\\")\\n\\n    def test_ensure_url_blocks_private_ip(self):\\n        \\\"\\\"\\\"RFC 1918 private addresses are blocked.\\\"\\\"\\\"\\n        component = URLComponent()\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            component.ensure_url(\\\"http://192.168.1.1/admin\\\")\\n\\n    def test_ensure_url_blocks_metadata_endpoint(self):\\n        \\\"\\\"\\\"The cloud metadata endpoint is blocked.\\\"\\\"\\\"\\n        component = URLComponent()\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            component.ensure_url(\\\"http://169.254.169.254/latest/meta-data/\\\")\\n\\n    def test_ensure_url_allows_public_ip(self):\\n        \\\"\\\"\\\"A public IP passes and is returned for DNS pinning.\\\"\\\"\\\"\\n        component = URLComponent()\\n        url, ips = component.ensure_url(\\\"http://8.8.8.8/\\\")\\n        assert url == \\\"http://8.8.8.8/\\\"\\n        assert ips == [\\\"8.8.8.8\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_ssrf_protection_in_fetch_content(self):\\n        \\\"\\\"\\\"A blocked URL surfaces the SSRF error from fetch_content (not a generic message).\\\"\\\"\\\"\\n        component = URLComponent()\\n        component.set_attributes({\\\"urls\\\": [\\\"http://127.0.0.1:9999\\\"]})\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            await component.fetch_url_contents()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/data_source/test_web_search.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ee57b0caf2d2729f42480dad584f0309fe118c8416b77e13f8d3c3cf3d665ec5\",\"content\":\"from unittest.mock import MagicMock, Mock, patch\\n\\nimport pandas as pd\\nimport pytest\\nfrom lfx.components.data_source.web_search import (\\n    DEFAULT_MAX_CONTENT_LENGTH,\\n    DEFAULT_MAX_RESULTS,\\n    TRUNCATION_SUFFIX,\\n    WebSearchComponent,\\n)\\nfrom lfx.schema import Data, DataFrame, Message\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError\\nfrom pydantic import SecretStr, ValidationError\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestWebSearchComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return WebSearchComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        return {\\n            \\\"search_mode\\\": \\\"Web\\\",\\n            \\\"query\\\": \\\"OpenAI GPT-4\\\",\\n            \\\"timeout\\\": 5,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return the file names mapping for the component.\\\"\\\"\\\"\\n        return []\\n\\n    async def test_invalid_url_handling(self):\\n        \\\"\\\"\\\"Test invalid URL handling.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n\\n        # Test invalid URL\\n        invalid_url = \\\"htp://invalid-url\\\"\\n\\n        # Ensure the URL is invalid\\n        with pytest.raises(ValueError, match=\\\"Invalid URL\\\"):\\n            component.ensure_url(invalid_url)\\n\\n    def test_validate_url(self):\\n        \\\"\\\"\\\"Test URL validation.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n\\n        # Valid URLs\\n        assert component.validate_url(\\\"https://example.com\\\")\\n        assert component.validate_url(\\\"http://example.com\\\")\\n        assert component.validate_url(\\\"www.example.com\\\")\\n        assert component.validate_url(\\\"example.com\\\")\\n        assert component.validate_url(\\\"https://subdomain.example.co.uk\\\")\\n\\n        # Invalid URLs\\n        assert not component.validate_url(\\\"not a url at all\\\")\\n        assert not component.validate_url(\\\"://missing-protocol\\\")\\n\\n    def test_ensure_url(self):\\n        \\\"\\\"\\\"Test ensure_url adds protocol if missing.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n\\n        assert component.ensure_url(\\\"https://example.com\\\") == \\\"https://example.com\\\"\\n        assert component.ensure_url(\\\"http://example.com\\\") == \\\"http://example.com\\\"\\n        assert component.ensure_url(\\\"example.com\\\") == \\\"https://example.com\\\"\\n        assert component.ensure_url(\\\"www.example.com\\\") == \\\"https://www.example.com\\\"\\n\\n    @patch(\\\"lfx.components.data_source.web_search.is_ssrf_protection_enabled\\\", return_value=True)\\n    @patch(\\\"lfx.components.data_source.web_search.create_ssrf_protected_sync_client\\\")\\n    @patch(\\\"lfx.components.data_source.web_search.validate_and_resolve_url\\\")\\n    def test_safe_get_url_validates_and_uses_dns_pinning(self, mock_validate, mock_create_client, mock_ssrf_enabled):\\n        \\\"\\\"\\\"Arbitrary URL fetches must use the shared SSRF validation and DNS pinning path.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.timeout = 5\\n        mock_validate.return_value = (\\\"https://example.com/feed.rss\\\", [\\\"93.184.216.34\\\"])\\n\\n        mock_response = Mock()\\n        mock_client = MagicMock()\\n        mock_client.__enter__.return_value = mock_client\\n        mock_client.get.return_value = mock_response\\n        mock_create_client.return_value = mock_client\\n\\n        result = component._safe_get_url(\\\"example.com/feed.rss\\\")\\n\\n        assert result is mock_response\\n        mock_validate.assert_called_once_with(\\\"https://example.com/feed.rss\\\")\\n        mock_ssrf_enabled.assert_called_once()\\n        mock_create_client.assert_called_once_with(hostname=\\\"example.com\\\", validated_ips=[\\\"93.184.216.34\\\"])\\n        mock_client.get.assert_called_once_with(\\n            \\\"https://example.com/feed.rss\\\", headers=None, timeout=5, follow_redirects=False\\n        )\\n\\n    @patch(\\\"lfx.components.data_source.web_search.validate_and_resolve_url\\\")\\n    def test_safe_get_url_blocks_ssrf_targets(self, mock_validate):\\n        \\\"\\\"\\\"SSRF validation failures should be surfaced before any network fetch.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.timeout = 5\\n        mock_validate.side_effect = SSRFProtectionError(\\\"blocked\\\")\\n\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection: blocked\\\"):\\n            component._safe_get_url(\\\"http://169.254.169.254/latest/meta-data\\\")\\n\\n        mock_validate.assert_called_once_with(\\\"http://169.254.169.254/latest/meta-data\\\")\\n\\n    def test_sanitize_query(self):\\n        \\\"\\\"\\\"Test query sanitization.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n\\n        # Test removal of dangerous characters\\n        assert component._sanitize_query('<script>alert(\\\"test\\\")</script>') == \\\"scriptalert(test)/script\\\"\\n        assert component._sanitize_query(\\\"test'query\\\\\\\"with<dangerous>chars\\\") == \\\"testquerywithdangerouschars\\\"\\n        assert component._sanitize_query(\\\"  normal query  \\\") == \\\"normal query\\\"\\n\\n    def test_clean_html(self):\\n        \\\"\\\"\\\"Test HTML cleaning.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n\\n        html = '<p>This is <b>bold</b> text with <a href=\\\"#\\\">link</a></p>'\\n        expected = \\\"This is bold text with link\\\"\\n        assert component.clean_html(html) == expected\\n\\n        # Test with complex HTML\\n        html = \\\"<div><h1>Title</h1><p>Paragraph</p></div>\\\"\\n        expected = \\\"Title Paragraph\\\"\\n        assert component.clean_html(html) == expected\\n\\n    def test_update_build_config_web_mode(self):\\n        \\\"\\\"\\\"Test build config update for Web mode.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        build_config = {\\\"query\\\": {\\\"info\\\": \\\"\\\", \\\"display_name\\\": \\\"\\\"}}\\n\\n        result = component.update_build_config(build_config, \\\"Web\\\", \\\"search_mode\\\")\\n        assert result[\\\"query\\\"][\\\"info\\\"] == \\\"Keywords to search for\\\"\\n        assert result[\\\"query\\\"][\\\"display_name\\\"] == \\\"Search Query\\\"\\n\\n    def test_update_build_config_news_mode(self):\\n        \\\"\\\"\\\"Test build config update for News mode.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        build_config = {\\\"query\\\": {\\\"info\\\": \\\"\\\", \\\"display_name\\\": \\\"\\\"}}\\n\\n        result = component.update_build_config(build_config, \\\"News\\\", \\\"search_mode\\\")\\n        assert result[\\\"query\\\"][\\\"info\\\"] == \\\"Search keywords for news articles.\\\"\\n        assert result[\\\"query\\\"][\\\"display_name\\\"] == \\\"Search Query\\\"\\n\\n    def test_update_build_config_rss_mode(self):\\n        \\\"\\\"\\\"Test build config update for RSS mode.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        build_config = {\\\"query\\\": {\\\"info\\\": \\\"\\\", \\\"display_name\\\": \\\"\\\"}}\\n\\n        result = component.update_build_config(build_config, \\\"RSS\\\", \\\"search_mode\\\")\\n        assert result[\\\"query\\\"][\\\"info\\\"] == \\\"RSS feed URL to parse\\\"\\n        assert result[\\\"query\\\"][\\\"display_name\\\"] == \\\"RSS Feed URL\\\"\\n\\n    @patch.object(WebSearchComponent, \\\"_safe_get_url\\\")\\n    @patch(\\\"lfx.components.data_source.web_search.requests.get\\\")\\n    def test_perform_web_search_success(self, mock_get, mock_safe_get):\\n        \\\"\\\"\\\"Test successful web search.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"test query\\\"\\n        component.timeout = 5\\n\\n        # Mock DuckDuckGo response\\n        mock_response = Mock()\\n        mock_response.text = \\\"\\\"\\\"\\n        <html>\\n            <div class=\\\"result\\\">\\n                <a class=\\\"result__a\\\" href=\\\"?uddg=https%3A%2F%2Fexample.com\\\">Test Title</a>\\n                <a class=\\\"result__snippet\\\">Test snippet content</a>\\n            </div>\\n        </html>\\n        \\\"\\\"\\\"\\n        mock_response.headers = {\\\"content-type\\\": \\\"text/html\\\"}\\n        mock_response.raise_for_status.return_value = None\\n\\n        # Mock the page fetch\\n        mock_page_response = Mock()\\n        mock_page_response.text = \\\"<html><body>Page content</body></html>\\\"\\n        mock_page_response.raise_for_status.return_value = None\\n\\n        mock_get.return_value = mock_response\\n        mock_safe_get.return_value = mock_page_response\\n\\n        result = component.perform_web_search()\\n\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 1\\n        assert result.iloc[0][\\\"title\\\"] == \\\"Test Title\\\"\\n        assert result.iloc[0][\\\"snippet\\\"] == \\\"Test snippet content\\\"\\n        assert \\\"Page content\\\" in result.iloc[0][\\\"content\\\"]\\n\\n    @patch(\\\"lfx.components.data_source.web_search.requests.get\\\")\\n    def test_perform_web_search_no_results(self, mock_get):\\n        \\\"\\\"\\\"Test web search with no results.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"test query\\\"\\n        component.timeout = 5\\n\\n        mock_response = Mock()\\n        mock_response.text = \\\"\\\"\\n        mock_response.headers = {\\\"content-type\\\": \\\"text/html\\\"}\\n        mock_response.raise_for_status.return_value = None\\n\\n        mock_get.return_value = mock_response\\n\\n        result = component.perform_web_search()\\n\\n        assert isinstance(result, DataFrame)\\n        assert \\\"No results found\\\" in result.iloc[0][\\\"snippet\\\"]\\n\\n    @patch(\\\"lfx.components.data_source.web_search.requests.get\\\")\\n    def test_perform_web_search_request_error(self, mock_get):\\n        \\\"\\\"\\\"Test web search with request error.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"test query\\\"\\n        component.timeout = 5\\n\\n        from requests import RequestException\\n\\n        mock_get.side_effect = RequestException(\\\"Connection error\\\")\\n\\n        result = component.perform_web_search()\\n\\n        assert isinstance(result, DataFrame)\\n        assert \\\"Connection error\\\" in result.iloc[0][\\\"snippet\\\"]\\n\\n    @patch(\\\"lfx.components.data_source.web_search.requests.get\\\")\\n    def test_perform_news_search_with_query(self, mock_get):\\n        \\\"\\\"\\\"Test news search with query.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"test news\\\"\\n        component.timeout = 5\\n\\n        # Mock RSS response\\n        mock_response = Mock()\\n        mock_response.content = b\\\"\\\"\\\"<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>\\n        <rss>\\n            <channel>\\n                <item>\\n                    <title>Test News Title</title>\\n                    <link>https://news.example.com</link>\\n                    <pubDate>Mon, 01 Jan 2024 00:00:00 GMT</pubDate>\\n                    <description>Test news description</description>\\n                </item>\\n            </channel>\\n        </rss>\\n        \\\"\\\"\\\"\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        result = component.perform_news_search()\\n\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 1\\n        assert result.iloc[0][\\\"title\\\"] == \\\"Test News Title\\\"\\n        assert result.iloc[0][\\\"link\\\"] == \\\"https://news.example.com\\\"\\n        assert result.iloc[0][\\\"summary\\\"] == \\\"Test news description\\\"\\n\\n    @patch(\\\"lfx.components.data_source.web_search.requests.get\\\")\\n    def test_perform_news_search_with_topic(self, mock_get):\\n        \\\"\\\"\\\"Test news search with topic.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.topic = \\\"TECHNOLOGY\\\"\\n        component.timeout = 5\\n\\n        # Mock RSS response\\n        mock_response = Mock()\\n        mock_response.content = b\\\"\\\"\\\"<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>\\n        <rss>\\n            <channel>\\n                <item>\\n                    <title>Tech News</title>\\n                    <link>https://tech.example.com</link>\\n                    <pubDate>Mon, 01 Jan 2024 00:00:00 GMT</pubDate>\\n                    <description>Technology news</description>\\n                </item>\\n            </channel>\\n        </rss>\\n        \\\"\\\"\\\"\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        result = component.perform_news_search()\\n\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 1\\n        # Check that the URL was constructed with topic\\n        mock_get.assert_called_once()\\n        call_args = mock_get.call_args[0][0]\\n        assert \\\"topic/TECHNOLOGY\\\" in call_args\\n\\n    @patch(\\\"lfx.components.data_source.web_search.requests.get\\\")\\n    def test_perform_news_search_no_params(self, mock_get):  # noqa: ARG002\\n        \\\"\\\"\\\"Test news search with no parameters.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.timeout = 5\\n\\n        result = component.perform_news_search()\\n\\n        assert isinstance(result, DataFrame)\\n        assert \\\"No search parameters provided\\\" in result.iloc[0][\\\"summary\\\"]\\n\\n    @patch.object(WebSearchComponent, \\\"_safe_get_url\\\")\\n    def test_perform_rss_read_success(self, mock_get):\\n        \\\"\\\"\\\"Test successful RSS feed reading.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"https://example.com/feed.rss\\\"\\n        component.timeout = 5\\n\\n        # Mock RSS response\\n        mock_response = Mock()\\n        mock_response.content = b\\\"\\\"\\\"<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?>\\n        <rss>\\n            <channel>\\n                <item>\\n                    <title>RSS Item 1</title>\\n                    <link>https://example.com/item1</link>\\n                    <pubDate>Mon, 01 Jan 2024 00:00:00 GMT</pubDate>\\n                    <description>Description 1</description>\\n                </item>\\n                <item>\\n                    <title>RSS Item 2</title>\\n                    <link>https://example.com/item2</link>\\n                    <pubDate>Tue, 02 Jan 2024 00:00:00 GMT</pubDate>\\n                    <description>Description 2</description>\\n                </item>\\n            </channel>\\n        </rss>\\n        \\\"\\\"\\\"\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        result = component.perform_rss_read()\\n\\n        assert isinstance(result, DataFrame)\\n        assert len(result) == 2\\n        assert result.iloc[0][\\\"title\\\"] == \\\"RSS Item 1\\\"\\n        assert result.iloc[1][\\\"title\\\"] == \\\"RSS Item 2\\\"\\n\\n    @patch.object(WebSearchComponent, \\\"_safe_get_url\\\")\\n    def test_perform_rss_read_empty_response(self, mock_get):\\n        \\\"\\\"\\\"Test RSS read with empty response.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"https://example.com/feed.rss\\\"\\n        component.timeout = 5\\n\\n        mock_response = Mock()\\n        mock_response.content = b\\\"\\\"\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        result = component.perform_rss_read()\\n\\n        assert isinstance(result, DataFrame)\\n        assert \\\"Empty response received\\\" in result.iloc[0][\\\"summary\\\"]\\n\\n    @patch.object(WebSearchComponent, \\\"_safe_get_url\\\")\\n    def test_perform_rss_read_invalid_xml(self, mock_get):\\n        \\\"\\\"\\\"Test RSS read with invalid XML - returns empty DataFrame when no items found.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"https://example.com/feed.rss\\\"\\n        component.timeout = 5\\n\\n        mock_response = Mock()\\n        mock_response.content = b\\\"This is not valid XML\\\"\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        result = component.perform_rss_read()\\n\\n        assert isinstance(result, DataFrame)\\n        # When no RSS items are found, it returns an empty DataFrame\\n        assert len(result) == 0\\n\\n    def test_perform_rss_read_no_url(self):\\n        \\\"\\\"\\\"Test RSS read with no URL provided.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"\\\"\\n\\n        result = component.perform_rss_read()\\n\\n        assert isinstance(result, DataFrame)\\n        assert \\\"No RSS URL provided\\\" in result.iloc[0][\\\"summary\\\"]\\n\\n    def test_perform_rss_read_blocks_ssrf(self, monkeypatch):\\n        \\\"\\\"\\\"Security: RSS mode must not fetch internal/metadata URLs when SSRF protection is on.\\n\\n        The query is treated as a raw URL in RSS mode; a tenant could point it at the cloud\\n        metadata endpoint. With SSRF protection enabled the request must be blocked before any\\n        network call.\\n        \\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"true\\\")\\n        component = WebSearchComponent()\\n        component.query = \\\"http://169.254.169.254/latest/meta-data/iam/security-credentials/\\\"\\n        component.timeout = 5\\n\\n        with patch(\\\"lfx.components.data_source.web_search.requests.get\\\") as mock_get:\\n            result = component.perform_rss_read()\\n\\n        mock_get.assert_not_called()\\n        assert isinstance(result, DataFrame)\\n        assert \\\"SSRF Protection\\\" in result.iloc[0][\\\"summary\\\"]\\n\\n    def test_perform_web_search_blocks_ssrf_on_result_links(self, monkeypatch):\\n        \\\"\\\"\\\"Security: result links resolving to internal IPs are not fetched when SSRF is on.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"true\\\")\\n        component = WebSearchComponent()\\n        component.query = \\\"test query\\\"\\n        component.timeout = 5\\n\\n        mock_response = Mock()\\n        mock_response.text = (\\n            '<html><div class=\\\"result\\\">'\\n            '<a class=\\\"result__a\\\" href=\\\"?uddg=http%3A%2F%2F169.254.169.254%2Flatest%2Fmeta-data%2F\\\">Title</a>'\\n            '<a class=\\\"result__snippet\\\">snippet</a>'\\n            \\\"</div></html>\\\"\\n        )\\n        mock_response.headers = {\\\"content-type\\\": \\\"text/html\\\"}\\n        mock_response.raise_for_status.return_value = None\\n\\n        with patch(\\\"lfx.components.data_source.web_search.requests.get\\\") as mock_get:\\n            mock_get.return_value = mock_response\\n            result = component.perform_web_search()\\n\\n        # Only the search-engine request fired; the internal result link was never fetched.\\n        assert mock_get.call_count == 1\\n        assert isinstance(result, DataFrame)\\n        assert \\\"Blocked by SSRF protection\\\" in result.iloc[0][\\\"content\\\"]\\n\\n    @staticmethod\\n    def _serp_html(result_count: int) -> str:\\n        blocks = \\\"\\\".join(\\n            f'<div class=\\\"result\\\">'\\n            f'<a class=\\\"result__a\\\" href=\\\"?uddg=https%3A%2F%2Fexample.com%2F{i}\\\">Title {i}</a>'\\n            f'<a class=\\\"result__snippet\\\">Snippet {i}</a>'\\n            f\\\"</div>\\\"\\n            for i in range(result_count)\\n        )\\n        return f\\\"<html>{blocks}</html>\\\"\\n\\n    @staticmethod\\n    def _serp_response(result_count: int) -> Mock:\\n        response = Mock()\\n        response.text = TestWebSearchComponent._serp_html(result_count)\\n        response.headers = {\\\"content-type\\\": \\\"text/html\\\"}\\n        response.raise_for_status.return_value = None\\n        return response\\n\\n    @staticmethod\\n    def _page_response(body_length: int) -> Mock:\\n        response = Mock()\\n        response.text = f\\\"<html><body>{'a' * body_length}</body></html>\\\"\\n        response.raise_for_status.return_value = None\\n        return response\\n\\n    @patch.object(WebSearchComponent, \\\"_safe_get_url\\\")\\n    @patch(\\\"lfx.components.data_source.web_search.requests.get\\\")\\n    def test_should_cap_web_results_when_max_results_is_set(self, mock_get, mock_safe_get):\\n        \\\"\\\"\\\"Regression (LE-2164): the scrape loop must stop at max_results.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"test query\\\"\\n        component.timeout = 5\\n        component.max_results = 3\\n\\n        mock_get.return_value = self._serp_response(result_count=12)\\n        mock_safe_get.return_value = self._page_response(body_length=50)\\n\\n        result = component.perform_web_search()\\n\\n        assert len(result) == 3\\n        assert mock_safe_get.call_count == 3\\n\\n    @patch.object(WebSearchComponent, \\\"_safe_get_url\\\")\\n    @patch(\\\"lfx.components.data_source.web_search.requests.get\\\")\\n    def test_should_truncate_content_when_max_content_length_is_set(self, mock_get, mock_safe_get):\\n        \\\"\\\"\\\"Regression (LE-2164): scraped page text must never exceed max_content_length.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"test query\\\"\\n        component.timeout = 5\\n        component.max_content_length = 500\\n\\n        mock_get.return_value = self._serp_response(result_count=1)\\n        mock_safe_get.return_value = self._page_response(body_length=40_000)\\n\\n        result = component.perform_web_search()\\n\\n        content = result.iloc[0][\\\"content\\\"]\\n        assert len(content) <= 500\\n        assert content.endswith(\\\"... [truncated]\\\")\\n\\n    @pytest.mark.parametrize(\\\"limit\\\", range(1, len(TRUNCATION_SUFFIX)))\\n    def test_should_mark_truncated_content_when_limit_is_shorter_than_suffix(self, limit):\\n        \\\"\\\"\\\"Every positive content limit must retain a recognizable truncation marker.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n\\n        content = component._truncate_content(\\\"a\\\" * 100, limit)\\n\\n        assert len(content) == limit\\n        assert content.endswith(\\\"\u2026\\\")\\n\\n    def test_should_use_full_truncation_marker_at_suffix_length(self):\\n        \\\"\\\"\\\"The full marker fits exactly at its existing length boundary.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n\\n        content = component._truncate_content(\\\"a\\\" * 100, len(TRUNCATION_SUFFIX))\\n\\n        assert content == TRUNCATION_SUFFIX\\n        assert component._truncate_content(\\\"a\\\" * 100, len(TRUNCATION_SUFFIX) + 1) == f\\\"a{TRUNCATION_SUFFIX}\\\"\\n        assert component._truncate_content(\\\"a\\\" * len(TRUNCATION_SUFFIX), len(TRUNCATION_SUFFIX)) == \\\"a\\\" * len(\\n            TRUNCATION_SUFFIX\\n        )\\n\\n    @patch.object(WebSearchComponent, \\\"_safe_get_url\\\")\\n    @patch(\\\"lfx.components.data_source.web_search.requests.get\\\")\\n    def test_should_bound_payload_when_limits_are_absent(self, mock_get, mock_safe_get):\\n        \\\"\\\"\\\"Saved flows frozen before LE-2164 carry no limit fields; defaults must still bound them.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"Sample Slide Show\\\"\\n        component.timeout = 5\\n\\n        mock_get.return_value = self._serp_response(result_count=10)\\n        mock_safe_get.return_value = self._page_response(body_length=40_755)\\n\\n        result = component.perform_web_search()\\n\\n        total_chars = sum(len(str(value)) for row in result.to_dict(orient=\\\"records\\\") for value in row.values())\\n        assert len(result) == 5\\n        assert all(len(row[\\\"content\\\"]) <= 2000 for row in result.to_dict(orient=\\\"records\\\"))\\n        assert total_chars < 20_000\\n\\n    @patch.object(WebSearchComponent, \\\"_safe_get_url\\\")\\n    @patch(\\\"lfx.components.data_source.web_search.requests.get\\\")\\n    def test_should_keep_full_payload_when_limits_are_disabled(self, mock_get, mock_safe_get):\\n        \\\"\\\"\\\"Zero is the documented opt-out for both limits.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"test query\\\"\\n        component.timeout = 5\\n        component.set_attributes({\\\"max_results\\\": 0, \\\"max_content_length\\\": 0})\\n\\n        mock_get.return_value = self._serp_response(result_count=12)\\n        mock_safe_get.return_value = self._page_response(body_length=10_000)\\n\\n        result = component.perform_web_search()\\n\\n        assert len(result) == 12\\n        assert len(result.iloc[0][\\\"content\\\"]) == 10_000\\n\\n    @patch(\\\"lfx.components.data_source.web_search.requests.get\\\")\\n    def test_should_cap_news_results_when_max_results_is_set(self, mock_get):\\n        \\\"\\\"\\\"Regression (LE-2164): News mode also feeds the agent context and must be bounded.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"test news\\\"\\n        component.timeout = 5\\n        component.max_results = 4\\n\\n        items = \\\"\\\".join(\\n            f\\\"<item><title>News {i}</title><link>https://news.example.com/{i}</link>\\\"\\n            f\\\"<pubDate>Mon, 01 Jan 2024 00:00:00 GMT</pubDate><description>Body {i}</description></item>\\\"\\n            for i in range(30)\\n        )\\n        mock_response = Mock()\\n        mock_response.content = f'<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?><rss><channel>{items}</channel></rss>'.encode()\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        result = component.perform_news_search()\\n\\n        assert len(result) == 4\\n\\n    @patch(\\\"lfx.components.data_source.web_search.requests.get\\\")\\n    def test_should_bound_news_text_fields(self, mock_get):\\n        \\\"\\\"\\\"Every text field in a News item must honor max_content_length.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"test news\\\"\\n        component.timeout = 5\\n        component.max_results = 1\\n        component.max_content_length = 100\\n\\n        oversized = \\\"a\\\" * 100_000\\n        mock_response = Mock()\\n        mock_response.content = (\\n            '<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?><rss><channel><item>'\\n            f\\\"<title>{oversized}</title><link>https://example.com/{oversized}</link>\\\"\\n            f\\\"<pubDate>{oversized}</pubDate><description>{oversized}</description>\\\"\\n            \\\"</item></channel></rss>\\\"\\n        ).encode()\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        result = component.perform_news_search()\\n\\n        row = result.iloc[0]\\n        for field in (\\\"title\\\", \\\"link\\\", \\\"published\\\", \\\"summary\\\"):\\n            assert len(row[field]) == 100\\n            assert row[field].endswith(TRUNCATION_SUFFIX)\\n\\n    @patch.object(WebSearchComponent, \\\"_safe_get_url\\\")\\n    def test_should_cap_rss_items_when_max_results_is_set(self, mock_get):\\n        \\\"\\\"\\\"Regression (LE-2164): RSS mode must honour the same cap.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"https://example.com/feed.rss\\\"\\n        component.timeout = 5\\n        component.max_results = 2\\n\\n        items = \\\"\\\".join(\\n            f\\\"<item><title>Item {i}</title><link>https://example.com/{i}</link>\\\"\\n            f\\\"<pubDate>Mon, 01 Jan 2024 00:00:00 GMT</pubDate><description>Body {i}</description></item>\\\"\\n            for i in range(10)\\n        )\\n        mock_response = Mock()\\n        mock_response.content = f'<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?><rss><channel>{items}</channel></rss>'.encode()\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        result = component.perform_rss_read()\\n\\n        assert len(result) == 2\\n\\n    @patch.object(WebSearchComponent, \\\"_safe_get_url\\\")\\n    def test_should_bound_rss_text_fields(self, mock_get):\\n        \\\"\\\"\\\"A single oversized RSS item must not flood the caller's context window.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"https://example.com/feed.rss\\\"\\n        component.timeout = 5\\n        component.max_results = 1\\n        component.max_content_length = 100\\n\\n        oversized = \\\"a\\\" * 100_000\\n        mock_response = Mock()\\n        mock_response.content = (\\n            '<?xml version=\\\"1.0\\\" encoding=\\\"UTF-8\\\"?><rss><channel><item>'\\n            f\\\"<title>{oversized}</title><link>https://example.com/{oversized}</link>\\\"\\n            f\\\"<pubDate>{oversized}</pubDate><description>{oversized}</description>\\\"\\n            \\\"</item></channel></rss>\\\"\\n        ).encode()\\n        mock_response.raise_for_status.return_value = None\\n        mock_get.return_value = mock_response\\n\\n        result = component.perform_rss_read()\\n\\n        assert len(result) == 1\\n        row = result.iloc[0]\\n        fields = (\\\"title\\\", \\\"link\\\", \\\"published\\\", \\\"summary\\\")\\n        for field in fields:\\n            assert len(row[field]) == 100\\n            assert row[field].endswith(TRUNCATION_SUFFIX)\\n        assert sum(len(row[field]) for field in fields) <= 4 * 100\\n\\n    @pytest.mark.parametrize(\\n        (\\\"name\\\", \\\"default\\\"), [(\\\"max_results\\\", DEFAULT_MAX_RESULTS), (\\\"max_content_length\\\", DEFAULT_MAX_CONTENT_LENGTH)]\\n    )\\n    @pytest.mark.parametrize(\\\"invalid\\\", [None, \\\"\\\", \\\"not-a-number\\\", -1, -0.5, 0.5, False, True, float(\\\"inf\\\"), \\\"1e309\\\"])\\n    def test_should_normalize_invalid_limits_before_input_validation(self, name, default, invalid):\\n        \\\"\\\"\\\"Graph input binding must fall back safely instead of disabling or rejecting limits.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n\\n        component.set_attributes({name: invalid})\\n\\n        assert component._get_limit(name, default) == default\\n\\n    @pytest.mark.parametrize(\\\"zero\\\", [0, 0.0, \\\"0\\\"])\\n    def test_should_only_disable_limits_for_explicit_zero(self, zero):\\n        \\\"\\\"\\\"Numeric zero remains the sole supported opt-out after normal input binding.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n\\n        component.set_attributes({\\\"max_results\\\": zero})\\n\\n        assert component._get_limit(\\\"max_results\\\", DEFAULT_MAX_RESULTS) is None\\n\\n    @pytest.mark.parametrize(\\\"wrapped\\\", [Message(text=\\\"2\\\"), Data(text=\\\"2\\\")])\\n    def test_should_preserve_wrapped_integer_limits(self, wrapped):\\n        \\\"\\\"\\\"Component-specific normalization must preserve IntInput's Message/Data support.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n\\n        component.set_attributes({\\\"max_results\\\": wrapped})\\n\\n        assert component._get_limit(\\\"max_results\\\", DEFAULT_MAX_RESULTS) == 2\\n\\n    @pytest.mark.parametrize(\\\"name\\\", [\\\"max_results\\\", \\\"max_content_length\\\"])\\n    def test_should_reject_credential_variables_for_limits(self, name):\\n        \\\"\\\"\\\"Pre-normalization must preserve the global non-password credential guard.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        raw_secret = \\\"credential-sentinel\\\"  # noqa: S105  # pragma: allowlist secret\\n\\n        with pytest.raises(ValidationError) as excinfo:\\n            component.set_attributes({name: SecretStr(raw_secret)})\\n\\n        error_text = str(excinfo.value)\\n        assert \\\"Credential-typed global variable\\\" in error_text\\n        assert name in error_text\\n        assert raw_secret not in error_text\\n\\n    @patch.object(WebSearchComponent, \\\"_safe_get_url\\\")\\n    @patch(\\\"lfx.components.data_source.web_search.requests.get\\\")\\n    def test_should_fall_back_to_defaults_when_limits_are_invalid(self, mock_get, mock_safe_get):\\n        \\\"\\\"\\\"Tool-mode callers can pass strings/None; invalid limits must not crash the search.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.query = \\\"test query\\\"\\n        component.timeout = 5\\n        component.set_attributes({\\\"max_results\\\": \\\"not-a-number\\\", \\\"max_content_length\\\": None})\\n\\n        mock_get.return_value = self._serp_response(result_count=12)\\n        mock_safe_get.return_value = self._page_response(body_length=40_000)\\n\\n        result = component.perform_web_search()\\n\\n        assert len(result) == 5\\n        assert len(result.iloc[0][\\\"content\\\"]) <= 2000\\n\\n    @patch.object(WebSearchComponent, \\\"perform_web_search\\\")\\n    def test_perform_search_web_mode(self, mock_web_search):\\n        \\\"\\\"\\\"Test perform_search routes to web search in Web mode.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.search_mode = \\\"Web\\\"\\n\\n        mock_web_search.return_value = DataFrame(pd.DataFrame([{\\\"result\\\": \\\"web\\\"}]))\\n\\n        result = component.perform_search()\\n\\n        mock_web_search.assert_called_once()\\n        assert result.iloc[0][\\\"result\\\"] == \\\"web\\\"\\n\\n    @patch.object(WebSearchComponent, \\\"perform_news_search\\\")\\n    def test_perform_search_news_mode(self, mock_news_search):\\n        \\\"\\\"\\\"Test perform_search routes to news search in News mode.\\\"\\\"\\\"\\n        component = WebSearchComponent()\\n        component.search_mode = \\\"News\\\"\\n\\n        mock_news_search.return_value = DataFrame(pd.DataFrame([{\\\"result\\\": \\\"news\\\"}]))\\n\\n        result = component.perform_search()\\n\\n        mock_news_search.assert_called_once()\\n        assert result.iloc[0][\\\"result\\\"] == \\\"news\\\"\\n\\n    @patch.object(WebSearchComponent, \\\"perform_rss_read\\\")\\n    def test_perform_search_rss_mode(self, mock_rss_read):\\n        \\\"\\\"\\\"Test perform_search routes to RSS read in RSS mode.\\\"\\\"\\\"\\n        component = WebSearchCompo";
